#!/usr/bin/env python3
"""deploy_rulebook.py

Deterministic deploy filtering + report generation for OG.

Inputs:
  - A BOOKIE_IMP{XX}_ALLMARKETS_<date_from>_to_<date_to>.csv generated by bookie_allmarkets.py

Outputs (written next to the input file by default):
  - <input_stem>__DEPLOY_PRESET_V1.csv
  - <input_stem>__DEPLOY_PRESET_V1.md
  - DEPLOY_CANDIDATES_RAW.csv
  - DEPLOY_CANDIDATES_AFTER_GATES.csv

This script applies a market-specific rulebook (V1) with tunable params.
It is intentionally EV-free: it operates on bookie implied + model probabilities,
plus stability/structure features like ftr_margin and power_diff.

Notes:
  - Uses no-vig implieds when available (bookie_implied_novig), otherwise falls back to raw implied.
  - Uses gap_novig when available, otherwise gap = model_p_for_bookie - bookie_implied.
"""

