def _as_int_flag(v, default=0) -> int:
    try:
        if v is None:
            return int(default)
        if isinstance(v, str) and not v.strip():
            return int(default)
        return int(float(v))
    except Exception:
        return int(default)


def btts_yes_is_live(row) -> bool:
    league = str(row.get("league", "")).strip()

    if league in BTTS_YES_HARD_BLACKLIST:
        return False

    baseline_live = _as_int_flag(row.get("final_live_pass", 0), 0) == 1

    fts_override_live = (
        league in FTS_OVERRIDE_ALLOWED_LEAGUES
        and league not in BTTS_YES_BASELINE_ONLY_WATCHLIST
        and _as_int_flag(row.get("final_live_pass", 0), 0) == 0
        and _as_int_flag(row.get("fts_pass", 0), 0) == 0
        and _as_int_flag(row.get("label_pass", 0), 0) == 1
        and _as_int_flag(row.get("brazil_block", 0), 0) == 0
        and _as_int_flag(row.get("ge2_pass", 0), 0) == 1
        and _as_int_flag(row.get("model_floor_pass", 0), 0) == 1
        and _as_int_flag(row.get("cs_pass", 0), 0) == 1
        and _as_int_flag(row.get("double_blank_pass", 1), 1) == 1
        and _as_int_flag(row.get("confirmation_pass", 1), 1) == 1
    )

    return baseline_live or fts_override_live


def btts_yes_reason(row) -> str:
    league = str(row.get("league", "")).strip()

    if league in BTTS_YES_HARD_BLACKLIST:
        return "BTTS_YES_HARD_BLACKLIST"

    if _as_int_flag(row.get("final_live_pass", 0), 0) == 1:
        return "BTTS_YES_BASELINE_LIVE"

    if (
        league in FTS_OVERRIDE_ALLOWED_LEAGUES
        and league not in BTTS_YES_BASELINE_ONLY_WATCHLIST
        and _as_int_flag(row.get("final_live_pass", 0), 0) == 0
        and _as_int_flag(row.get("fts_pass", 0), 0) == 0
        and _as_int_flag(row.get("label_pass", 0), 0) == 1
        and _as_int_flag(row.get("brazil_block", 0), 0) == 0
        and _as_int_flag(row.get("ge2_pass", 0), 0) == 1
        and _as_int_flag(row.get("model_floor_pass", 0), 0) == 1
        and _as_int_flag(row.get("cs_pass", 0), 0) == 1
        and _as_int_flag(row.get("double_blank_pass", 1), 1) == 1
        and _as_int_flag(row.get("confirmation_pass", 1), 1) == 1
    ):
        return "BTTS_YES_FTS_OVERRIDE"

    return "BTTS_YES_NOT_LIVE"
