def _league_override_threshold_series(
    league: pd.Series,
    overrides: Dict[str, Dict[str, float]],
    key: str,
    default: float,
) -> pd.Series:
    league_series = league.astype("string").fillna("").str.strip()
    return league_series.map(
        lambda lg: float(overrides.get(str(lg), {}).get(key, default))
    ).astype("float64")


def _ou25_struct_combo_mask(df: pd.DataFrame) -> pd.Series:
    out = _stamp_ou25_runtime_fields(df)
    out = _stamp_ou25_over_live_features(out)

    avg_btts = pd.to_numeric(out.get("avg_btts_rate", np.nan), errors="coerce")
    cs_mass = pd.to_numeric(out.get("cs_over25_mass", np.nan), errors="coerce")
    league = out.get("league", pd.Series("", index=out.index))

    avg_floor = _league_override_threshold_series(
        league,
        OU25_OVER25_STRUCT_COMBO_LEAGUE_OVERRIDES,
        "avg_btts_min",
        0.50,
    )
    cs_floor = _league_override_threshold_series(
        league,
        OU25_OVER25_STRUCT_COMBO_LEAGUE_OVERRIDES,
        "cs_mass_min",
        0.15,
    )
    return avg_btts.ge(avg_floor) & cs_mass.ge(cs_floor)


def _ou25_top3_mask(df: pd.DataFrame) -> pd.Series:
    out = _stamp_ou25_runtime_fields(df)
    out = _stamp_ou25_over_live_features(out)

    top3_over = pd.to_numeric(out.get("top3_over_count", np.nan), errors="coerce")
    league = out.get("league", pd.Series("", index=out.index))
    top3_floor = _league_override_threshold_series(
        league,
        OU25_OVER25_TOP3_LEAGUE_OVERRIDES,
        "top3_over_count_min",
        2.0,
    )
    return top3_over.ge(top3_floor)

def _load_deploy_gates_ftr_csv(path: str) -> dict:
    """Load per-league FTR gates from DEPLOY_GATES_FTR.csv.

    Returns dict: league -> {min_conf, min_margin, status}
    """
    try:
        p = Path(path)
        if not p.exists():
            return {}
        g = pd.read_csv(p)
        if g is None or g.empty or "league" not in g.columns:
            return {}

        def _f(x, default=np.nan):
            try:
                v = float(pd.to_numeric(x, errors="coerce"))
            except Exception:
                v = float("nan")
            if not np.isfinite(v):
                return default
            return float(v)

        out = {}
        for _, r in g.iterrows():
            lg = str(r.get("league", "")).strip()
            if not lg:
                continue
            min_conf = _f(r.get("ftr_gate_min_conf"), default=0.0)
            min_margin = _f(r.get("ftr_gate_min_margin"), default=0.0)
            status = str(r.get("status", r.get("status_margin", ""))).strip() or ""
            # If status_margin exists and is non-empty, prefer it
            sm = str(r.get("status_margin", "")).strip()
            if sm:
                status = sm
            out[lg] = {
                "min_conf": float(0.0 if not np.isfinite(min_conf) else min_conf),
                "min_margin": float(0.0 if not np.isfinite(min_margin) else min_margin),
                "status": status,
            }
        return out
    except Exception:
        return {}


def _load_league_weighting_policy(path: str) -> dict:
    """Load league-weighted threshold policy JSON (if present)."""
    if not path:
        return {}
    try:
        p = Path(path)
        if not p.exists():
            return {}
        import json
        with open(p, "r", encoding="utf-8") as fh:
            return json.load(fh)
    except Exception:
        return {}


def _league_tag(league: str) -> str:
    return str(league).strip().replace(" ", "_").replace("-", "_")


def _load_base_market_threshold(league: str) -> float | None:
    """Load base ftr threshold from ModelStore/<LeagueTag>/market_thresholds.json if present."""
    try:
        tag = _league_tag(league)
        p = Path("ModelStore") / tag / "market_thresholds.json"
        if p.exists():
            import json
            return float(json.load(open(p, "r", encoding="utf-8")).get("ftr"))
    except Exception:
        return None
    return None


def _apply_league_weighting_to_ftr_gates(ftr_gates: dict, policy_path: str) -> dict:
    """Override per-league min_conf using league-weighting policy JSON."""
    if not ftr_gates:
        ftr_gates = {}
    policy = _load_league_weighting_policy(policy_path)
    if not policy:
        return ftr_gates

    leagues = policy.get("leagues", {}) if isinstance(policy, dict) else {}
    for lg, info in leagues.items():
        if not isinstance(info, dict):
            continue
        suggested = info.get("suggested_ftr_threshold")
        if suggested is None:
            suggested = _load_base_market_threshold(lg)
        if suggested is None:
            continue
        min_margin = float(ftr_gates.get(str(lg), {}).get("min_margin", 0.0))
        ftr_gates[str(lg)] = {
            "min_conf": float(suggested),
            "min_margin": min_margin,
            "status": str(ftr_gates.get(str(lg), {}).get("status", "OK") or "OK"),
        }
    return ftr_gates


def _load_deploy_gates_side_csv(path: str) -> dict:
    """Load per-league side-market gates from DEPLOY_GATES_SIDE.csv.

    Returns dict keyed by "<league>||<market>":
      {"labels": set(str), "status": str, "hit_rate": float, "n": int}

    Note: markets are expected in {over25, under25, btts, btts_no}.
    """
    try:
        p = Path(path)
        if not p.exists():
            return {}
        g = pd.read_csv(p)
        if g is None or g.empty or "league" not in g.columns or "market" not in g.columns:
            return {}

        def _labels(s: object) -> set:
            if s is None:
                return set()
            txt = str(s).strip()
            if not txt:
                return set()
            # e.g. "VERY_STRONG_OVER,STRONG_OVER"
            return {t.strip().upper() for t in txt.split(",") if t.strip()}

        out = {}
        for _, r in g.iterrows():
            lg = str(r.get("league", "")).strip()
            mk = str(r.get("market", "")).strip().lower()
            if not lg or not mk:
                continue
            key = f"{lg}||{mk}"
            out[key] = {
                "labels": _labels(r.get("allowed_labels", "")),
                "status": str(r.get("status", "")).strip(),
                "hit_rate": float(pd.to_numeric(r.get("hit_rate", np.nan), errors="coerce")),
                "n": int(pd.to_numeric(r.get("n", 0), errors="coerce") or 0),
            }
        return out
    except Exception:
        return {}


@lru_cache(maxsize=4)
def _load_phase9b_premium_ge2_rule_draft_csv(path: str) -> pd.DataFrame:
    """Load frozen Phase 9B premium GE2 rule draft rows."""
    try:
        p = Path(path)
        if not p.exists():
            return pd.DataFrame()
        df = pd.read_csv(p)
        if df is None or df.empty:
            return pd.DataFrame()
        need = {"market", "selection", "league", "allowlist_side", "team_name"}
        if not need.issubset(df.columns):
            return pd.DataFrame()
        out = df.copy()
        for col in [
            "market",
            "selection",
            "league",
            "allowlist_side",
            "team_name",
            "team_match_column",
            "required_value_edge_tier",
            "required_team_context_filter_family",
            "promote_to_deploy_tier",
            "reason_token",
            "policy_status",
        ]:
            if col not in out.columns:
                out[col] = ""
            out[col] = out[col].astype("string").fillna("").str.strip()
        for col in ["raw_model_prob_floor", "corrected_model_prob_floor"]:
            if col not in out.columns:
                out[col] = np.nan
            out[col] = pd.to_numeric(out[col], errors="coerce")
        return out
    except Exception:
        return pd.DataFrame()


@lru_cache(maxsize=4)
def _load_phase9b_league_correction_table_csv(path: str) -> dict:
    """Load league-style correction multipliers keyed by (study, league)."""
    try:
        p = Path(path)
        if not p.exists():
            return {}
        df = pd.read_csv(p)
        if df is None or df.empty or "study" not in df.columns or "league" not in df.columns:
            return {}
        out: dict[tuple[str, str], float] = {}
        for _, r in df.iterrows():
            study = str(r.get("study", "")).strip().upper()
            league = str(r.get("league", "")).strip()
            mult = pd.to_numeric(pd.Series([r.get("correction_multiplier")]), errors="coerce").iloc[0]
            if not study or not league or not pd.notna(mult):
                continue
            out[(study, league)] = float(mult)
        return out
    except Exception:
        return {}


