@lru_cache(maxsize=8)
def _load_phase10a_team_intel_context_policy_csv(path: str) -> pd.DataFrame:
    """Load non-destructive Team Intel overlay policy rows for slip ranking."""
    try:
        p = Path(path)
        if not p.exists():
            return pd.DataFrame()
        df = pd.read_csv(p)
        if df is None or df.empty:
            return pd.DataFrame()
        need = {"market", "team_fixture_interaction", "team_context_filter_family"}
        if not need.issubset(df.columns):
            return pd.DataFrame()
        out = df.copy()
        for col in [
            "market",
            "team_fixture_interaction",
            "team_context_filter_family",
            "overlay_action",
            "policy_bucket",
            "notes",
        ]:
            if col not in out.columns:
                out[col] = ""
            out[col] = out[col].astype("string").fillna("").str.strip()
        for col in [
            "rank_uplift_bps",
            "rank_penalty_bps",
            "market_fit_score",
        ]:
            if col not in out.columns:
                out[col] = np.nan
            out[col] = pd.to_numeric(out[col], errors="coerce")
        for col in [
            "premium_tag_allowed",
            "slip_caution_flag",
            "avoid_in_acca_flag",
        ]:
            if col not in out.columns:
                out[col] = 0
            out[col] = pd.to_numeric(out[col], errors="coerce").fillna(0).astype(int)
        out["market"] = out["market"].astype("string").fillna("").str.lower().str.strip()
        out["team_fixture_interaction"] = out["team_fixture_interaction"].astype("string").fillna("OTHER").str.upper().str.strip()
        out["team_context_filter_family"] = out["team_context_filter_family"].astype("string").fillna("GENERAL").str.upper().str.strip()
        return out
    except Exception:
        return pd.DataFrame()


def _apply_team_intel_overlay_policy(
    df: pd.DataFrame,
    *,
    ftr_policy_path: str = "",
    ou25_policy_path: str = "",
    btts_policy_path: str = "",
    debug: bool = False,
) -> pd.DataFrame:
    """Stamp non-destructive Team Intel overlay fields for downstream slip ranking.

    This is intentionally informational only. It never removes rows, changes tiers,
    or blocks deploy outputs. The overlay fields are consumed later by
    `slip_formatter.py` when ranking legs for larger accas.
    """
    if not isinstance(df, pd.DataFrame):
        return df

    out = _normalize_team_context_fields(df.copy())
    if out.empty:
        for col, default in [
            ("team_intel_overlay_active_flag", 0),
            ("team_intel_overlay_policy_bucket", ""),
            ("team_intel_overlay_action", ""),
            ("team_intel_overlay_rank_uplift_bps", 0.0),
            ("team_intel_overlay_rank_penalty_bps", 0.0),
            ("team_intel_overlay_slip_caution_flag", 0),
            ("team_intel_overlay_avoid_in_acca_flag", 0),
            ("team_intel_overlay_premium_tag_flag", 0),
            ("team_intel_overlay_market_fit_score", np.nan),
            ("team_intel_overlay_reason", ""),
        ]:
            if col not in out.columns:
                out[col] = default
        return out

    ftr_path = str(ftr_policy_path or PHASE10A_FTR_TEAM_INTEL_CONTEXT_POLICY_DEFAULT)
    ou25_path = str(ou25_policy_path or PHASE10A_OU25_TEAM_INTEL_CONTEXT_POLICY_DEFAULT)
    btts_path = str(btts_policy_path or PHASE10A_BTTS_TEAM_INTEL_CONTEXT_POLICY_DEFAULT)
    policy = pd.concat(
        [
            _load_phase10a_team_intel_context_policy_csv(ftr_path),
            _load_phase10a_team_intel_context_policy_csv(ou25_path),
            _load_phase10a_team_intel_context_policy_csv(btts_path),
        ],
        axis=0,
        ignore_index=True,
    )

    if policy.empty:
        for col, default in [
            ("team_intel_overlay_active_flag", 0),
            ("team_intel_overlay_policy_bucket", ""),
            ("team_intel_overlay_action", ""),
            ("team_intel_overlay_rank_uplift_bps", 0.0),
            ("team_intel_overlay_rank_penalty_bps", 0.0),
            ("team_intel_overlay_slip_caution_flag", 0),
            ("team_intel_overlay_avoid_in_acca_flag", 0),
            ("team_intel_overlay_premium_tag_flag", 0),
            ("team_intel_overlay_market_fit_score", np.nan),
            ("team_intel_overlay_reason", ""),
        ]:
            if col not in out.columns:
                out[col] = default
        return out

    out["__team_intel_market_norm"] = out.get("market", pd.Series("", index=out.index)).astype("string").fillna("").str.lower().str.strip()
    out["__team_intel_interaction_norm"] = out.get("team_fixture_interaction", pd.Series("OTHER", index=out.index)).astype("string").fillna("OTHER").str.upper().str.strip()
    out["__team_intel_filter_norm"] = out.get("team_context_filter_family", pd.Series("GENERAL", index=out.index)).astype("string").fillna("GENERAL").str.upper().str.strip()

    policy = policy.rename(
        columns={
            "market": "__team_intel_market_norm",
            "team_fixture_interaction": "__team_intel_interaction_norm",
            "team_context_filter_family": "__team_intel_filter_norm",
        }
    )

    out = out.merge(
        policy,
        on=["__team_intel_market_norm", "__team_intel_interaction_norm", "__team_intel_filter_norm"],
        how="left",
    )

    out["team_intel_overlay_active_flag"] = out["overlay_action"].notna().astype(int)
    out["team_intel_overlay_policy_bucket"] = out.get("policy_bucket", pd.Series("", index=out.index)).astype("string").fillna("").str.strip()
    out["team_intel_overlay_action"] = out.get("overlay_action", pd.Series("", index=out.index)).astype("string").fillna("").str.upper().str.strip()
    out["team_intel_overlay_rank_uplift_bps"] = pd.to_numeric(out.get("rank_uplift_bps", pd.Series(0, index=out.index)), errors="coerce").fillna(0.0)
    out["team_intel_overlay_rank_penalty_bps"] = pd.to_numeric(out.get("rank_penalty_bps", pd.Series(0, index=out.index)), errors="coerce").fillna(0.0)
    out["team_intel_overlay_slip_caution_flag"] = pd.to_numeric(out.get("slip_caution_flag", pd.Series(0, index=out.index)), errors="coerce").fillna(0).astype(int)
    out["team_intel_overlay_avoid_in_acca_flag"] = pd.to_numeric(out.get("avoid_in_acca_flag", pd.Series(0, index=out.index)), errors="coerce").fillna(0).astype(int)
    out["team_intel_overlay_premium_tag_flag"] = pd.to_numeric(out.get("premium_tag_allowed", pd.Series(0, index=out.index)), errors="coerce").fillna(0).astype(int)
    out["team_intel_overlay_market_fit_score"] = pd.to_numeric(out.get("market_fit_score", pd.Series(np.nan, index=out.index)), errors="coerce")

    _policy_bucket = out["team_intel_overlay_policy_bucket"].replace("", pd.NA)
    _notes = out.get("notes", pd.Series("", index=out.index)).astype("string").fillna("").str.strip().replace("", pd.NA)
    _action = out["team_intel_overlay_action"].replace("", pd.NA)
    _reason = _policy_bucket.fillna(_action)
    _reason = _reason.where(_notes.isna(), _reason.fillna("").astype("string").str.strip() + ": " + _notes.fillna("").astype("string").str.strip())
    out["team_intel_overlay_reason"] = _reason.fillna("").astype("string")

    try:
        if "context_reason_codes" not in out.columns:
            out["context_reason_codes"] = ""
        out["context_reason_codes"] = out["context_reason_codes"].astype("string").fillna("")
        _append_reason_token(
            out,
            "context_reason_codes",
            out["team_intel_overlay_action"].eq("UPLIFT"),
            "TEAM_INTEL_UPLIFT",
        )
        _append_reason_token(
            out,
            "context_reason_codes",
            out["team_intel_overlay_slip_caution_flag"].eq(1),
            "TEAM_INTEL_CAUTION",
        )
        _append_reason_token(
            out,
            "context_reason_codes",
            out["team_intel_overlay_avoid_in_acca_flag"].eq(1),
            "TEAM_INTEL_AVOID_IN_ACCA",
        )
    except Exception:
        pass

    if debug:
        try:
            active = out.loc[out["team_intel_overlay_active_flag"].eq(1)].copy()
            if not active.empty:
                summary = (
                    active.groupby(
                        [
                            "__team_intel_market_norm",
                            "team_intel_overlay_action",
                            "team_intel_overlay_policy_bucket",
                        ],
                        dropna=False,
                    )
                    .size()
                    .reset_index(name="rows")
                )
                print("[deploy_rulebook] Team Intel overlay summary:", summary.to_dict(orient="records"))
        except Exception:
            pass

    return out.drop(
        columns=[
            "__team_intel_market_norm",
            "__team_intel_interaction_norm",
            "__team_intel_filter_norm",
            "overlay_action",
            "rank_uplift_bps",
            "rank_penalty_bps",
            "premium_tag_allowed",
            "slip_caution_flag",
            "avoid_in_acca_flag",
            "market_fit_score",
            "policy_bucket",
            "notes",
        ],
        errors="ignore",
    )


def _apply_learned_deploy_gates(df: pd.DataFrame, *, ftr_gates: dict, side_gates: dict, debug: bool = False) -> pd.DataFrame:
    """Filter an ALLMARKETS dataframe using learned deploy gates.

    - FTR: per-league min_conf (on model_p_for_bookie) and min_margin (on ftr_margin)
    - OU25: uses signal_over25 labels, keyed by (league, over25|under25) inferred from bookie_pick
    - BTTS: uses signal_btts labels, keyed by (league, btts|btts_no) inferred from bookie_pick

    TG markets are left untouched (no odds/labels).
    """
    if df is None or df.empty:
        return df

    out = df.copy()

    # Optional BTTS gate audit (YES pipeline only)
    _init_btts_gate_audit_state(params)
    _init_ou25_gate_audit_state(params)

    # Normalize core fields
    out["market"] = out.get("market", pd.Series("", index=out.index)).astype(str).str.lower().str.strip()
    out["league"] = out.get("league", pd.Series("", index=out.index)).astype(str).str.strip()
    out["bookie_pick"] = out.get(
        "bookie_pick",
        out.get("selection", pd.Series("", index=out.index)),
    ).astype(str).str.upper().str.strip()

    # --- FTR gate ---
    is_ftr = out["market"].eq("ftr")
    conf = pd.to_numeric(out.get("model_p_for_bookie", out.get("confidence", np.nan)), errors="coerce")
    margin = pd.to_numeric(out.get("ftr_margin", np.nan), errors="coerce")

    # Map per-league thresholds (defaults to 0.0 if missing)
    min_conf_s = out["league"].map(lambda lg: float(ftr_gates.get(str(lg), {}).get("min_conf", 0.0))).fillna(0.0)
    min_margin_s = out["league"].map(lambda lg: float(ftr_gates.get(str(lg), {}).get("min_margin", 0.0))).fillna(0.0)

    # Expose for downstream transparency
    out["ftr_gate_min_conf"] = np.where(is_ftr, min_conf_s, np.nan)
    out["ftr_gate_min_margin"] = np.where(is_ftr, min_margin_s, np.nan)

    # If margin is missing (older files), treat it as 0.0 so margin gates behave deterministically
    margin0 = margin.fillna(0.0)
    conf0 = conf.fillna(-1.0)

    keep_ftr = (~is_ftr) | ((conf0 >= min_conf_s) & (margin0 >= min_margin_s))

    # --- Side gates via signal labels ---
    # Build a derived side-market key for gating: over25/under25, btts/btts_no
    mk = out["market"]
    pick = out["bookie_pick"]

    gate_market = pd.Series("", index=out.index, dtype="string")

    # OU25 rows (in ALLMARKETS they are market='ou25' and bookie_pick is OVER25/UNDER25)
    is_ou = mk.eq("ou25")
    gate_market = gate_market.mask(is_ou & pick.eq("OVER25"), "over25")
    gate_market = gate_market.mask(is_ou & pick.eq("UNDER25"), "under25")

    # BTTS rows (market='btts' with pick YES/NO)
    is_btts = mk.eq("btts")
    gate_market = gate_market.mask(is_btts & pick.eq("YES"), "btts")
    gate_market = gate_market.mask(is_btts & pick.eq("NO"), "btts_no")

    # Only apply side gates where we have an inferred gate_market
    is_side = gate_market.ne("")

    sig_over = _normalize_signal_label_series(_get_ou25_signal_series(out, default=""), default="")
    sig_btts = _normalize_signal_label_series(_get_btts_signal_series(out, default=""), default="")

    def _row_side_ok(i: int) -> bool:
        if not bool(is_side.iloc[i]):
            return True
        lg = str(out["league"].iloc[i]).strip()
        gm = str(gate_market.iloc[i]).strip().lower()
        if not lg or not gm:
            return False
        key = f"{lg}||{gm}"
        info = side_gates.get(key)
        if not isinstance(info, dict):
            return False
        labels = _normalize_allowed_labels(info.get("labels"))
        if not labels:
            return False
        status = str(info.get("status", "")).strip().upper()
        if status.startswith("SKIP"):
            return False
        lbl = str(sig_over.iloc[i] if gm in ("over25", "under25") else sig_btts.iloc[i]).strip()
        return lbl in labels

    if bool(is_side.any()):
        keep_side = pd.Series([_row_side_ok(i) for i in range(len(out))], index=out.index)
    else:
        keep_side = pd.Series(True, index=out.index)

    before = len(out)
    out = out[keep_ftr & keep_side].copy()

    if bool(debug):
        try:
            if ("signal_over25" not in df.columns) and ("signal_ou25" in df.columns):
                print("[deploy_rulebook] legacy OU25 signal column detected: using signal_ou25 fallback")

            print(f"[deploy_rulebook] learned_gates: kept {len(out)}/{before}")

            # --- market counts (before vs after) ---
            try:
                m_before = df.get("market", pd.Series("", index=df.index)).astype(str).str.lower().str.strip()
                m_after = out.get("market", pd.Series("", index=out.index)).astype(str).str.lower().str.strip()
                print("[deploy_rulebook] learned_gates market_before:", m_before.value_counts(dropna=False).to_dict())
                print("[deploy_rulebook] learned_gates market_after: ", m_after.value_counts(dropna=False).to_dict())
            except Exception:
                pass

            # --- league counts (before vs after) ---
            try:
                l_before = df.get("league", pd.Series("", index=df.index)).astype(str).str.strip()
                l_after = out.get("league", pd.Series("", index=out.index)).astype(str).str.strip()
                print("[deploy_rulebook] learned_gates league_before(top20):", l_before.value_counts(dropna=False).head(20).to_dict())
                print("[deploy_rulebook] learned_gates league_after(top20): ", l_after.value_counts(dropna=False).head(20).to_dict())
            except Exception:
                pass

            # --- FTR gate diagnostic ---
            try:
                if bool(is_ftr.any()):
                    ftr_before_n = int(is_ftr.sum())
                    ftr_after_n = int(out.get("market", pd.Series("", index=out.index)).astype(str).str.lower().eq("ftr").sum())

                    # How many FTR rows failed conf/margin
                    ftr_fail = is_ftr & ~((conf0 >= min_conf_s) & (margin0 >= min_margin_s))
                    ftr_fail_n = int(ftr_fail.sum())

                    # League-level breakdown of FTR fails (top 15)
                    fail_by_league = (
                        out.copy()
                    )
                    # Use original df rows for fail breakdown to avoid losing dropped leagues
                    try:
                        df_ftr = df.copy()
                        df_ftr["market"] = df_ftr.get("market", pd.Series("", index=df_ftr.index)).astype(str).str.lower().str.strip()
                        df_ftr["league"] = df_ftr.get("league", pd.Series("", index=df_ftr.index)).astype(str).str.strip()
                        df_is_ftr = df_ftr["market"].eq("ftr")
                        df_conf0 = pd.to_numeric(df_ftr.get("model_p_for_bookie", df_ftr.get("confidence", np.nan)), errors="coerce").fillna(-1.0)
                        df_margin0 = pd.to_numeric(df_ftr.get("ftr_margin", np.nan), errors="coerce").fillna(0.0)
                        df_min_conf = df_ftr["league"].map(lambda lg: float(ftr_gates.get(str(lg), {}).get("min_conf", 0.0))).fillna(0.0)
                        df_min_margin = df_ftr["league"].map(lambda lg: float(ftr_gates.get(str(lg), {}).get("min_margin", 0.0))).fillna(0.0)
                        df_fail = df_is_ftr & ~((df_conf0 >= df_min_conf) & (df_margin0 >= df_min_margin))
                        if bool(df_fail.any()):
                            top_fail = df_ftr.loc[df_fail, "league"].value_counts().head(15).to_dict()
                        else:
                            top_fail = {}
                    except Exception:
                        top_fail = {}

                    print(f"[deploy_rulebook] learned_gates FTR before={ftr_before_n} after={ftr_after_n} failed={ftr_fail_n}")
                    if top_fail:
                        print("[deploy_rulebook] learned_gates FTR fails by league(top15):", top_fail)
            except Exception:
                pass

            # --- Side gate diagnostic (OU25/BTTS) ---
            try:
                if bool(is_side.any()):
                    # Use original df for before counts
                    df_m = df.copy()
                    df_m["market"] = df_m.get("market", pd.Series("", index=df_m.index)).astype(str).str.lower().str.strip()
                    df_m["league"] = df_m.get("league", pd.Series("", index=df_m.index)).astype(str).str.strip()
                    df_m["bookie_pick"] = df_m.get(
                        "bookie_pick",
                        df_m.get("selection", pd.Series("", index=df_m.index)),
                    ).astype(str).str.upper().str.strip()

                    mk0 = df_m["market"]
                    pk0 = df_m["bookie_pick"]

                    gm0 = pd.Series("", index=df_m.index, dtype="string")
                    is_ou0 = mk0.eq("ou25")
                    gm0 = gm0.mask(is_ou0 & pk0.eq("OVER25"), "over25")
                    gm0 = gm0.mask(is_ou0 & pk0.eq("UNDER25"), "under25")
                    is_btts0 = mk0.eq("btts")
                    gm0 = gm0.mask(is_btts0 & pk0.eq("YES"), "btts")
                    gm0 = gm0.mask(is_btts0 & pk0.eq("NO"), "btts_no")

                    side_before = int((gm0 != "").sum())

                    out_m = out.copy()
                    out_m["market"] = out_m.get("market", pd.Series("", index=out_m.index)).astype(str).str.lower().str.strip()
                    out_m["bookie_pick"] = out_m.get(
                        "bookie_pick",
                        out_m.get("selection", pd.Series("", index=out_m.index)),
                    ).astype(str).str.upper().str.strip()
                    mk1 = out_m["market"]
                    pk1 = out_m["bookie_pick"]
                    gm1 = pd.Series("", index=out_m.index, dtype="string")
                    is_ou1 = mk1.eq("ou25")
                    gm1 = gm1.mask(is_ou1 & pk1.eq("OVER25"), "over25")
                    gm1 = gm1.mask(is_ou1 & pk1.eq("UNDER25"), "under25")
                    is_btts1 = mk1.eq("btts")
                    gm1 = gm1.mask(is_btts1 & pk1.eq("YES"), "btts")
                    gm1 = gm1.mask(is_btts1 & pk1.eq("NO"), "btts_no")
                    side_after = int((gm1 != "").sum())

                    # breakdown by derived side market
                    print(f"[deploy_rulebook] learned_gates SIDE before={side_before} after={side_after}")
                    print("[deploy_rulebook] learned_gates SIDE by gate_market(before):", gm0.value_counts(dropna=False).to_dict())
                    print("[deploy_rulebook] learned_gates SIDE by gate_market(after): ", gm1.value_counts(dropna=False).to_dict())

                    # League-level failures for side rows (top 15)
                    # Identify fails as those with inferred gm but not present after filtering
                    try:
                        df_m["__jk"] = df_m["league"].astype(str) + "||" + gm0.astype(str)
                        # keep only rows with a gate market
                        cand = df_m[gm0 != ""].copy()
                        if not cand.empty:
                            # approximate fail count as those whose (league,fixture_key,market,bookie_pick) aren't in out
                            key_cols = [c for c in ("league","fixture_key","market","bookie_pick") if c in cand.columns and c in out.columns]
                            if key_cols:
                                cand_keys = cand[key_cols].astype(str).agg("|".join, axis=1)
                                out_keys = out[key_cols].astype(str).agg("|".join, axis=1)
                                miss = ~cand_keys.isin(set(out_keys.tolist()))
                                top_side_fail = cand.loc[miss, "league"].value_counts().head(15).to_dict() if bool(miss.any()) else {}
                            else:
                                top_side_fail = {}
                        else:
                            top_side_fail = {}
                    except Exception:
                        top_side_fail = {}

                    if top_side_fail:
                        print("[deploy_rulebook] learned_gates SIDE fails by league(top15):", top_side_fail)
            except Exception:
                pass

        except Exception:
            pass

    return out


def _stamp_ftr_priority(df: pd.DataFrame) -> pd.DataFrame:
    """Add FTR priority tier based on Cat vs XGB consensus.

    Priority order:
      3 = CONSENSUS_ELITE (Cat == XGB)
      2 = CAT_ELITE (Cat only / no XGB consensus)
      1 = STANDARD (non-FTR rows)
    """
    if df is None or df.empty:
        return df
    out = df.copy()
    mk = out.get("market", pd.Series("", index=out.index)).astype("string").fillna("").str.lower().str.strip()
    is_ftr = mk.eq("ftr")

    if "ftr_priority" not in out.columns:
        out["ftr_priority"] = ""
    if "ftr_priority_tier" not in out.columns:
        out["ftr_priority_tier"] = ""
    if "ftr_priority_rank" not in out.columns:
        out["ftr_priority_rank"] = 1

    if not bool(is_ftr.any()):
        return out

    cat = out.get("model_top_pick", out.get("selection", "")).astype("string").fillna("").str.upper().str.strip()
    xgb = out.get("ftr_pick_xgb", out.get("model_top_pick_xgb", "")).astype("string").fillna("").str.upper().str.strip()

    consensus = is_ftr & (cat != "") & (xgb != "") & cat.eq(xgb)
    cat_only = is_ftr & (~consensus)

    out.loc[consensus, "ftr_priority"] = "CONSENSUS_ELITE"
    out.loc[consensus, "ftr_priority_tier"] = "CONSENSUS_ELITE"
    out.loc[consensus, "ftr_priority_rank"] = 3

    out.loc[cat_only, "ftr_priority"] = "CAT_ELITE"
    out.loc[cat_only, "ftr_priority_tier"] = "CAT_ELITE"
    out.loc[cat_only, "ftr_priority_rank"] = 2

    out.loc[~is_ftr, "ftr_priority"] = "STANDARD"
    out.loc[~is_ftr, "ftr_priority_tier"] = "STANDARD"
    out.loc[~is_ftr, "ftr_priority_rank"] = 1

    return out


def _stamp_btts_priority(df: pd.DataFrame) -> pd.DataFrame:
    """Add BTTS priority tier based on routed consensus labels.

    Priority order:
      3 = CONSENSUS_ELITE
      2 = CAT_ELITE
      1 = STANDARD (non-BTTS rows)
    """
    if df is None or df.empty:
        return df
    out = df.copy()
    mk = out.get("market", pd.Series("", index=out.index)).astype("string").fillna("").str.lower().str.strip()
    is_btts = mk.eq("btts")

    if "btts_priority" not in out.columns:
        out["btts_priority"] = ""
    if "btts_priority_tier" not in out.columns:
        out["btts_priority_tier"] = ""
    if "btts_priority_rank" not in out.columns:
        out["btts_priority_rank"] = 1

    if not bool(is_btts.any()):
        return out

    routed = out.get("btts_priority", pd.Series("", index=out.index)).astype("string").fillna("").str.upper().str.strip()
    cat = out.get("model_top_pick", out.get("selection", "")).astype("string").fillna("").str.upper().str.strip()
    xgb = out.get("btts_pick_xgb", out.get("model_top_pick_xgb", "")).astype("string").fillna("").str.upper().str.strip()

    inferred_consensus = is_btts & (cat != "") & (xgb != "") & cat.eq(xgb)
    explicit_consensus = is_btts & routed.eq("CONSENSUS_ELITE")
    consensus = explicit_consensus | inferred_consensus
    cat_only = is_btts & (~consensus)

    out.loc[consensus, "btts_priority"] = "CONSENSUS_ELITE"
    out.loc[consensus, "btts_priority_tier"] = "CONSENSUS_ELITE"
    out.loc[consensus, "btts_priority_rank"] = 3

    out.loc[cat_only, "btts_priority"] = "CAT_ELITE"
    out.loc[cat_only, "btts_priority_tier"] = "CAT_ELITE"
    out.loc[cat_only, "btts_priority_rank"] = 2

    out.loc[~is_btts, "btts_priority"] = "STANDARD"
    out.loc[~is_btts, "btts_priority_tier"] = "STANDARD"
    out.loc[~is_btts, "btts_priority_rank"] = 1

    return out


def _stamp_phase7c_cross_market_candidates(df: pd.DataFrame) -> pd.DataFrame:
    """Stamp audit-only cross-market consensus rescue candidates.

    This does not change deploy tiers yet. It only adds stable candidate flags
    and supporting fields so Phase 7C can be audited before any live promotion.
    """
    if df is None or df.empty:
        return df
    out = df.copy()

    mk = out.get("market", pd.Series("", index=out.index)).astype("string").fillna("").str.lower().str.strip()
    sel = out.get("selection", out.get("bookie_pick", pd.Series("", index=out.index))).astype("string").fillna("").str.upper().str.strip()
    league = out.get("league", pd.Series("", index=out.index)).astype("string").fillna("").str.strip()

    # Ensure support columns exist even when older files are loaded.
    default_str = [
        "support_btts_priority", "support_btts_pick", "support_btts_signal",
        "support_ou25_priority", "support_ou25_pick", "support_ou25_signal",
    ]
    default_num = [
        "support_btts_priority_rank", "support_btts_model_p", "support_btts_model_p_xgb", "support_btts_consensus_flag",
        "support_ou25_priority_rank", "support_ou25_model_p", "support_ou25_model_p_xgb", "support_ou25_consensus_flag",
    ]
    for c in default_str:
        if c not in out.columns:
            out[c] = pd.Series("", index=out.index, dtype="string")
        else:
            out[c] = out[c].astype("string").fillna("").str.strip()
    for c in default_num:
        if c not in out.columns:
            out[c] = 0 if c.endswith("_flag") or c.endswith("_rank") else np.nan
        if c.endswith("_flag") or c.endswith("_rank"):
            out[c] = pd.to_numeric(out[c], errors="coerce").fillna(0).astype(int)
        else:
            out[c] = pd.to_numeric(out[c], errors="coerce")

    if "phase7c_ou25_from_btts_candidate" not in out.columns:
        out["phase7c_ou25_from_btts_candidate"] = 0
    if "phase7c_btts_from_ou25_candidate" not in out.columns:
        out["phase7c_btts_from_ou25_candidate"] = 0
    if "phase7c_cross_market_note" not in out.columns:
        out["phase7c_cross_market_note"] = pd.Series("", index=out.index, dtype="string")
    else:
        out["phase7c_cross_market_note"] = out["phase7c_cross_market_note"].astype("string").fillna("").str.strip()

    signal_btts = out.get("support_btts_signal", pd.Series("", index=out.index)).astype("string").fillna("").str.upper().str.strip()
    signal_ou25 = out.get("support_ou25_signal", pd.Series("", index=out.index)).astype("string").fillna("").str.upper().str.strip()

    btts_consensus = out.get("support_btts_priority", pd.Series("", index=out.index)).astype("string").fillna("").str.upper().str.strip().eq("CONSENSUS_ELITE")
    ou25_consensus = out.get("support_ou25_priority", pd.Series("", index=out.index)).astype("string").fillna("").str.upper().str.strip().eq("CONSENSUS_ELITE")

    btts_model_p = pd.to_numeric(out.get("support_btts_model_p", np.nan), errors="coerce")
    btts_model_p_xgb = pd.to_numeric(out.get("support_btts_model_p_xgb", np.nan), errors="coerce")
    ou25_model_p = pd.to_numeric(out.get("support_ou25_model_p", np.nan), errors="coerce")
    ou25_model_p_xgb = pd.to_numeric(out.get("support_ou25_model_p_xgb", np.nan), errors="coerce")

    # Phase 7C discovery pass: allow WEAK_YES when both BTTS model floors clear.
    btts_prob_ok = btts_model_p.ge(0.56) & (btts_model_p_xgb.isna() | btts_model_p_xgb.ge(0.50))
    btts_signal_ok = signal_btts.isin(["STRONG_YES", "VERY_STRONG_YES"]) | (
        signal_btts.eq("WEAK_YES") & btts_prob_ok
    )

    ou25_from_btts = (
        mk.eq("ou25")
        & sel.eq("OVER25")
        & league.isin(PHASE7C_OU25_FROM_BTTS_CANDIDATE_LEAGUES)
        & btts_consensus
        & btts_signal_ok
        & btts_prob_ok
    )

    btts_from_ou25 = (
        mk.eq("btts")
        & sel.eq("YES")
        & league.isin(PHASE7C_BTTS_FROM_OU25_CANDIDATE_LEAGUES)
        & ou25_consensus
        & signal_ou25.isin(["STRONG_OVER", "VERY_STRONG_OVER"])
        & ou25_model_p.ge(0.58)
        & (ou25_model_p_xgb.isna() | ou25_model_p_xgb.ge(0.55))
    )

    out.loc[ou25_from_btts, "phase7c_ou25_from_btts_candidate"] = 1
    out.loc[btts_from_ou25, "phase7c_btts_from_ou25_candidate"] = 1
    out.loc[ou25_from_btts, "phase7c_cross_market_note"] = "OU25_FROM_BTTS_CONSENSUS_CANDIDATE"
    out.loc[btts_from_ou25, "phase7c_cross_market_note"] = "BTTS_FROM_OU25_CONSENSUS_CANDIDATE"

    return out


def _stamp_meta_priority(
    df: pd.DataFrame,
    meta_threshold: float = 0.60,
) -> pd.DataFrame:
    """Stamp additive Phase 8 meta overlay fields when meta scores are present."""
    if df is None:
        return pd.DataFrame()
    out = _normalize_team_context_fields(df.copy())

    if "meta_super_score_cal" not in out.columns:
        out["meta_super_score_cal"] = pd.Series(np.nan, index=out.index, dtype="float64")
    if "meta_super_score" not in out.columns:
        out["meta_super_score"] = pd.Series(np.nan, index=out.index, dtype="float64")
    if "meta_calibration_method" not in out.columns:
        out["meta_calibration_method"] = pd.Series("", index=out.index, dtype="string")
    if "meta_tier" not in out.columns:
        out["meta_tier"] = pd.Series("", index=out.index, dtype="string")
    if "meta_priority_rank" not in out.columns:
        out["meta_priority_rank"] = pd.Series(0, index=out.index, dtype="int64")
    if "meta_overlay_label" not in out.columns:
        out["meta_overlay_label"] = pd.Series("", index=out.index, dtype="string")
    if "meta_score_used" not in out.columns:
        out["meta_score_used"] = pd.Series(np.nan, index=out.index, dtype="float64")
    if "meta_score_source" not in out.columns:
        out["meta_score_source"] = pd.Series("", index=out.index, dtype="string")
    if "meta_gate_pass" not in out.columns:
        out["meta_gate_pass"] = pd.Series(0, index=out.index, dtype="int64")
    if "context_reason_codes" not in out.columns:
        out["context_reason_codes"] = pd.Series("", index=out.index, dtype="string")
    if "value_edge" not in out.columns:
        out["value_edge"] = pd.Series(np.nan, index=out.index, dtype="float64")
    if "value_edge_bps" not in out.columns:
        out["value_edge_bps"] = pd.Series(np.nan, index=out.index, dtype="float64")
    if "value_gap_pct_points" not in out.columns:
        out["value_gap_pct_points"] = pd.Series(np.nan, index=out.index, dtype="float64")
    if "value_edge_tier" not in out.columns:
        out["value_edge_tier"] = pd.Series("NONE", index=out.index, dtype="string")
    for col in TEAM_PROFILE_FLAG_COLUMNS:
        if col not in out.columns:
            out[col] = pd.Series(0, index=out.index, dtype="int64")
    if "team_fixture_interaction" not in out.columns:
        out["team_fixture_interaction"] = pd.Series("OTHER", index=out.index, dtype="string")
    if "team_goal_profile_source" not in out.columns:
        out["team_goal_profile_source"] = pd.Series("", index=out.index, dtype="string")
    if "team_context_label" not in out.columns:
        out["team_context_label"] = pd.Series("General Fixture", index=out.index, dtype="string")
    if "team_context_filter_family" not in out.columns:
        out["team_context_filter_family"] = pd.Series("GENERAL", index=out.index, dtype="string")
    if "team_context_market_bias" not in out.columns:
        out["team_context_market_bias"] = pd.Series("NONE", index=out.index, dtype="string")
    if "team_context_active_flag" not in out.columns:
        out["team_context_active_flag"] = pd.Series(0, index=out.index, dtype="int64")

    market = out.get("market", pd.Series("", index=out.index)).astype("string").fillna("").str.lower().str.strip()
    league = out.get("league", pd.Series("", index=out.index)).astype("string").fillna("").str.strip()
    selection = out.get("selection", out.get("bookie_pick", pd.Series("", index=out.index))).astype("string").fillna("").str.upper().str.strip()
    out["team_fixture_interaction"] = (
        out.get("team_fixture_interaction", pd.Series("OTHER", index=out.index))
        .astype("string")
        .fillna("OTHER")
        .str.upper()
        .str.strip()
    )
    out.loc[~out["team_fixture_interaction"].isin(list(TEAM_CONTEXT_PRODUCT_MAP.keys())), "team_fixture_interaction"] = "OTHER"
    out["team_context_label"] = out["team_fixture_interaction"].map(
        lambda x: TEAM_CONTEXT_PRODUCT_MAP.get(str(x), TEAM_CONTEXT_PRODUCT_MAP["OTHER"])["label"]
    ).astype("string")
    out["team_context_filter_family"] = out["team_fixture_interaction"].map(
        lambda x: TEAM_CONTEXT_PRODUCT_MAP.get(str(x), TEAM_CONTEXT_PRODUCT_MAP["OTHER"])["filter"]
    ).astype("string")
    out["team_context_market_bias"] = out["team_fixture_interaction"].map(
        lambda x: TEAM_CONTEXT_PRODUCT_MAP.get(str(x), TEAM_CONTEXT_PRODUCT_MAP["OTHER"])["bias"]
    ).astype("string")
    out["team_context_active_flag"] = out["team_fixture_interaction"].ne("OTHER").astype(int)

    model_p = pd.to_numeric(out.get("model_p_for_bookie", pd.Series(np.nan, index=out.index)), errors="coerce")
    implied_used = pd.to_numeric(
        out.get(
            "bookie_implied_used",
            out.get(
                "bookie_implied_novig",
                out.get("bookie_implied", pd.Series(np.nan, index=out.index)),
            ),
        ),
        errors="coerce",
    )
    if implied_used.isna().all() or implied_used.isna().any():
        raw_implied = pd.to_numeric(out.get("bookie_implied", pd.Series(np.nan, index=out.index)), errors="coerce")
        implied_used = implied_used.where(implied_used.notna(), raw_implied)
    if implied_used.isna().all() or implied_used.isna().any():
        bookie_od = pd.to_numeric(out.get("bookie_od", pd.Series(np.nan, index=out.index)), errors="coerce")
        implied_from_odds = (1.0 / bookie_od).where(bookie_od > 1.0)
        implied_used = implied_used.where(implied_used.notna(), implied_from_odds)

    out["bookie_implied_used"] = implied_used
    out["value_edge"] = model_p - implied_used
    out["value_edge_bps"] = out["value_edge"] * 10000.0
    out["value_gap_pct_points"] = out["value_edge"] * 100.0
    out["value_edge_tier"] = pd.Series("NONE", index=out.index, dtype="string")
    for tier, threshold in sorted(VALUE_EDGE_TIERS.items(), key=lambda kv: kv[1], reverse=True):
        value_mask = (
            model_p.notna()
            & implied_used.notna()
            & out["value_edge"].ge(float(threshold))
            & out["value_edge_tier"].astype("string").fillna("").eq("NONE")
        )
        out.loc[value_mask, "value_edge_tier"] = tier

    def _pick_score(candidates: list[str]) -> tuple[pd.Series, str]:
        for col in candidates:
            if col in out.columns:
                return pd.to_numeric(out[col], errors="coerce"), col
        return pd.Series(np.nan, index=out.index, dtype="float64"), ""

    btts_score, btts_src = _pick_score(["p_meta_btts", "p_meta"])
    ou25_score, ou25_src = _pick_score(["p_meta_ou25", "p_meta"])
    ftr_score, ftr_src = _pick_score(["p_meta_ftr", "meta_super_score_cal", "meta_super_score", "p_meta"])
    btts_no_score, btts_no_src = _pick_score(["cs_mass_btts_no"])
    under25_score, under25_src = _pick_score(["cs_mass_under25"])
    entropy_score, _ = _pick_score(["cs_entropy"])

    is_btts = market.eq("btts")
    is_ou25 = market.eq("ou25")
    is_ftr = market.eq("ftr")

    def _league_threshold_mask(score: pd.Series, threshold_map: dict[str, float]) -> pd.Series:
        threshold = pd.to_numeric(league.map(threshold_map), errors="coerce")
        return threshold.notna() & score.notna() & score.ge(threshold)

    is_btts_yes = is_btts & selection.eq("YES")
    is_btts_no = is_btts & selection.eq("NO")
    is_ou25_over = is_ou25 & selection.eq("OVER25")
    is_ou25_under = is_ou25 & selection.eq("UNDER25")

    btts_elite = is_btts_yes & _league_threshold_mask(btts_score, BTTS_META_ELITE_LEAGUE_THRESHOLDS)
    btts_no_elite = is_btts_no & _league_threshold_mask(btts_no_score, BTTS_NO_META_ELITE_LEAGUE_THRESHOLDS)
    ou25_elite = is_ou25_over & _league_threshold_mask(ou25_score, OU25_META_ELITE_LEAGUE_THRESHOLDS)

    under25_cfg = league.map(OU25_UNDER25_SPECIALIST_CONFIG)
    under25_mass_min = pd.to_numeric(
        under25_cfg.map(lambda cfg: cfg.get("cs_mass_under25_min") if isinstance(cfg, dict) else np.nan),
        errors="coerce",
    )
    under25_btts_no_min = pd.to_numeric(
        under25_cfg.map(lambda cfg: cfg.get("cs_mass_btts_no_min") if isinstance(cfg, dict) else np.nan),
        errors="coerce",
    )
    under25_specialist = (
        is_ou25_under
        & under25_mass_min.notna()
        & under25_score.notna()
        & under25_score.ge(under25_mass_min)
        & btts_no_score.notna()
        & btts_no_score.ge(under25_btts_no_min)
        & entropy_score.notna()
        & entropy_score.le(float(UNDER25_ENTROPY_GUARD))
    )

    ftr_allowed = ~league.isin(list(FTR_META_RANK_EXCLUDE_LEAGUES)).fillna(False)
    ftr_rankable = is_ftr & ftr_allowed & ftr_score.notna()
    ftr_meta_elite = ftr_rankable & ftr_score.ge(float(meta_threshold))
    ftr_meta_standard = ftr_rankable & (~ftr_meta_elite)

    out.loc[is_btts_yes & btts_score.notna(), "meta_score_used"] = btts_score.loc[is_btts_yes & btts_score.notna()]
    out.loc[is_btts_yes & btts_score.notna(), "meta_score_source"] = btts_src
    out.loc[is_btts_no & btts_no_score.notna(), "meta_score_used"] = btts_no_score.loc[is_btts_no & btts_no_score.notna()]
    out.loc[is_btts_no & btts_no_score.notna(), "meta_score_source"] = btts_no_src
    out.loc[is_ou25_over & ou25_score.notna(), "meta_score_used"] = ou25_score.loc[is_ou25_over & ou25_score.notna()]
    out.loc[is_ou25_over & ou25_score.notna(), "meta_score_source"] = ou25_src
    out.loc[is_ou25_under & under25_score.notna(), "meta_score_used"] = under25_score.loc[is_ou25_under & under25_score.notna()]
    out.loc[is_ou25_under & under25_score.notna(), "meta_score_source"] = under25_src
    out.loc[is_ftr & ftr_score.notna(), "meta_score_used"] = ftr_score.loc[is_ftr & ftr_score.notna()]
    out.loc[is_ftr & ftr_score.notna(), "meta_score_source"] = ftr_src

    out.loc[btts_elite, "meta_tier"] = "META_ELITE_PLUS"
    out.loc[btts_elite, "meta_overlay_label"] = "BTTS_META_ELITE"
    out.loc[btts_elite, "meta_gate_pass"] = 1

    out.loc[btts_no_elite, "meta_tier"] = "META_ELITE_PLUS"
    out.loc[btts_no_elite, "meta_overlay_label"] = "BTTS_NO_META_ELITE"
    out.loc[btts_no_elite, "meta_gate_pass"] = 1

    out.loc[ou25_elite, "meta_tier"] = "META_ELITE_PLUS"
    out.loc[ou25_elite, "meta_overlay_label"] = "OU25_META_ELITE"
    out.loc[ou25_elite, "meta_gate_pass"] = 1

    out.loc[under25_specialist, "meta_tier"] = "META_ELITE_PLUS"
    out.loc[under25_specialist, "meta_overlay_label"] = "OU25_UNDER25_SPECIALIST"
    out.loc[under25_specialist, "meta_gate_pass"] = 1

    out.loc[ftr_meta_elite, "meta_tier"] = "META_ELITE"
    out.loc[ftr_meta_elite, "meta_overlay_label"] = "FTR_META_RANK"
    out.loc[ftr_meta_standard, "meta_tier"] = "META_STANDARD"
    out.loc[ftr_meta_standard, "meta_overlay_label"] = "FTR_META_RANK"

    if bool(btts_elite.any()):
        out = _append_reason_code(out, btts_elite, "BTTS_META_ELITE")
    if bool(btts_no_elite.any()):
        out = _append_reason_code(out, btts_no_elite, "BTTS_NO_META_ELITE")
    if bool(ou25_elite.any()):
        out = _append_reason_code(out, ou25_elite, "OU25_META_ELITE")
    if bool(under25_specialist.any()):
        out = _append_reason_code(out, under25_specialist, "OU25_UNDER25_SPECIALIST")
    if bool(ftr_rankable.any()):
        out = _append_reason_code(out, ftr_rankable, "FTR_META_RANK")

    for tier in ("STANDARD", "STRONG", "PREMIUM"):
        tier_mask = out["value_edge_tier"].astype("string").fillna("").str.upper().eq(tier)
        if bool(tier_mask.any()):
            out = _append_reason_code(out, tier_mask, f"VALUE_EDGE_{tier}")

    for label, token in TEAM_FIXTURE_REASON_TOKENS.items():
        label_mask = out["team_fixture_interaction"].eq(label)
        if bool(label_mask.any()):
            out = _append_reason_code(out, label_mask, token)

    btts_rank = (btts_score.fillna(-1.0) * 1000.0).round().astype(int)
    btts_no_rank = (btts_no_score.fillna(-1.0) * 1000.0).round().astype(int)
    ou25_rank = (ou25_score.fillna(-1.0) * 1000.0).round().astype(int)
    ftr_rank = (ftr_score.fillna(-1.0) * 1000.0).round().astype(int)

    out.loc[btts_elite, "meta_priority_rank"] = 4000 + btts_rank.loc[btts_elite]
    out.loc[btts_no_elite, "meta_priority_rank"] = 4000 + btts_no_rank.loc[btts_no_elite]
    out.loc[ou25_elite, "meta_priority_rank"] = 4000 + ou25_rank.loc[ou25_elite]
    under25_rank = (under25_score.fillna(-1.0) * 1000.0).round().astype(int)
    out.loc[under25_specialist, "meta_priority_rank"] = 4000 + under25_rank.loc[under25_specialist]
    out.loc[ftr_meta_elite, "meta_priority_rank"] = 3000 + ftr_rank.loc[ftr_meta_elite]
    out.loc[ftr_meta_standard, "meta_priority_rank"] = 1000 + ftr_rank.loc[ftr_meta_standard]

    out = _normalize_team_context_fields(out)
    return out


def _stamp_draw_meta_tier(df: pd.DataFrame) -> pd.DataFrame:
    """Stamp draw meta tiers on synthetic FTR DRAW rows."""
    if (not DRAW_LAYER_ENABLED) or df is None or df.empty:
        return df

    out = df.copy()
    if "draw_meta_tier" not in out.columns:
        out["draw_meta_tier"] = pd.Series("", index=out.index, dtype="string")

    sel = out.get("selection", out.get("bookie_pick", pd.Series("", index=out.index))).astype("string").fillna("").str.upper().str.strip()
    market = out.get("market", pd.Series("", index=out.index)).astype("string").fillna("").str.lower().str.strip()
    league = out.get("league", pd.Series("", index=out.index)).astype("string").fillna("").str.strip()
    synth = pd.to_numeric(out.get("is_synthetic_draw_row", 0), errors="coerce").fillna(0).astype(int).ge(1)
    p_draw = pd.to_numeric(out.get("p_draw", np.nan), errors="coerce")
    odds = pd.to_numeric(out.get("odds_draw_decimal", out.get("od_draw", np.nan)), errors="coerce")

    draw_mask = market.eq("ftr") & sel.eq("DRAW") & synth & p_draw.notna() & odds.notna()
    if not bool(draw_mask.any()):
        return out

    odds_ok = odds.ge(DRAW_META_ODDS_GUARD_LO) & odds.lt(DRAW_META_ODDS_GUARD_HI)

    elite_threshold = pd.to_numeric(league.map(DRAW_META_ELITE_LEAGUE_THRESHOLDS), errors="coerce")
    elite_mask = draw_mask & odds_ok & elite_threshold.notna() & p_draw.ge(elite_threshold)
    out.loc[elite_mask, "draw_meta_tier"] = "FTR_DRAW_META_ELITE"

    observe_threshold = pd.to_numeric(league.map(DRAW_META_OBSERVE_LEAGUE_THRESHOLDS), errors="coerce")
    observe_mask = (
        draw_mask
        & odds_ok
        & (~elite_mask)
        & observe_threshold.notna()
        & p_draw.ge(observe_threshold)
    )
    out.loc[observe_mask, "draw_meta_tier"] = "FTR_DRAW_META_OBSERVE"

    if bool(elite_mask.any()):
        out = _append_reason_code(out, elite_mask, "FTR_DRAW_META_ELITE")
    if bool(observe_mask.any()):
        out = _append_reason_code(out, observe_mask, "FTR_DRAW_META_OBSERVE")

    return out


def _stamp_draw_risk_overlay(df: pd.DataFrame) -> pd.DataFrame:
    """Project draw risk from synthetic draw rows onto FTR HOME/AWAY rows."""
    if (not DRAW_LAYER_ENABLED) or df is None or df.empty or "fixture_key" not in df.columns:
        return df

    out = df.copy()
    if "draw_risk_score" not in out.columns:
        out["draw_risk_score"] = pd.Series(np.nan, index=out.index, dtype="float64")
    if "draw_risk_elevated" not in out.columns:
        out["draw_risk_elevated"] = pd.Series(0, index=out.index, dtype="int64")

    sel = out.get("selection", out.get("bookie_pick", pd.Series("", index=out.index))).astype("string").fillna("").str.upper().str.strip()
    market = out.get("market", pd.Series("", index=out.index)).astype("string").fillna("").str.lower().str.strip()
    synth = pd.to_numeric(out.get("is_synthetic_draw_row", 0), errors="coerce").fillna(0).astype(int).ge(1)
    p_draw = pd.to_numeric(out.get("p_draw", np.nan), errors="coerce")

    draw_rows = out.loc[market.eq("ftr") & sel.eq("DRAW") & synth & p_draw.notna(), ["fixture_key"]].copy()
    if draw_rows.empty:
        return out
    draw_rows["p_draw_lookup"] = p_draw.loc[draw_rows.index].values
    draw_lookup = (
        draw_rows.drop_duplicates(subset=["fixture_key"], keep="last")
        .set_index("fixture_key")["p_draw_lookup"]
    )

    ha_mask = market.eq("ftr") & sel.isin(["HOME", "AWAY"])
    out.loc[ha_mask, "draw_risk_score"] = (
        out.loc[ha_mask, "fixture_key"].map(draw_lookup)
    )
    out.loc[ha_mask, "draw_risk_elevated"] = (
        pd.to_numeric(out.loc[ha_mask, "draw_risk_score"], errors="coerce")
        .ge(DRAW_RISK_CONFLICT_THRESHOLD)
        .fillna(False)
        .astype(int)
    )

    elevated_mask = ha_mask & out["draw_risk_elevated"].eq(1)
    if bool(elevated_mask.any()):
        out = _append_reason_code(out, elevated_mask, "FTR_DRAW_RISK_WARN")

    return out


def _route_draw_meta_rows(df: pd.DataFrame, tier_label: str) -> pd.DataFrame:
    """Select routed draw rows for a given deploy tier."""
    if (not DRAW_LAYER_ENABLED) or df is None or df.empty:
        return pd.DataFrame()

    token = "FTR_DRAW_META_ELITE" if str(tier_label).upper() == "ELITE" else "FTR_DRAW_META_OBSERVE"
    routed = df[
        df.get("draw_meta_tier", pd.Series("", index=df.index)).astype("string").fillna("").eq(token)
    ].copy()
    if routed.empty:
        return routed

    routed["deploy_tier"] = "ELITE" if token == "FTR_DRAW_META_ELITE" else "OBSERVE"
    routed["tier"] = routed["deploy_tier"]
    routed["draw_conflict_demoted"] = pd.to_numeric(
        routed.get("draw_conflict_demoted", 0), errors="coerce"
    ).fillna(0).astype(int)
    routed = _append_reason_code(routed, pd.Series(True, index=routed.index), token)
    return routed


def _resolve_draw_conflicts(
    deploy_elite: pd.DataFrame,
    deploy_standard: pd.DataFrame,
) -> tuple[pd.DataFrame, pd.DataFrame]:
    """
    Demote FTR HOME/AWAY ELITE rows when the same fixture also has a
    standalone FTR draw-elite signal.
    """
    if (not DRAW_LAYER_ENABLED) or deploy_elite is None or deploy_elite.empty or "fixture_key" not in deploy_elite.columns:
        return deploy_elite, deploy_standard

    elite = deploy_elite.copy()
    standard = deploy_standard.copy() if isinstance(deploy_standard, pd.DataFrame) else pd.DataFrame()

    draw_elite_keys = set(
        elite.loc[
            elite.get("draw_meta_tier", pd.Series("", index=elite.index)).astype("string").fillna("").eq("FTR_DRAW_META_ELITE"),
            "fixture_key",
        ].dropna().astype("string").tolist()
    )
    if not draw_elite_keys:
        return elite, standard

    sel = elite.get("selection", elite.get("bookie_pick", pd.Series("", index=elite.index))).astype("string").fillna("").str.upper().str.strip()
    market = elite.get("market", pd.Series("", index=elite.index)).astype("string").fillna("").str.lower().str.strip()
    conflict_mask = elite["fixture_key"].astype("string").isin(draw_elite_keys) & market.eq("ftr") & sel.isin(["HOME", "AWAY"])
    if not bool(conflict_mask.any()):
        return elite, standard

    demoted = elite.loc[conflict_mask].copy()
    elite = elite.loc[~conflict_mask].copy()

    demoted["deploy_tier"] = "STANDARD"
    demoted["tier"] = "STANDARD"
    demoted["draw_conflict_demoted"] = 1
    demoted = _append_reason_code(demoted, pd.Series(True, index=demoted.index), "FTR_DRAW_CONFLICT_DEMOTED")

    if standard.empty:
        standard = demoted
    else:
        standard = pd.concat([standard, demoted], ignore_index=True)
        dedupe_cols = [c for c in ["league", "fixture_key", "market", "bookie_pick"] if c in standard.columns]
        if dedupe_cols:
            standard = standard.drop_duplicates(subset=dedupe_cols, keep="last")

    print(
        f"[draw] Demoted {int(conflict_mask.sum())} FTR ELITE home/away rows "
        f"due to draw conflict in {len(draw_elite_keys)} fixtures"
    )
    return elite, standard


# -----------------------------
# Helpers
# -----------------------------

def _normalize_ftr_profile(p: object) -> str:
    s = str(p or "").strip().lower()
    if not s:
        return "accuracy"
    if s in ("accuracy", "value", "valueev_balanced", "valueev_aggressive"):
        return s
    if s.startswith("valueev"):
        return "valueev_balanced"
    return "accuracy"


def _stamp_ftr_product_fields(df: pd.DataFrame, *, ftr_profile: str) -> pd.DataFrame:
    if df is None or df.empty:
        return df
    out = df.copy()
    prof = _normalize_ftr_profile(ftr_profile)

    if "product_profile" not in out.columns:
        out["product_profile"] = ""
    if "product_lane" not in out.columns:
        out["product_lane"] = ""

    mapping = {
        "accuracy": ("ftr_accuracy", "ACCURACY"),
        "value": ("ftr_value", "VALUE"),
        "valueev_balanced": ("ftr_valueev_balanced", "VALUEEV_BALANCED"),
        "valueev_aggressive": ("ftr_valueev_aggressive", "VALUEEV_AGGRESSIVE"),
    }
    pp, lane = mapping[prof]
    out["product_profile"] = pp
    out["product_lane"] = lane
    return out

# NOTE: We intentionally do NOT maintain a local fallback copy of the deterministic
# deploy veto rules in this file.
#
# Reason: the runtime gates evolve frequently (RulePack versions, consensus gates,
# etc). A duplicated fallback silently diverges and causes hard-to-debug behavior.
#
# If deploy_gates cannot be imported, we fail loudly.

def _safe_tag(s: str) -> str:
    s = (s or "").strip()
    s = s.replace(" ", "_").replace("/", "_").replace("\\", "_")
    s = "".join(ch for ch in s if ch.isalnum() or ch in ("_", "-", "."))
    return s


def _build_run_tag(args) -> str:
    # preset always matters
    preset = _safe_tag(getattr(args, "preset", "") or "V1")

    # include FTR profile only if provided (keeps older runs comparable)
    ftr_prof = _safe_tag(getattr(args, "ftr_profile", "") or "")
    parts = [f"PRESET_{preset}"]
    if ftr_prof:
        parts.append(f"FTR_{ftr_prof}")

    return "__" + "__".join(parts)

def _combine_pipe(a: object, b: object) -> str:
    """Combine two pipe-separated reason strings, skipping empties."""
    aa = str(a or '').strip()
    bb = str(b or '').strip()
    if not aa and not bb:
        return ''
    if aa and not bb:
        return aa
    if bb and not aa:
        return bb
    # avoid duplicate tokens
    toks = []
    seen = set()
    for part in (aa.split('|') + bb.split('|')):
        t = part.strip()
        if not t or t in seen:
            continue
        seen.add(t)
        toks.append(t)
    return '|'.join(toks)

def _append_reason_code(df: pd.DataFrame, mask: pd.Series, code: str) -> pd.DataFrame:
    """Append a pipe-delimited reason code onto context_reason_codes for masked rows."""
    if df is None or df.empty:
        return df
    if "context_reason_codes" not in df.columns:
        df["context_reason_codes"] = ""
    df["context_reason_codes"] = df["context_reason_codes"].astype("string").fillna("")
    m = pd.Series(mask, index=df.index).fillna(False)
    if bool(m.any()):
        df.loc[m, "context_reason_codes"] = df.loc[m, "context_reason_codes"].map(
            lambda x: _combine_pipe(x, code)
        )
    return df


def _normalize_team_context_fields(df: pd.DataFrame) -> pd.DataFrame:
    """Keep team-intelligence descriptive fields stable across deploy outputs."""
    if df is None or df.empty:
        return df

    out = df.copy()
    for col in TEAM_PROFILE_FLAG_COLUMNS:
        if col not in out.columns:
            out[col] = pd.Series(0, index=out.index, dtype="int64")
        out[col] = pd.to_numeric(out.get(col, pd.Series(0, index=out.index)), errors="coerce").fillna(0).astype(int)

    if "team_fixture_interaction" not in out.columns:
        out["team_fixture_interaction"] = pd.Series("OTHER", index=out.index, dtype="string")
    out["team_fixture_interaction"] = (
        out.get("team_fixture_interaction", pd.Series("OTHER", index=out.index))
        .astype("string")
        .fillna("OTHER")
        .str.upper()
        .str.strip()
    )
    out.loc[~out["team_fixture_interaction"].isin(list(TEAM_CONTEXT_PRODUCT_MAP.keys())), "team_fixture_interaction"] = "OTHER"

    if "team_goal_profile_source" not in out.columns:
        out["team_goal_profile_source"] = pd.Series("", index=out.index, dtype="string")
    out["team_goal_profile_source"] = out["team_goal_profile_source"].astype("string").fillna("")

    out["team_context_label"] = out["team_fixture_interaction"].map(
        lambda x: TEAM_CONTEXT_PRODUCT_MAP.get(str(x), TEAM_CONTEXT_PRODUCT_MAP["OTHER"])["label"]
    ).astype("string")
    out["team_context_filter_family"] = out["team_fixture_interaction"].map(
        lambda x: TEAM_CONTEXT_PRODUCT_MAP.get(str(x), TEAM_CONTEXT_PRODUCT_MAP["OTHER"])["filter"]
    ).astype("string")
    out["team_context_market_bias"] = out["team_fixture_interaction"].map(
        lambda x: TEAM_CONTEXT_PRODUCT_MAP.get(str(x), TEAM_CONTEXT_PRODUCT_MAP["OTHER"])["bias"]
    ).astype("string")
    out["team_context_active_flag"] = out["team_fixture_interaction"].ne("OTHER").astype(int)
    return out


def _apply_phase9b_premium_ge2_test_lane(
    deploy_standard: pd.DataFrame,
    observe: pd.DataFrame,
    *,
    params: Dict[str, Any],
    debug: bool = False,
) -> tuple[pd.DataFrame, pd.DataFrame]:
    """Promote frozen Phase 9B premium GE2 finalists into a narrow STANDARD test lane.

    This intentionally stays rule-draft driven and is gated behind an explicit flag.
    It only considers BTTS YES / OU25 OVER rows that match the frozen premium rule draft.
    """
    enabled = bool(params.get("phase9b_premium_ge2_test_lane", False))
    if not enabled:
        return deploy_standard, observe

    rule_path = str(params.get("phase9b_premium_ge2_rule_csv", "") or PHASE9B_PREMIUM_GE2_RULE_DRAFT_DEFAULT)
    corr_path = str(params.get("phase9b_league_correction_csv", "") or PHASE9B_LEAGUE_CORRECTION_TABLE_DEFAULT)
    context_mode = str(params.get("phase9b_premium_ge2_context_mode", "exact") or "exact").strip().lower()
    rules = _load_phase9b_premium_ge2_rule_draft_csv(rule_path)
    corr_map = _load_phase9b_league_correction_table_csv(corr_path)
    if rules.empty:
        if debug:
            print(f"[deploy_rulebook] Phase9B premium GE2 test lane skipped: no rule draft at {rule_path}")
        return deploy_standard, observe

    std = _normalize_team_context_fields(_coalesce_tier_cols(deploy_standard.copy() if isinstance(deploy_standard, pd.DataFrame) else pd.DataFrame()))
    obs = _normalize_team_context_fields(_coalesce_tier_cols(observe.copy() if isinstance(observe, pd.DataFrame) else pd.DataFrame()))

    def _prep(df: pd.DataFrame) -> pd.DataFrame:
        if df is None or df.empty:
            return pd.DataFrame()
        out = _normalize_team_context_fields(df.copy())
        out["market_norm"] = out.get("market", pd.Series("", index=out.index)).astype("string").fillna("").str.lower().str.strip()
        out["selection_norm"] = (
            out.get("bookie_pick", out.get("selection", pd.Series("", index=out.index)))
            .astype("string")
            .fillna("")
            .str.upper()
            .str.strip()
        )
        out["league_norm"] = out.get("league", pd.Series("", index=out.index)).astype("string").fillna("").str.strip()
        out["value_edge_tier_norm"] = out.get("value_edge_tier", pd.Series("", index=out.index)).astype("string").fillna("").str.upper().str.strip()
        out["team_context_filter_family"] = out.get("team_context_filter_family", pd.Series("", index=out.index)).astype("string").fillna("").str.upper().str.strip()
        out["home_team_name_norm"] = out.get("home_team_name", pd.Series("", index=out.index)).astype("string").fillna("").str.strip()
        out["away_team_name_norm"] = out.get("away_team_name", pd.Series("", index=out.index)).astype("string").fillna("").str.strip()

        out["phase9b_raw_model_prob"] = np.where(
            out["market_norm"].eq("btts") & out["selection_norm"].eq("YES"),
            pd.to_numeric(out.get("cs_mass_btts_yes", np.nan), errors="coerce"),
            np.where(
                out["market_norm"].eq("ou25") & out["selection_norm"].eq("OVER25"),
                pd.to_numeric(out.get("cs_mass_over25", np.nan), errors="coerce"),
                np.nan,
            ),
        )
        out["phase9b_study"] = np.where(
            out["market_norm"].eq("btts") & out["selection_norm"].eq("YES"),
            "BTTS_YES",
            np.where(
                out["market_norm"].eq("ou25") & out["selection_norm"].eq("OVER25"),
                "OU25_OVER",
                "",
            ),
        )
        corr_keys = list(zip(out["phase9b_study"].astype(str), out["league_norm"].astype(str)))
        corr_vals = pd.Series([corr_map.get((s, lg), 1.0) for s, lg in corr_keys], index=out.index, dtype="float64")
        out["phase9b_correction_multiplier"] = corr_vals.fillna(1.0)
        out["phase9b_corrected_model_prob"] = (
            out["phase9b_raw_model_prob"] * out["phase9b_correction_multiplier"]
        ).clip(lower=0.0, upper=0.999)
        return out

    std = _prep(std)
    obs = _prep(obs)

    promoted_frames: list[pd.DataFrame] = []
    promoted_idx: set = set()
    stamped_std = 0

    for _, rule in rules.iterrows():
        allow_side = str(rule.get("allowlist_side", "")).strip().upper()
        team_col = str(rule.get("team_match_column", "")).strip()
        if team_col not in {"home_team_name", "away_team_name"}:
            team_col = "home_team_name" if allow_side == "HOME_GE2" else "away_team_name"
        team_norm_col = f"{team_col}_norm"
        req_filter = str(rule.get("required_team_context_filter_family", "")).strip().upper()
        req_value = str(rule.get("required_value_edge_tier", "")).strip().upper()
        rule_market = str(rule.get("market", "")).strip().lower()
        rule_selection = str(rule.get("selection", "")).strip().upper()
        rule_league = str(rule.get("league", "")).strip()
        rule_team = str(rule.get("team_name", "")).strip()
        raw_floor = pd.to_numeric(pd.Series([rule.get("raw_model_prob_floor")]), errors="coerce").iloc[0]
        corr_floor = pd.to_numeric(pd.Series([rule.get("corrected_model_prob_floor")]), errors="coerce").iloc[0]
        token = str(rule.get("reason_token", "")).strip() or "PHASE9B_PREMIUM_GE2_TEST_LANE"

        def _mask(df: pd.DataFrame) -> pd.Series:
            if df is None or df.empty:
                return pd.Series(False, index=getattr(df, "index", pd.RangeIndex(0)))
            m = (
                df["market_norm"].eq(rule_market)
                & df["selection_norm"].eq(rule_selection)
                & df["league_norm"].eq(rule_league)
                & df["value_edge_tier_norm"].eq(req_value)
                & df.get(team_norm_col, pd.Series("", index=df.index)).eq(rule_team)
            )
            if context_mode == "side_family_or_general":
                m = m & df["team_context_filter_family"].isin([req_filter, "GENERAL"])
            elif context_mode == "drop_context":
                pass
            else:
                m = m & df["team_context_filter_family"].eq(req_filter)
            if pd.notna(raw_floor):
                m = m & df["phase9b_raw_model_prob"].ge(float(raw_floor))
            if pd.notna(corr_floor):
                m = m & df["phase9b_corrected_model_prob"].ge(float(corr_floor))
            return m.fillna(False)

        m_std = _mask(std)
        if bool(m_std.any()):
            _append_reason_token(std, "context_reason_codes", m_std, token)
            if "reason_codes" in std.columns:
                _append_reason_token(std, "reason_codes", m_std, token)
            stamped_std += int(m_std.sum())

        m_obs = _mask(obs)
        if bool(m_obs.any()):
            promoted = obs.loc[m_obs].copy()
            promoted["deploy_tier"] = str(rule.get("promote_to_deploy_tier", "STANDARD")).strip().upper() or "STANDARD"
            promoted["tier"] = promoted["deploy_tier"]
            if "context_reason_codes" not in promoted.columns:
                promoted["context_reason_codes"] = ""
            promoted["context_reason_codes"] = promoted["context_reason_codes"].astype("string").fillna("")
            _append_reason_token(promoted, "context_reason_codes", pd.Series(True, index=promoted.index), token)
            _append_reason_token(promoted, "context_reason_codes", pd.Series(True, index=promoted.index), "PHASE9B_PREMIUM_GE2_TEST_LANE")
            if "reason_codes" in promoted.columns:
                _append_reason_token(promoted, "reason_codes", pd.Series(True, index=promoted.index), token)
                _append_reason_token(promoted, "reason_codes", pd.Series(True, index=promoted.index), "PHASE9B_PREMIUM_GE2_TEST_LANE")
            promoted["phase9b_premium_ge2_test_lane"] = 1
            promoted_frames.append(promoted)
            promoted_idx.update(obs.index[m_obs].tolist())

    if promoted_idx:
        obs = obs.loc[~obs.index.isin(list(promoted_idx))].copy()
    if promoted_frames:
        promo_df = pd.concat(promoted_frames, axis=0, ignore_index=False)
        std = pd.concat([std, promo_df], axis=0, ignore_index=True) if not std.empty else promo_df.reset_index(drop=True)
        dedupe_cols = [c for c in ["league", "fixture_key", "market", "bookie_pick"] if c in std.columns]
        if dedupe_cols:
            std = std.drop_duplicates(subset=dedupe_cols, keep="last").reset_index(drop=True)

    for df in (std, obs):
        if df is None or df.empty:
            continue
        if "phase9b_premium_ge2_test_lane" not in df.columns:
            df["phase9b_premium_ge2_test_lane"] = 0
        df["phase9b_premium_ge2_test_lane"] = pd.to_numeric(df["phase9b_premium_ge2_test_lane"], errors="coerce").fillna(0).astype(int)

    drop_cols = [
        "market_norm",
        "selection_norm",
        "league_norm",
        "value_edge_tier_norm",
        "home_team_name_norm",
        "away_team_name_norm",
    ]
    std = std.drop(columns=[c for c in drop_cols if c in std.columns], errors="ignore")
    obs = obs.drop(columns=[c for c in drop_cols if c in obs.columns], errors="ignore")

    if debug:
        promoted_n = sum(len(x) for x in promoted_frames)
        print(
            "[deploy_rulebook] Phase9B premium GE2 test lane:",
            {
                "rule_rows": int(len(rules)),
                "standard_stamped": int(stamped_std),
                "observe_promoted": int(promoted_n),
                "rule_csv": rule_path,
                "context_mode": context_mode,
            },
        )

    return std, obs


def _apply_phase9b_team_over15_shadow_capture_lane(
    deploy_standard: pd.DataFrame,
    observe: pd.DataFrame,
    *,
    params: Dict[str, Any],
    debug: bool = False,
) -> tuple[pd.DataFrame, pd.DataFrame]:
    """Stamp a future-ready shadow-only TG15 capture lane when direct prices exist.

    This lane is intentionally dormant under the current provider setup because TG15
    rows are model-only. If a future provider starts delivering direct team-goals
    prices, matching shortlist rows are diverted into OBSERVE and stamped for
    shadow/capture review rather than live promotion.
    """
    enabled = bool(params.get("phase9b_team_over15_shadow_capture_lane", False))
    if not enabled:
        return deploy_standard, observe

    shortlist_path = str(
        params.get("phase9b_team_over15_shortlist_csv", "") or PHASE9B_TEAM_OVER15_SHORTLIST_DEFAULT
    )
    shortlist = _load_phase9b_team_over15_shortlist_csv(shortlist_path)
    if shortlist.empty:
        if debug:
            print(f"[deploy_rulebook] Phase9B TG15 shadow lane skipped: no shortlist at {shortlist_path}")
        return deploy_standard, observe

    std = _coalesce_tier_cols(deploy_standard.copy() if isinstance(deploy_standard, pd.DataFrame) else pd.DataFrame())
    obs = _coalesce_tier_cols(observe.copy() if isinstance(observe, pd.DataFrame) else pd.DataFrame())

    def _prep(df: pd.DataFrame) -> pd.DataFrame:
        if df is None or df.empty:
            return pd.DataFrame()
        out = df.copy()
        out["market_norm"] = out.get("market", pd.Series("", index=out.index)).astype("string").fillna("").str.lower().str.strip()
        out["league_norm"] = out.get("league", pd.Series("", index=out.index)).astype("string").fillna("").str.strip()
        out["bookie_pick_norm"] = (
            out.get("bookie_pick", out.get("selection", pd.Series("", index=out.index)))
            .astype("string")
            .fillna("")
            .str.upper()
            .str.strip()
        )
        out["home_team_name_norm"] = out.get("home_team_name", pd.Series("", index=out.index)).astype("string").fillna("").str.strip()
        out["away_team_name_norm"] = out.get("away_team_name", pd.Series("", index=out.index)).astype("string").fillna("").str.strip()
        out["allowlist_side_norm"] = np.where(
            out["bookie_pick_norm"].str.startswith("HOME_", na=False),
            "HOME_OVER15",
            np.where(out["bookie_pick_norm"].str.startswith("AWAY_", na=False), "AWAY_OVER15", ""),
        )
        out["allowlist_team_norm"] = np.where(
            out["allowlist_side_norm"] == "HOME_OVER15",
            out["home_team_name_norm"],
            np.where(out["allowlist_side_norm"] == "AWAY_OVER15", out["away_team_name_norm"], ""),
        )
        out["od_source_norm"] = out.get("od_source", pd.Series("", index=out.index)).astype("string").fillna("").str.lower().str.strip()
        out["bookie_od_num"] = pd.to_numeric(out.get("bookie_od", np.nan), errors="coerce")
        out["bookie_implied_num"] = pd.to_numeric(out.get("bookie_implied", np.nan), errors="coerce")
        out["phase9b_team_over15_direct_price_ready_flag"] = (
            out["bookie_od_num"].gt(1.0)
            | out["bookie_implied_num"].gt(0.0)
            | (~out["od_source_norm"].isin(["", "model_only"]))
        ).astype(int)
        return out

    std = _prep(std)
    obs = _prep(obs)
    shortlist_key = shortlist.copy()
    shortlist_key["league_norm"] = shortlist_key["league"].astype("string").fillna("").str.strip()
    shortlist_key["team_norm"] = shortlist_key["team"].astype("string").fillna("").str.strip()
    shortlist_key["allowlist_side_norm"] = shortlist_key["allowlist_side"].astype("string").fillna("").str.strip()
    shortlist_key = shortlist_key.drop_duplicates(subset=["league_norm", "team_norm", "allowlist_side_norm"])

    def _stamp(df: pd.DataFrame, *, force_observe: bool) -> tuple[pd.DataFrame, pd.DataFrame]:
        if df is None or df.empty:
            return df, pd.DataFrame()
        keyed = df.merge(
            shortlist_key[
                [
                    "league_norm",
                    "team_norm",
                    "allowlist_side_norm",
                    "allowlist_tier",
                    "review_priority",
                    "premium_signal_state",
                    "promotion_policy",
                ]
            ],
            left_on=["league_norm", "allowlist_team_norm", "allowlist_side_norm"],
            right_on=["league_norm", "team_norm", "allowlist_side_norm"],
            how="left",
        )
        matched = (
            keyed["market_norm"].eq("tg15")
            & keyed["allowlist_side_norm"].isin(["HOME_OVER15", "AWAY_OVER15"])
            & keyed["allowlist_tier"].astype("string").fillna("").ne("")
            & keyed["phase9b_team_over15_direct_price_ready_flag"].eq(1)
        )
        keyed["phase9b_team_over15_shadow_capture_lane"] = matched.astype(int)
        keyed["phase9b_team_over15_capture_status"] = np.where(
            matched,
            "SHADOW_CAPTURE_READY",
            np.where(
                keyed["market_norm"].eq("tg15") & keyed["allowlist_tier"].astype("string").fillna("").ne(""),
                "WAITING_FOR_DIRECT_PRICES",
                "",
            ),
        )
        if "context_reason_codes" not in keyed.columns:
            keyed["context_reason_codes"] = ""
        keyed["context_reason_codes"] = keyed["context_reason_codes"].astype("string").fillna("")
        _append_reason_token(
            keyed,
            "context_reason_codes",
            matched,
            "PHASE9B_TEAM_OVER15_SHADOW_CAPTURE",
        )
        if "reason_codes" in keyed.columns:
            _append_reason_token(
                keyed,
                "reason_codes",
                matched,
                "PHASE9B_TEAM_OVER15_SHADOW_CAPTURE",
            )
        if force_observe and bool(matched.any()):
            diverted = keyed.loc[matched].copy()
            diverted["deploy_tier"] = "OBSERVE"
            diverted["tier"] = "OBSERVE"
            kept = keyed.loc[~matched].copy()
            return kept, diverted
        return keyed, pd.DataFrame()

    std, diverted_std = _stamp(std, force_observe=True)
    obs, diverted_obs = _stamp(obs, force_observe=False)

    if not diverted_std.empty:
        obs = pd.concat([obs, diverted_std], ignore_index=True) if not obs.empty else diverted_std.reset_index(drop=True)
    if not diverted_obs.empty:
        obs = pd.concat([obs, diverted_obs], ignore_index=True) if not obs.empty else diverted_obs.reset_index(drop=True)

    dedupe_cols = [c for c in ["league", "fixture_key", "market", "bookie_pick"] if c in obs.columns]
    if dedupe_cols and not obs.empty:
        obs = obs.drop_duplicates(subset=dedupe_cols, keep="last").reset_index(drop=True)
    if dedupe_cols and not std.empty:
        std = std.drop_duplicates(subset=dedupe_cols, keep="last").reset_index(drop=True)

    for df in (std, obs):
        if df is None or df.empty:
            continue
        if "phase9b_team_over15_shadow_capture_lane" not in df.columns:
            df["phase9b_team_over15_shadow_capture_lane"] = 0
        df["phase9b_team_over15_shadow_capture_lane"] = (
            pd.to_numeric(df["phase9b_team_over15_shadow_capture_lane"], errors="coerce").fillna(0).astype(int)
        )
        if "phase9b_team_over15_capture_status" not in df.columns:
            df["phase9b_team_over15_capture_status"] = ""

    drop_cols = [
        "market_norm",
        "league_norm",
        "bookie_pick_norm",
        "home_team_name_norm",
        "away_team_name_norm",
        "allowlist_side_norm",
        "allowlist_team_norm",
        "od_source_norm",
        "bookie_od_num",
        "bookie_implied_num",
        "team_norm",
    ]
    std = std.drop(columns=[c for c in drop_cols if c in std.columns], errors="ignore")
    obs = obs.drop(columns=[c for c in drop_cols if c in obs.columns], errors="ignore")

    if debug:
        std_n = int(pd.to_numeric(std.get("phase9b_team_over15_shadow_capture_lane", 0), errors="coerce").fillna(0).sum()) if not std.empty else 0
        obs_n = int(pd.to_numeric(obs.get("phase9b_team_over15_shadow_capture_lane", 0), errors="coerce").fillna(0).sum()) if not obs.empty else 0
        print(
            "[deploy_rulebook] Phase9B TG15 shadow capture lane:",
            {
                "shortlist_rows": int(len(shortlist)),
                "standard_shadow_rows": std_n,
                "observe_shadow_rows": obs_n,
                "shortlist_csv": shortlist_path,
            },
        )

    return std, obs


def _coalesce_tier_cols(df: pd.DataFrame) -> pd.DataFrame:
    """Ensure a consistent deploy tier column exists and is normalized.

    Supports naming variants (`tier` / `deploy_tier`) and keeps them in sync.
    """
    if df is None:
        return df

    out = df.copy()

    if ("deploy_tier" not in out.columns) and ("tier" not in out.columns):
        out["deploy_tier"] = "STANDARD"
        out["tier"] = "STANDARD"
    elif ("deploy_tier" in out.columns) and ("tier" not in out.columns):
        out["tier"] = out["deploy_tier"].astype("string")
    elif ("tier" in out.columns) and ("deploy_tier" not in out.columns):
        out["deploy_tier"] = out["tier"].astype("string")

    out["deploy_tier"] = out["deploy_tier"].astype("string").fillna("").str.strip().str.upper()
    out.loc[out["deploy_tier"].eq(""), "deploy_tier"] = "STANDARD"
    out["tier"] = out["deploy_tier"]

    return out

def _stamp_product_identity(df: pd.DataFrame, *, params: Dict[str, Any]) -> pd.DataFrame:
    if df is None or df.empty:
        return df
    out = df.copy()

    # Ensure cols exist and are strings
    if "product_profile" not in out.columns:
        out["product_profile"] = ""
    if "product_lane" not in out.columns:
        out["product_lane"] = ""
    out["product_profile"] = out["product_profile"].astype("string").fillna("").str.strip()
    out["product_lane"] = out["product_lane"].astype("string").fillna("").str.strip()

    mk = out.get("market", pd.Series("", index=out.index)).astype("string").fillna("").str.lower().str.strip()
    pick = out.get("bookie_pick", out.get("selection", pd.Series("", index=out.index))).astype("string").fillna("").str.upper().str.strip()

    # ---- FTR
    ftr_prof = _normalize_ftr_profile(params.get("ftr_profile", "accuracy") or "accuracy")
    m_ftr = mk.eq("ftr")
    if bool(m_ftr.any()):
        stamped_ftr = _stamp_ftr_product_fields(out.loc[m_ftr, :].copy(), ftr_profile=ftr_prof)
        stamped_ftr = _classify_hw_hge2_live(stamped_ftr)
        stamped_ftr = _classify_aw_age2_live(stamped_ftr)

        # Keep the normal FTR identity as the primary market identity.
        if "product_profile" in stamped_ftr.columns:
            out.loc[m_ftr, "product_profile"] = stamped_ftr["product_profile"].astype("string").fillna("")
        if "product_lane" in stamped_ftr.columns:
            out.loc[m_ftr, "product_lane"] = stamped_ftr["product_lane"].astype("string").fillna("")

        # Build parallel combo-overlay identity fields.
        combo_product = pd.Series("", index=stamped_ftr.index, dtype="string")
        combo_tier = pd.Series("", index=stamped_ftr.index, dtype="string")
        combo_allowed = pd.Series(0, index=stamped_ftr.index, dtype="int64")

        hw_tier = stamped_ftr.get("hw_hge2_live_tier", pd.Series("", index=stamped_ftr.index)).astype("string").fillna("").str.strip()
        aw_tier = stamped_ftr.get("aw_age2_live_tier", pd.Series("", index=stamped_ftr.index)).astype("string").fillna("").str.strip()
        hw_allowed = pd.to_numeric(
            stamped_ftr.get("hw_hge2_live_allowed", pd.Series(0, index=stamped_ftr.index)),
            errors="coerce",
        ).fillna(0).astype(int)
        aw_allowed = pd.to_numeric(
            stamped_ftr.get("aw_age2_live_allowed", pd.Series(0, index=stamped_ftr.index)),
            errors="coerce",
        ).fillna(0).astype(int)

        m_hw = hw_allowed.ge(1) & hw_tier.ne("")
        m_aw = aw_allowed.ge(1) & aw_tier.ne("")

        combo_product.loc[m_hw] = "HOME_WIN_AND_HOME_GE2"
        combo_tier.loc[m_hw] = hw_tier.loc[m_hw]
        combo_allowed.loc[m_hw] = 1

        combo_product.loc[m_aw] = "AWAY_WIN_AND_AWAY_GE2"
        combo_tier.loc[m_aw] = aw_tier.loc[m_aw]
        combo_allowed.loc[m_aw] = 1

        stamped_ftr["ftr_combo_live_product"] = combo_product.astype("string").fillna("")
        stamped_ftr["ftr_combo_live_tier"] = combo_tier.astype("string").fillna("")
        stamped_ftr["ftr_combo_live_allowed"] = combo_allowed.astype(int)

        for _c in [
            "hw_hge2_live_tier",
            "hw_hge2_live_allowed",
            "hw_hge2_lambda_away_ok",
            "hw_hge2_premium_monster_flag",
            "hw_hge2_combo_lambda",
            "hw_hge2_combo_prob",
            "hw_hge2_ge2_gap",
            "aw_age2_live_tier",
            "aw_age2_live_allowed",
            "aw_age2_combo_lambda",
            "aw_age2_combo_prob",
            "aw_age2_ge2_gap",
            "ftr_combo_live_product",
            "ftr_combo_live_tier",
            "ftr_combo_live_allowed",
        ]:
            if _c in stamped_ftr.columns:
                out.loc[m_ftr, _c] = stamped_ftr[_c]

    # ---- OU25
    m_ou = mk.eq("ou25")
    if bool(m_ou.any()):
        out.loc[m_ou & pick.eq("OVER25"), "product_profile"] = "ou25_over"
        out.loc[m_ou & pick.eq("OVER25"), "product_lane"] = "OU25_OVER"
        out.loc[m_ou & pick.eq("UNDER25"), "product_profile"] = "ou25_under"
        out.loc[m_ou & pick.eq("UNDER25"), "product_lane"] = "OU25_UNDER"

    # ---- BTTS
    m_bt = mk.eq("btts")
    if bool(m_bt.any()):
        out.loc[m_bt & pick.eq("YES"), "product_profile"] = "btts_yes"
        out.loc[m_bt & pick.eq("YES"), "product_lane"] = "BTTS_YES"
        out.loc[m_bt & pick.eq("NO"), "product_profile"] = "btts_no"
        out.loc[m_bt & pick.eq("NO"), "product_lane"] = "BTTS_NO"

    # ---- TG
    m_tg15 = mk.eq("tg15")
    m_tg25 = mk.eq("tg25")
    if bool(m_tg15.any()):
        out.loc[m_tg15, "product_profile"] = "tg15"
        out.loc[m_tg15, "product_lane"] = "TG15"
    if bool(m_tg25.any()):
        out.loc[m_tg25, "product_profile"] = "tg25"
        out.loc[m_tg25, "product_lane"] = "TG25"
    # Carry live combo helper fields through when present so downstream reports can use them.
    for combo_col in ["ftr_combo_live_product", "ftr_combo_live_tier", "ftr_combo_live_allowed"]:
        if combo_col in out.columns:
            if combo_col == "ftr_combo_live_allowed":
                out[combo_col] = pd.to_numeric(
                    out.get(combo_col, pd.Series(0, index=out.index)),
                    errors="coerce",
                ).fillna(0).astype(int)
            else:
                out[combo_col] = out[combo_col].astype("string").fillna("").str.strip()

    # Parallel combo overlay routing / priority layer (does not replace base product identity)
    if "combo_overlay_priority" not in out.columns:
        out["combo_overlay_priority"] = pd.Series(0, index=out.index, dtype="int64")
    if "combo_overlay_bucket" not in out.columns:
        out["combo_overlay_bucket"] = pd.Series("", index=out.index, dtype="string")
    if "acca_builder_priority" not in out.columns:
        out["acca_builder_priority"] = pd.Series(999, index=out.index, dtype="int64")
    if "acca_builder_rank" not in out.columns:
        out["acca_builder_rank"] = pd.Series(999, index=out.index, dtype="int64")
    if "acca_builder_bucket" not in out.columns:
        out["acca_builder_bucket"] = pd.Series("", index=out.index, dtype="string")

    out["combo_overlay_priority"] = pd.to_numeric(
        out.get("combo_overlay_priority", pd.Series(0, index=out.index)),
        errors="coerce",
    ).fillna(0).astype(int)
    out["combo_overlay_bucket"] = out.get(
        "combo_overlay_bucket", pd.Series("", index=out.index, dtype="string")
    ).astype("string").fillna("").str.strip()
    out["acca_builder_priority"] = pd.to_numeric(
        out.get("acca_builder_priority", pd.Series(999, index=out.index)),
        errors="coerce",
    ).fillna(999).astype(int)
    out["acca_builder_rank"] = pd.to_numeric(
        out.get("acca_builder_rank", pd.Series(999, index=out.index)),
        errors="coerce",
    ).fillna(999).astype(int)
    out["acca_builder_bucket"] = out.get(
        "acca_builder_bucket", pd.Series("", index=out.index, dtype="string")
    ).astype("string").fillna("").str.strip()
    combo_product = out.get("ftr_combo_live_product", pd.Series("", index=out.index)).astype("string").fillna("").str.strip()
    combo_tier = out.get("ftr_combo_live_tier", pd.Series("", index=out.index)).astype("string").fillna("").str.strip()

    signal_btts_runtime = out.get(
        "signal_btts_runtime",
        pd.Series("", index=out.index),
    ).astype("string").fillna("").str.strip().str.upper()
    signal_over25 = _normalize_signal_label_series(_get_ou25_signal_series(out, default=""), default="")

    m_combo_aw_vs = combo_product.eq("AWAY_WIN_AND_AWAY_GE2") & combo_tier.eq("VERY_STRONG_AW")
    m_combo_aw_s = combo_product.eq("AWAY_WIN_AND_AWAY_GE2") & combo_tier.eq("STRONG_AW")
    m_combo_hw_vs = combo_product.eq("HOME_WIN_AND_HOME_GE2") & combo_tier.eq("VERY_STRONG_HW")
    m_combo_hw_s = combo_product.eq("HOME_WIN_AND_HOME_GE2") & combo_tier.eq("STRONG_HW")

    std_bucket = out.get("standard_reporting_bucket", pd.Series("", index=out.index)).astype("string").fillna("").str.strip()
    m_ftr_cs_promoted = mk.eq("ftr") & std_bucket.eq("STANDARD_FTR_CS_PROMOTED_ALIGNED")
    m_btts_vs = (
        mk.eq("btts")
        & pick.eq("YES")
        & signal_btts_runtime.eq("VERY_STRONG_YES")
        & (~out.get("league", pd.Series("", index=out.index)).astype("string").fillna("").str.strip().eq("Brazil Serie A"))
    )
    m_ou25_vs = mk.eq("ou25") & pick.eq("OVER25") & signal_over25.eq("VERY_STRONG_OVER")

    # Locked live deployment ordering v1.2
    # 1. FTR_CS_PROMOTED
    # 2. BTTS VS non-Brazil
    # 3. HW+HGE2 combined (VERY_STRONG then STRONG)
    # 4. AW+AGE2 combined (VERY_STRONG then STRONG)
    # 5. OU25 VS

    out.loc[m_ftr_cs_promoted, "combo_overlay_priority"] = 100
    out.loc[m_ftr_cs_promoted, "combo_overlay_bucket"] = "FTR_CS_PROMOTED"
    out.loc[m_ftr_cs_promoted, "acca_builder_bucket"] = "FTR_CS_PROMOTED"
    out.loc[m_ftr_cs_promoted, "acca_builder_priority"] = 1
    out.loc[m_ftr_cs_promoted, "acca_builder_rank"] = 1

    out.loc[m_btts_vs, "combo_overlay_priority"] = 95
    out.loc[m_btts_vs, "combo_overlay_bucket"] = "BTTS_VERY_STRONG_NON_BRAZIL"
    out.loc[m_btts_vs, "acca_builder_bucket"] = "BTTS_VS_NON_BRAZIL"
    out.loc[m_btts_vs, "acca_builder_priority"] = 2
    out.loc[m_btts_vs, "acca_builder_rank"] = 2

    out.loc[m_combo_hw_vs, "combo_overlay_priority"] = 90
    out.loc[m_combo_hw_vs, "combo_overlay_bucket"] = "HOME_WIN_AND_HOME_GE2_VERY_STRONG_HW"
    out.loc[m_combo_hw_vs, "acca_builder_bucket"] = "HW_HGE2_COMBINED"
    out.loc[m_combo_hw_vs, "acca_builder_priority"] = 3
    out.loc[m_combo_hw_vs, "acca_builder_rank"] = 3

    out.loc[m_combo_hw_s, "combo_overlay_priority"] = 85
    out.loc[m_combo_hw_s, "combo_overlay_bucket"] = "HOME_WIN_AND_HOME_GE2_STRONG_HW"
    out.loc[m_combo_hw_s, "acca_builder_bucket"] = "HW_HGE2_COMBINED"
    out.loc[m_combo_hw_s, "acca_builder_priority"] = 4
    out.loc[m_combo_hw_s, "acca_builder_rank"] = 4

    out.loc[m_combo_aw_vs, "combo_overlay_priority"] = 80
    out.loc[m_combo_aw_vs, "combo_overlay_bucket"] = "AWAY_WIN_AND_AWAY_GE2_VERY_STRONG_AW"
    out.loc[m_combo_aw_vs, "acca_builder_bucket"] = "AW_AGE2_COMBINED"
    out.loc[m_combo_aw_vs, "acca_builder_priority"] = 5
    out.loc[m_combo_aw_vs, "acca_builder_rank"] = 5

    out.loc[m_combo_aw_s, "combo_overlay_priority"] = 75
    out.loc[m_combo_aw_s, "combo_overlay_bucket"] = "AWAY_WIN_AND_AWAY_GE2_STRONG_AW"
    out.loc[m_combo_aw_s, "acca_builder_bucket"] = "AW_AGE2_COMBINED"
    out.loc[m_combo_aw_s, "acca_builder_priority"] = 6
    out.loc[m_combo_aw_s, "acca_builder_rank"] = 6

    out.loc[m_ou25_vs, "combo_overlay_priority"] = 70
    out.loc[m_ou25_vs, "combo_overlay_bucket"] = "OU25_VERY_STRONG"
    out.loc[m_ou25_vs, "acca_builder_bucket"] = "OU25_VS"
    out.loc[m_ou25_vs, "acca_builder_priority"] = 7
    out.loc[m_ou25_vs, "acca_builder_rank"] = 7
    
    # Final normalize: ensure identity fields are always non-null strings
    out["product_profile"] = out["product_profile"].astype("string").fillna("").str.strip()
    out["product_lane"] = out["product_lane"].astype("string").fillna("").str.strip()

    return out

def _append_reason_token(df: pd.DataFrame, col: str, mask: pd.Series, token: str) -> None:
    """Append a token into a pipe-separated reason column."""
    if df is None or df.empty:
        return
    if col not in df.columns:
        df[col] = ""
    s = df[col].astype("string").fillna("")
    df.loc[mask, col] = s.loc[mask].map(lambda x: _combine_pipe(x, token))

def extract_draw_warning_token_bucket(series: pd.Series) -> pd.Series:
    reason_codes = (
        series.astype("string")
        .fillna("")
        .str.upper()
        .str.strip()
    )
    out = pd.Series("NO_DRAWWARN", index=reason_codes.index, dtype="string")

    out = out.mask(reason_codes.str.contains("OBSERVE_RESCUE", regex=False), "OBSERVE_RESCUE")
    out = out.mask(reason_codes.str.contains("CS_PROMOTE", regex=False), "CS_PROMOTED")
    out = out.mask(reason_codes.str.contains("ULTRASHORT", regex=False), "ULTRASHORT")
    out = out.mask(reason_codes.str.contains("DEMOTED", regex=False), "DEMOTED")
    out = out.mask(reason_codes.str.contains("NOT_GLUE", regex=False), "NOT_GLUE")
    out = out.mask(reason_codes.str.contains("CHAOS", regex=False), "CHAOS")
    out = out.mask(reason_codes.str.contains("DRAW", regex=False), "DRAW_TOKEN")

    multi_mask = (
        reason_codes.str.contains("OBSERVE_RESCUE", regex=False)
        & reason_codes.str.contains("CHAOS", regex=False)
    )
    out = out.mask(multi_mask, "OBSERVE_RESCUE_PLUS_CHAOS")
    return out.astype("string").fillna("NO_DRAWWARN")

def _stamp_btts_runtime_fields(df: pd.DataFrame) -> pd.DataFrame:
    """Stamp BTTS alignment/runtime labels on any BTTS rows in a frame.

    Rules:
    - aligned rows keep side-aware label (fallback to signal_btts)
    - contrarian rows are downgraded to NEUTRAL
    - non-BTTS rows are left untouched
    """
    if df is None:
        return pd.DataFrame()

    out = df.copy()
    if out.empty:
        return out

    market = out.get("market", pd.Series("", index=out.index)).astype("string").fillna("").str.strip().str.lower()
    is_btts = market.eq("btts")
    if not bool(is_btts.any()):
        return out

    if "btts_alignment" not in out.columns:
        out["btts_alignment"] = pd.Series(pd.NA, index=out.index, dtype="string")
    else:
        out["btts_alignment"] = out["btts_alignment"].astype("string")

    if "signal_btts_runtime" not in out.columns:
        out["signal_btts_runtime"] = pd.Series(pd.NA, index=out.index, dtype="string")
    else:
        out["signal_btts_runtime"] = out["signal_btts_runtime"].astype("string")

    bt = out.loc[is_btts].copy()
    _sel = bt.get("selection", pd.Series("", index=bt.index)).astype("string").fillna("").str.upper().str.strip()
    _top = bt.get("model_top_pick", pd.Series("", index=bt.index)).astype("string").fillna("").str.upper().str.strip()

    _side_sig = bt.get("signal_btts_side", pd.Series(pd.NA, index=bt.index)).astype("string")
    _base_sig = bt.get("signal_btts", pd.Series("", index=bt.index)).astype("string").fillna("").str.upper().str.strip()

    _aligned = _sel.eq(_top)
    _runtime = _side_sig.fillna(_base_sig).astype("string").fillna("").str.upper().str.strip()
    _runtime = _runtime.where(_aligned, "NEUTRAL")

    out.loc[is_btts, "btts_alignment"] = pd.Series(
        np.where(_aligned, "ALIGNED", "CONTRARIAN"),
        index=bt.index,
        dtype="string",
    )
    out.loc[is_btts, "signal_btts_runtime"] = pd.Series(_runtime, index=bt.index, dtype="string")
    return out

def _stamp_ou25_runtime_fields(df: pd.DataFrame) -> pd.DataFrame:
    """Stamp OU25 policy/runtime fields on any OU25 rows in a frame.

    This is a runtime identity layer (not a learned gate replay).
    It is designed to be resilient to missing upstream policy columns.

    Fields stamped when missing:
      - ou25_policy_mode / ou25_policy_branch / ou25_policy_state
      - ou25_runtime_lane
      - ou25_is_shadow
      - ou25_is_premium_candidate
    """
    if df is None:
        return pd.DataFrame()

    out = df.copy()
    if out.empty:
        return out

    market = out.get("market", pd.Series("", index=out.index)).astype("string").fillna("").str.strip().str.lower()
    is_ou = market.eq("ou25")
    if not bool(is_ou.any()):
        return out

    # Ensure columns exist
    for c in [
        "ou25_policy_mode",
        "ou25_policy_branch",
        "ou25_policy_state",
        "ou25_runtime_lane",
        "ou25_is_shadow",
        "ou25_is_premium_candidate",
    ]:
        if c not in out.columns:
            out[c] = pd.NA

    league = out.get("league", pd.Series("", index=out.index)).astype("string").fillna("").str.strip()
    pick = out.get("bookie_pick", out.get("selection", pd.Series("", index=out.index))).astype("string").fillna("").str.upper().str.strip()

    # Review state by league
    is_review = league.isin(list(OU25_REVIEW_LEAGUES)).fillna(False)

    # Default policy stamps (only where blank)
    mode = out["ou25_policy_mode"].astype("string").fillna("").str.strip()
    branch = out["ou25_policy_branch"].astype("string").fillna("").str.strip()
    state = out["ou25_policy_state"].astype("string").fillna("").str.strip()

    # Live defaults apply only to OVER25 rows
    m_live_default = is_ou & pick.eq("OVER25") & mode.eq("")
    out.loc[m_live_default, "ou25_policy_mode"] = OU25_LIVE_MODE
    out.loc[m_live_default & branch.eq(""), "ou25_policy_branch"] = OU25_LIVE_BRANCH

    # Under rows are not part of the live posture
    m_under_default = is_ou & pick.ne("OVER25") & mode.eq("")
    out.loc[m_under_default, "ou25_policy_mode"] = "observe_only"
    out.loc[m_under_default & branch.eq(""), "ou25_policy_branch"] = ""

    # Policy state defaults
    out.loc[is_ou & state.eq("") & is_review, "ou25_policy_state"] = "review"
    out.loc[is_ou & state.eq("") & (~is_review), "ou25_policy_state"] = "live"

    # Runtime lane: if upstream provided it, keep; else derive from policy mode
    lane = out["ou25_runtime_lane"].astype("string").fillna("").str.strip()
    out.loc[
        is_ou
        & lane.eq("")
        & out["ou25_policy_mode"].astype("string").fillna("").str.contains("shadow", case=False, regex=False),
        "ou25_runtime_lane",
    ] = OU25_SHADOW_MODE
    out.loc[
        is_ou
        & lane.eq("")
        & out["ou25_policy_mode"].astype("string").fillna("").str.contains("filtered", case=False, regex=False),
        "ou25_runtime_lane",
    ] = OU25_LIVE_MODE
    out.loc[
        is_ou
        & out["ou25_runtime_lane"].astype("string").fillna("").str.strip().eq(""),
        "ou25_runtime_lane",
    ] = out.loc[is_ou, "ou25_policy_mode"].astype("string").fillna("")

    # Shadow flag: prefer explicit marker if present; else infer from mode/lane/model_lane
    model_lane = out.get("model_lane", pd.Series("", index=out.index)).astype("string").fillna("").str.lower()
    runtime_lane_lower = out.get("ou25_runtime_lane", pd.Series("", index=out.index)).astype("string").fillna("").str.lower().str.strip()
    model_lane_lower = out.get("model_lane", pd.Series("", index=out.index)).astype("string").fillna("").str.lower().str.strip()

    inferred_shadow = (
        runtime_lane_lower.eq(str(OU25_SHADOW_MODE).lower())
        | model_lane_lower.eq("dedicated_over25_model")
        | model_lane_lower.str.contains("shadow", regex=False)
    )
    sh_num = pd.to_numeric(out["ou25_is_shadow"], errors="coerce")
    out.loc[is_ou & sh_num.isna(), "ou25_is_shadow"] = inferred_shadow.loc[is_ou].astype(int)

    # Premium candidate: prefer explicit marker; else infer from branch OR strong signal + p_model
    br = out.get("ou25_policy_branch", pd.Series("", index=out.index)).astype("string").fillna("").str.strip()
    sig_over = _normalize_signal_label_series(_get_ou25_signal_series(out, default=""), default="")
    pm = pd.to_numeric(out.get("model_p_for_bookie", np.nan), errors="coerce")

    inferred_premium = (
        br.eq(OU25_PREMIUM_BRANCH)
        | (sig_over.isin(["STRONG_OVER", "VERY_STRONG_OVER"]).fillna(False) & (pm >= 0.60).fillna(False))
    )
    prem_num = pd.to_numeric(out["ou25_is_premium_candidate"], errors="coerce")
    out.loc[is_ou & prem_num.isna(), "ou25_is_premium_candidate"] = inferred_premium.loc[is_ou].astype(int)

    # Re-assert review override state
    out.loc[is_ou & is_review, "ou25_policy_state"] = "review"

    return out


def _detect_ou25_shadow_rows(df: pd.DataFrame) -> pd.Series:
    """Return True for OU25 rows that represent the dedicated shadow model lane."""
    if df is None or df.empty:
        return pd.Series(False, index=getattr(df, "index", pd.RangeIndex(0)))

    out = _stamp_ou25_runtime_fields(df)

    market = out.get("market", pd.Series("", index=out.index)).astype("string").fillna("").str.strip().str.lower()
    is_ou = market.eq("ou25")
    if not bool(is_ou.any()):
        return pd.Series(False, index=out.index)

    sh = pd.to_numeric(
        out.get("ou25_is_shadow", pd.Series(0, index=out.index)),
        errors="coerce",
    ).fillna(0).astype(int)
    lane = out.get("ou25_runtime_lane", pd.Series("", index=out.index)).astype("string").fillna("").str.lower().str.strip()
    model_lane = out.get("model_lane", pd.Series("", index=out.index)).astype("string").fillna("").str.lower()

    return is_ou & (
        (sh >= 1)
        | lane.eq(str(OU25_SHADOW_MODE).lower())
        | model_lane.eq("dedicated_over25_model")
        | model_lane.str.contains("shadow", regex=False)
    )

def _eligible_ou25_premium_rows(df: pd.DataFrame) -> pd.Series:
    """Return True for OU25 rows eligible for PREMIUM whitelist STANDARD posture."""
    if df is None or df.empty:
        return pd.Series(False, index=getattr(df, "index", pd.RangeIndex(0)))

    out = _stamp_ou25_runtime_fields(df)
    out = _stamp_ou25_over_live_features(out)

    market = out.get("market", pd.Series("", index=out.index)).astype("string").fillna("").str.strip().str.lower()
    is_ou = market.eq("ou25")

    pick = out.get("bookie_pick", out.get("selection", pd.Series("", index=out.index))).astype("string").fillna("").str.upper().str.strip()
    is_over = pick.eq("OVER25")

    state = out.get("ou25_policy_state", pd.Series("", index=out.index)).astype("string").fillna("").str.lower().str.strip()
    not_review = ~state.eq("review")

    is_shadow = _detect_ou25_shadow_rows(out)

    prem_flag = pd.to_numeric(
        out.get("ou25_is_premium_candidate", pd.Series(0, index=out.index)),
        errors="coerce",
    ).fillna(0).astype(int)
    branch = out.get("ou25_policy_branch", pd.Series("", index=out.index)).astype("string").fillna("").str.strip()
    league = out.get("league", pd.Series("", index=out.index)).astype("string").fillna("").str.strip()
    model_p = pd.to_numeric(out.get("model_p_for_bookie", np.nan), errors="coerce")

    structural_ok = _ou25_struct_combo_mask(out) & _ou25_top3_mask(out)

    premium_flag = ((prem_flag >= 1) | branch.eq(OU25_PREMIUM_BRANCH))

    premium_floor = pd.Series(0.60, index=out.index, dtype="float64")
    if isinstance(OU25_PREMIUM_WHITELIST_MODEL_P_FLOORS, dict):
        for _lg, _minp in OU25_PREMIUM_WHITELIST_MODEL_P_FLOORS.items():
            try:
                premium_floor.loc[league.eq(str(_lg))] = float(_minp)
            except Exception:
                continue
    premium_model_ok = model_p.notna() & model_p.ge(premium_floor)

    return (
        is_ou
        & is_over
        & not_review
        & (~is_shadow)
        & premium_flag
        & structural_ok.fillna(False)
        & premium_model_ok
    )


def _eligible_ou25_uefa_premium_rescue_rows(df: pd.DataFrame) -> pd.Series:
    """Return True for narrow UEFA OVER25 rescue rows validated by the loss audit."""
    if df is None or df.empty:
        return pd.Series(False, index=getattr(df, "index", pd.RangeIndex(0)))

    out = _stamp_ou25_runtime_fields(df.copy())
    out = _stamp_ou25_over_live_features(out)

    market = out.get("market", pd.Series("", index=out.index)).astype("string").fillna("").str.strip().str.lower()
    pick = out.get("bookie_pick", out.get("selection", pd.Series("", index=out.index))).astype("string").fillna("").str.upper().str.strip()
    league = out.get("league", pd.Series("", index=out.index)).astype("string").fillna("").str.strip()
    state = out.get("ou25_policy_state", pd.Series("", index=out.index)).astype("string").fillna("").str.lower().str.strip()
    signal = out.get("signal_over25", pd.Series("", index=out.index)).astype("string").fillna("").str.upper().str.strip()
    branch = out.get("ou25_policy_branch", pd.Series("", index=out.index)).astype("string").fillna("").str.strip()
    lane = out.get("ou25_runtime_lane", pd.Series("", index=out.index)).astype("string").fillna("").str.strip()
    ctx = out.get("context_reason_codes", pd.Series("", index=out.index)).astype("string").fillna("")

    model_p = pd.to_numeric(out.get("model_p_for_bookie", np.nan), errors="coerce")
    exp_goals_sum = pd.to_numeric(out.get("exp_goals_sum", np.nan), errors="coerce")
    xg_sum_pre_match = pd.to_numeric(out.get("xg_sum_pre_match", np.nan), errors="coerce")
    lambda_total = pd.to_numeric(out.get("bookie_lambda_total_fit", np.nan), errors="coerce")
    p00_est = pd.to_numeric(out.get("p00_est", np.nan), errors="coerce")

    is_shadow = _detect_ou25_shadow_rows(out)
    is_uefa = league.isin(list(OU25_HYBRID_UEFA_PREMIUM_RESCUE_LEAGUES)).fillna(False)
    is_ou_over = market.eq("ou25") & pick.eq("OVER25")
    not_review = ~state.eq("review")
    signal_ok = signal.eq("VERY_STRONG_OVER")
    premium_shape = branch.eq(OU25_PREMIUM_BRANCH) | lane.eq("ou25_premium")
    denylist_shape = ctx.str.contains("OU25_OVER25_BTTS_YES_RESCUE_DENYLIST", na=False)
    shape_ok = premium_shape | denylist_shape
    model_ok = model_p.notna() & model_p.ge(float(OU25_HYBRID_UEFA_PREMIUM_RESCUE_MODEL_P_MIN))
    goals_ok = (
        (exp_goals_sum.notna() & exp_goals_sum.ge(float(OU25_HYBRID_UEFA_PREMIUM_RESCUE_EXP_GOALS_MIN)))
        | (xg_sum_pre_match.notna() & xg_sum_pre_match.ge(float(OU25_HYBRID_UEFA_PREMIUM_RESCUE_XG_SUM_MIN)))
        | (lambda_total.notna() & lambda_total.ge(float(OU25_HYBRID_UEFA_PREMIUM_RESCUE_LAMBDA_MIN)))
    )
    p00_ok = p00_est.notna() & p00_est.le(float(OU25_HYBRID_UEFA_PREMIUM_RESCUE_P00_MAX))

    return (
        is_ou_over
        & is_uefa
        & not_review
        & (~is_shadow)
        & signal_ok
        & shape_ok
        & model_ok
        & goals_ok
        & p00_ok
    )


