def _eligible_ou25_diffuse_top3_timing_shadow_rows(df: pd.DataFrame) -> pd.Series:
    """Shadow-only refinement for Portugal/Spain diffuse-top3 rows with supportive timing shape."""
    if df is None or df.empty:
        return pd.Series(False, index=getattr(df, "index", pd.Index([])))

    out = _stamp_ou25_runtime_fields(df.copy())
    base = _eligible_ou25_diffuse_top3_shadow_rows(out)
    if not bool(base.any()):
        return pd.Series(False, index=out.index)

    league = out.get("league", pd.Series("", index=out.index)).astype("string").fillna("").str.strip()
    s2h = _to_num(_col(out, "snap_timing_second_half_acceleration"))
    regime = _to_num(_col(out, "snap_ou25_over_regime_blend"))

    target = league.isin(list(OU25_DIFFUSE_TOP3_TIMING_SHADOW_LEAGUES)).fillna(False)
    s2h_ok = pd.Series(False, index=out.index)
    regime_ok = pd.Series(False, index=out.index)
    for lg, med in OU25_DIFFUSE_TOP3_TIMING_SHADOW_S2H_MEDIANS.items():
        s2h_ok = s2h_ok | (league.eq(lg) & s2h.notna() & s2h.ge(float(med)))
    for lg, med in OU25_DIFFUSE_TOP3_TIMING_SHADOW_REGIME_MEDIANS.items():
        regime_ok = regime_ok | (league.eq(lg) & regime.notna() & regime.ge(float(med)))

    return (base & target & s2h_ok & regime_ok).fillna(False)


def _ou25_implied_rescue_labels(df: pd.DataFrame) -> pd.DataFrame:
    """Return implied-rescue token/tier labels for OU25 OVER25 rows in efficient markets."""
    if df is None or df.empty:
        return pd.DataFrame(index=getattr(df, "index", pd.RangeIndex(0)))

    out = _stamp_ou25_runtime_fields(df)
    market = out.get("market", pd.Series("", index=out.index)).astype("string").fillna("").str.strip().str.lower()
    pick = out.get("bookie_pick", out.get("selection", pd.Series("", index=out.index))).astype("string").fillna("").str.upper().str.strip()
    league = out.get("league", pd.Series("", index=out.index)).astype("string").fillna("").str.strip()
    state = out.get("ou25_policy_state", pd.Series("", index=out.index)).astype("string").fillna("").str.lower().str.strip()

    is_ou_over = market.eq("ou25") & pick.eq("OVER25")
    not_review = ~state.eq("review")
    implied_p = pd.to_numeric(out.get("bookie_implied", np.nan), errors="coerce")
    model_p = pd.to_numeric(out.get("model_p_for_bookie", np.nan), errors="coerce")

    token = pd.Series("", index=out.index, dtype="string")
    target_tier = pd.Series("", index=out.index, dtype="string")
    eligible = pd.Series(False, index=out.index, dtype="bool")

    if isinstance(OU25_IMPLIED_RESCUE_CONFIG, dict):
        for lg, cfg in OU25_IMPLIED_RESCUE_CONFIG.items():
            try:
                implied_t = float(cfg.get("implied_t", 9.99))
                model_t = float(cfg.get("model_t", 9.99))
            except Exception:
                continue
            token_value = str(cfg.get("token", "")).strip()
            tier_value = str(cfg.get("tier", "")).strip().upper()
            mask = (
                is_ou_over
                & not_review
                & league.eq(str(lg))
                & implied_p.notna()
                & model_p.notna()
                & implied_p.ge(implied_t)
                & model_p.ge(model_t)
            )
            if bool(mask.any()):
                eligible.loc[mask] = True
                token.loc[mask] = token_value
                target_tier.loc[mask] = tier_value

    return pd.DataFrame(
        {
            "eligible": eligible,
            "token": token,
            "target_tier": target_tier,
        },
        index=out.index,
    )

def _safe_num_series_ou25_live(df: pd.DataFrame, col: str, default=np.nan) -> pd.Series:
    return pd.to_numeric(df.get(col, pd.Series(default, index=df.index)), errors="coerce")


def _score_total_goals_from_cs_ou25_live(score: object) -> float:
    try:
        s = str(score).strip()
        if "-" not in s:
            return np.nan
        h, a = s.split("-", 1)
        return float(int(h) + int(a))
    except Exception:
        return np.nan


def _first_existing_num_series_ou25_live(df: pd.DataFrame, cols: list[str], default=np.nan) -> pd.Series:
    for col in cols:
        if col in df.columns:
            s = _safe_num_series_ou25_live(df, col, default=default)
            if s.notna().any():
                return s
    return pd.Series(default, index=df.index, dtype="float64")


def _compute_avg_btts_rate_live(df: pd.DataFrame) -> pd.Series:
    home = _first_existing_num_series_ou25_live(
        df,
        [
            "btts_rate_5_home",
            "avg_btts_rate_home",
            "rolling_btts_rate_5_home",
            "btts_rate_10_home",
            "home_snap__btts_percentage_home",
            "home_snap__btts_percentage",
            "btts_percentage_pre_match",
        ],
    )
    away = _first_existing_num_series_ou25_live(
        df,
        [
            "btts_rate_5_away",
            "avg_btts_rate_away",
            "rolling_btts_rate_5_away",
            "btts_rate_10_away",
            "away_snap__btts_percentage_away",
            "away_snap__btts_percentage",
            "btts_percentage_pre_match",
        ],
    )

    home = home.where(home <= 1.0, home / 100.0)
    away = away.where(away <= 1.0, away / 100.0)
    return (home + away) / 2.0



def _compute_cs_over25_mass_live(df: pd.DataFrame) -> pd.Series:
    out_part = pd.Series(0.0, index=df.index, dtype="float64")
    for score_col, prob_col in [("cs1", "cs1_p"), ("cs2", "cs2_p"), ("cs3", "cs3_p")]:
        if score_col not in df.columns or prob_col not in df.columns:
            continue
        totals = df[score_col].map(_score_total_goals_from_cs_ou25_live)
        probs = _safe_num_series_ou25_live(df, prob_col).fillna(0.0)
        out_part = out_part + probs.where(totals > 2.0, 0.0)
    return out_part


def _compute_top3_over_count_live(df: pd.DataFrame) -> pd.Series:
    out_part = pd.Series(0, index=df.index, dtype="int64")
    for score_col in ["cs1", "cs2", "cs3"]:
        if score_col not in df.columns:
            continue
        totals = df[score_col].map(_score_total_goals_from_cs_ou25_live)
        out_part = out_part + (totals > 2.0).fillna(False).astype(int)
    return out_part


# --- OU25 live helper section: additional helpers ---
def _score_side_from_cs_ou25_live(score: object) -> str:
    try:
        s = str(score).strip()
        if "-" not in s:
            return ""
        h, a = s.split("-", 1)
        h = int(h)
        a = int(a)
        if h > a:
            return "HOME"
        if a > h:
            return "AWAY"
        return "DRAW"
    except Exception:
        return ""


def _score_btts_from_cs_ou25_live(score: object) -> float:
    try:
        s = str(score).strip()
        if "-" not in s:
            return np.nan
        h, a = s.split("-", 1)
        h = int(h)
        a = int(a)
        return float((h > 0) and (a > 0))
    except Exception:
        return np.nan


def _compute_one_sided_no_btts_live(df: pd.DataFrame) -> pd.Series:
    out_part = pd.Series(0, index=df.index, dtype="int64")

    sides = []
    btts_flags = []

    for score_col in ["cs1", "cs2", "cs3"]:
        if score_col in df.columns:
            sides.append(df[score_col].map(_score_side_from_cs_ou25_live))
            btts_flags.append(df[score_col].map(_score_btts_from_cs_ou25_live))
        else:
            sides.append(pd.Series("", index=df.index, dtype="string"))
            btts_flags.append(pd.Series(np.nan, index=df.index, dtype="float64"))

    cs1_side, cs2_side, cs3_side = sides
    cs1_btts, cs2_btts, cs3_btts = btts_flags

    same_home = cs1_side.eq("HOME") & cs2_side.eq("HOME") & cs3_side.eq("HOME")
    same_away = cs1_side.eq("AWAY") & cs2_side.eq("AWAY") & cs3_side.eq("AWAY")
    same_side = same_home | same_away

    any_btts = (
        cs1_btts.fillna(0).astype(int)
        + cs2_btts.fillna(0).astype(int)
        + cs3_btts.fillna(0).astype(int)
    ) >= 1

    out_part = (same_side & (~any_btts)).astype("int64")
    return out_part


def _stamp_ou25_over_live_features(df_part: pd.DataFrame) -> pd.DataFrame:
    if df_part is None:
        return pd.DataFrame()

    out_part = df_part.copy()
    if out_part.empty:
        for c in ["avg_btts_rate", "cs_over25_mass", "top3_over_count", "one_sided_no_btts"]:
            if c not in out_part.columns:
                out_part[c] = pd.Series(dtype="float64")
        return out_part

    out_part["avg_btts_rate"] = _compute_avg_btts_rate_live(out_part)
    out_part["cs_over25_mass"] = _compute_cs_over25_mass_live(out_part)
    out_part["top3_over_count"] = _compute_top3_over_count_live(out_part).astype("float64")
    out_part["one_sided_no_btts"] = _compute_one_sided_no_btts_live(out_part).astype("float64")
    return out_part
def _score_home_clean_sheet_from_cs_btts_live(score: object) -> float:
    try:
        s = str(score).strip()
        if "-" not in s:
            return np.nan
        h, a = s.split("-", 1)
        h = int(h)
        a = int(a)
        return float(a == 0)
    except Exception:
        return np.nan


def _score_away_clean_sheet_from_cs_btts_live(score: object) -> float:
    try:
        s = str(score).strip()
        if "-" not in s:
            return np.nan
        h, a = s.split("-", 1)
        h = int(h)
        a = int(a)
        return float(h == 0)
    except Exception:
        return np.nan


def _compute_cs_home_from_top3_live(df: pd.DataFrame) -> pd.Series:
    out_part = pd.Series(0.0, index=df.index, dtype="float64")
    for score_col, prob_col in [("cs1", "cs1_p"), ("cs2", "cs2_p"), ("cs3", "cs3_p")]:
        if score_col not in df.columns or prob_col not in df.columns:
            continue
        flags = df[score_col].map(_score_home_clean_sheet_from_cs_btts_live)
        probs = pd.to_numeric(df.get(prob_col, pd.Series(np.nan, index=df.index)), errors="coerce").fillna(0.0)
        out_part = out_part + probs.where(flags.fillna(0).astype(int).eq(1), 0.0)
    return out_part


def _compute_cs_away_from_top3_live(df: pd.DataFrame) -> pd.Series:
    out_part = pd.Series(0.0, index=df.index, dtype="float64")
    for score_col, prob_col in [("cs1", "cs1_p"), ("cs2", "cs2_p"), ("cs3", "cs3_p")]:
        if score_col not in df.columns or prob_col not in df.columns:
            continue
        flags = df[score_col].map(_score_away_clean_sheet_from_cs_btts_live)
        probs = pd.to_numeric(df.get(prob_col, pd.Series(np.nan, index=df.index)), errors="coerce").fillna(0.0)
        out_part = out_part + probs.where(flags.fillna(0).astype(int).eq(1), 0.0)
    return out_part


def _stamp_btts_yes_live_features(df_part: pd.DataFrame) -> pd.DataFrame:
    if df_part is None:
        return pd.DataFrame()

    out_part = df_part.copy()
    if out_part.empty:
        for c in [
            "cs_home",
            "cs_away",
            "cs00_top3_mass",
            "btts_top3_mass",
            "top3_any_00",
            "fts_sum",
            "cs_sum",
            "btts_yes_double_blank_shadow_block",
        ]:
            if c not in out_part.columns:
                out_part[c] = pd.Series(dtype="float64")
        return out_part

    if "cs_home" not in out_part.columns:
        out_part["cs_home"] = np.nan
    if "cs_away" not in out_part.columns:
        out_part["cs_away"] = np.nan

    cs_home_existing = pd.to_numeric(
        out_part.get("cs_home", pd.Series(np.nan, index=out_part.index)),
        errors="coerce",
    )
    cs_away_existing = pd.to_numeric(
        out_part.get("cs_away", pd.Series(np.nan, index=out_part.index)),
        errors="coerce",
    )

    cs_home_live = _compute_cs_home_from_top3_live(out_part)
    cs_away_live = _compute_cs_away_from_top3_live(out_part)

    out_part["cs_home"] = cs_home_existing.where(cs_home_existing.notna(), cs_home_live)
    out_part["cs_away"] = cs_away_existing.where(cs_away_existing.notna(), cs_away_live)

    cs_home_num = pd.to_numeric(out_part["cs_home"], errors="coerce")
    cs_away_num = pd.to_numeric(out_part["cs_away"], errors="coerce")
    out_part["cs_max"] = pd.concat([cs_home_num, cs_away_num], axis=1).max(axis=1)

    out_part = _stamp_btts_yes_double_blank_live_features(out_part)
    return out_part
def _score_is_00_from_cs_btts_live(score: object) -> float:
    try:
        s = str(score).strip()
        if "-" not in s:
            return np.nan
        h, a = s.split("-", 1)
        h = int(h)
        a = int(a)
        return float((h == 0) and (a == 0))
    except Exception:
        return np.nan


def _score_is_btts_from_cs_btts_live(score: object) -> float:
    try:
        s = str(score).strip()
        if "-" not in s:
            return np.nan
        h, a = s.split("-", 1)
        h = int(h)
        a = int(a)
        return float((h > 0) and (a > 0))
    except Exception:
        return np.nan


def _compute_cs00_top3_mass_btts_live(df: pd.DataFrame) -> pd.Series:
    out_part = pd.Series(0.0, index=df.index, dtype="float64")
    for score_col, prob_col in [("cs1", "cs1_p"), ("cs2", "cs2_p"), ("cs3", "cs3_p")]:
        if score_col not in df.columns or prob_col not in df.columns:
            continue
        flags = df[score_col].map(_score_is_00_from_cs_btts_live)
        probs = pd.to_numeric(df.get(prob_col, pd.Series(np.nan, index=df.index)), errors="coerce").fillna(0.0)
        out_part = out_part + probs.where(flags.fillna(0).astype(int).eq(1), 0.0)
    return out_part


def _compute_btts_top3_mass_btts_live(df: pd.DataFrame) -> pd.Series:
    out_part = pd.Series(0.0, index=df.index, dtype="float64")
    for score_col, prob_col in [("cs1", "cs1_p"), ("cs2", "cs2_p"), ("cs3", "cs3_p")]:
        if score_col not in df.columns or prob_col not in df.columns:
            continue
        flags = df[score_col].map(_score_is_btts_from_cs_btts_live)
        probs = pd.to_numeric(df.get(prob_col, pd.Series(np.nan, index=df.index)), errors="coerce").fillna(0.0)
        out_part = out_part + probs.where(flags.fillna(0).astype(int).eq(1), 0.0)
    return out_part


def _compute_any_top3_00_btts_live(df: pd.DataFrame) -> pd.Series:
    out_part = pd.Series(0, index=df.index, dtype="int64")
    for score_col in ["cs1", "cs2", "cs3"]:
        if score_col not in df.columns:
            continue
        is_00 = df[score_col].map(_score_is_00_from_cs_btts_live).fillna(0).astype(int)
        out_part = np.maximum(out_part, is_00)
    return pd.Series(out_part, index=df.index, dtype="int64")


def _stamp_btts_yes_double_blank_live_features(df_part: pd.DataFrame) -> pd.DataFrame:
    if df_part is None:
        return pd.DataFrame()

    out_part = df_part.copy()
    if out_part.empty:
        for c in [
            "cs00_top3_mass",
            "btts_top3_mass",
            "top3_any_00",
            "fts_sum",
            "cs_sum",
            "btts_yes_double_blank_shadow_block",
        ]:
            if c not in out_part.columns:
                out_part[c] = pd.Series(dtype="float64")
        return out_part


    p00_est = pd.to_numeric(out_part.get("p00_est", pd.Series(np.nan, index=out_part.index)), errors="coerce")
    exp_goals_sum = pd.to_numeric(out_part.get("exp_goals_sum", pd.Series(np.nan, index=out_part.index)), errors="coerce")
    p_home_fts = pd.to_numeric(out_part.get("p_home_fts", pd.Series(np.nan, index=out_part.index)), errors="coerce")
    p_away_fts = pd.to_numeric(out_part.get("p_away_fts", pd.Series(np.nan, index=out_part.index)), errors="coerce")
    cs_home = pd.to_numeric(out_part.get("cs_home", pd.Series(np.nan, index=out_part.index)), errors="coerce")
    cs_away = pd.to_numeric(out_part.get("cs_away", pd.Series(np.nan, index=out_part.index)), errors="coerce")

    out_part["cs00_top3_mass"] = _compute_cs00_top3_mass_btts_live(out_part)
    out_part["btts_top3_mass"] = _compute_btts_top3_mass_btts_live(out_part)
    out_part["top3_any_00"] = _compute_any_top3_00_btts_live(out_part).astype("float64")
    out_part["fts_sum"] = p_home_fts.fillna(0.0) + p_away_fts.fillna(0.0)
    out_part["cs_sum"] = cs_home.fillna(0.0) + cs_away.fillna(0.0)

    veto_00 = out_part["top3_any_00"].ge(1) | out_part["cs00_top3_mass"].ge(0.12)
    veto_p00 = p00_est.ge(0.10)
    veto_fts = out_part["fts_sum"].ge(0.62)
    veto_cs = out_part["cs_sum"].ge(0.62)
    veto_xg = exp_goals_sum.le(2.20)
    weak_btts_support = out_part["btts_top3_mass"].le(0.18)

    out_part["btts_yes_double_blank_shadow_block"] = (
        ((veto_00 & veto_xg) | (veto_p00 & weak_btts_support) | (veto_fts & veto_cs & veto_xg))
    ).astype("float64")

    return out_part


def _extract_date_range_from_name(name: str) -> tuple[str | None, str | None]:
    m = re.search(r"(\\d{4}-\\d{2}-\\d{2})_to_(\\d{4}-\\d{2}-\\d{2})", name)
    if not m:
        return None, None
    return m.group(1), m.group(2)


def _write_btts_gate_audit(
    *,
    outdir: Path,
    src: Path,
    params: Dict[str, Any],
    deploy_elite: pd.DataFrame,
    deploy_standard: pd.DataFrame,
    observe: pd.DataFrame,
) -> Path | None:
    audit = params.get("_btts_gate_audit")
    if not isinstance(audit, dict):
        try:
            print("[deploy_rulebook] BTTS gate audit skipped: params['_btts_gate_audit'] missing")
        except Exception:
            pass
        return None

    def _count_btts(df_part: pd.DataFrame) -> int:
        if df_part is None or df_part.empty:
            return 0
        mk = df_part.get("market", pd.Series("", index=df_part.index)).astype("string").fillna("").str.lower().str.strip()
        return int(mk.eq("btts").sum())

    audit = audit.copy()
    # Ensure expected keys exist so audit columns are stable across runs
    for _k in [
        "btts_yes_ge2_missing",
        "btts_yes_fts_missing",
        "btts_yes_cs_missing",
        "btts_yes_ge2_missing_prelabel",
        "btts_yes_fts_missing_prelabel",
        "btts_yes_cs_missing_prelabel",
        "btts_yes_weak_input",
        "btts_yes_standard_rescue_global",
        "btts_yes_standard_rescue_global_brazil",
        "btts_yes_standard_rescue_global_non_brazil",
        "btts_yes_standard_rescue_weak_yes",
        "btts_yes_standard_rescue_weak_yes_brazil",
        "btts_yes_standard_rescue_weak_yes_non_brazil",
    ]:
        if _k not in audit:
            audit[_k] = 0
    audit["btts_final_elite"] = _count_btts(deploy_elite)
    audit["btts_final_standard"] = _count_btts(deploy_standard)
    audit["btts_final_observe"] = _count_btts(observe)

    window_id = params.get("window_id") or ""
    date_from, date_to = _extract_date_range_from_name(src.name)
    audit["window_id"] = window_id
    audit["date_from"] = date_from or ""
    audit["date_to"] = date_to or ""
    audit["src"] = str(src)

    suppressor_cols = [
        "btts_yes_label_fail",
        "btts_yes_brazil_block",
        "btts_yes_model_floor_fail",
        "btts_yes_ge2_fail",
        "btts_yes_fts_fail",
        "btts_yes_csmax_fail",
        "btts_yes_double_blank_fail",
    ]
    top_gate = ""
    top_count = 0
    for col in suppressor_cols:
        val = int(pd.to_numeric(pd.Series([audit.get(col, 0)]), errors="coerce").fillna(0).iloc[0])
        if val > top_count:
            top_count = val
            top_gate = col
    audit["top_suppressor_gate"] = top_gate
    audit["top_suppressor_count"] = int(top_count)
    yes_input = float(pd.to_numeric(pd.Series([audit.get("btts_yes_input", 0)]), errors="coerce").fillna(0).iloc[0])
    audit["top_suppressor_share_of_yes_input"] = float(top_count / (yes_input if yes_input > 0 else 1.0))

    # Ranked top-3 suppressors
    ranking = []
    for col in suppressor_cols:
        val = int(pd.to_numeric(pd.Series([audit.get(col, 0)]), errors="coerce").fillna(0).iloc[0])
        ranking.append((col, val))
    ranking.sort(key=lambda x: x[1], reverse=True)
    for i in range(3):
        gate, count = ranking[i] if i < len(ranking) else ("", 0)
        audit[f"top{i+1}_suppressor_gate"] = gate
        audit[f"top{i+1}_suppressor_count"] = int(count)
        audit[f"top{i+1}_suppressor_share_of_yes_input"] = float(count / (yes_input if yes_input > 0 else 1.0))

    if date_from and date_to:
        out_name = f"BTTS_GATE_AUDIT__{date_from}_to_{date_to}.csv"
    else:
        out_name = f"BTTS_GATE_AUDIT__{src.stem}.csv"

    out_path = outdir / out_name
    pd.DataFrame([audit]).to_csv(out_path, index=False)
    try:
        print(f"[deploy_rulebook] BTTS gate top suppressor: {top_gate} count={top_count}")
    except Exception:
        pass

    # Per-gate breakdown by league
    by_league = audit.get("by_league")
    if isinstance(by_league, dict) and by_league:
        # Fallback: ensure btts_yes_input per-league counts are present for rate calculations
        if "btts_yes_input" not in by_league:
            fallback = audit.get("_btts_yes_input_by_league", {})
            if isinstance(fallback, dict) and fallback:
                by_league["btts_yes_input"] = dict(fallback)
        league_rows: list[dict[str, object]] = []
        for gate, league_map in by_league.items():
            if not isinstance(league_map, dict):
                continue
            for league, count in league_map.items():
                league_rows.append(
                    {
                        "window_id": window_id,
                        "date_from": date_from or "",
                        "date_to": date_to or "",
                        "gate": gate,
                        "league": league,
                        "fail_count": int(count),
                        "btts_yes_input": int(yes_input),
                        "src": str(src),
                    }
                )
        if league_rows:
            if date_from and date_to:
                league_name = f"BTTS_GATE_AUDIT_BY_LEAGUE__{date_from}_to_{date_to}.csv"
            else:
                league_name = f"BTTS_GATE_AUDIT_BY_LEAGUE__{src.stem}.csv"
            league_path = outdir / league_name
            pd.DataFrame(league_rows).to_csv(league_path, index=False)
    return out_path


def _write_ou25_gate_audit(
    *,
    outdir: Path,
    src: Path,
    params: Dict[str, Any],
    deploy_elite: pd.DataFrame,
    deploy_standard: pd.DataFrame,
    observe: pd.DataFrame,
) -> Path | None:
    audit = params.get("_ou25_gate_audit")
    if not isinstance(audit, dict):
        try:
            print("[deploy_rulebook] OU25 gate audit skipped: params['_ou25_gate_audit'] missing")
        except Exception:
            pass
        return None

    def _count_ou25(df_part: pd.DataFrame) -> int:
        if df_part is None or df_part.empty:
            return 0
        mk = df_part.get("market", pd.Series("", index=df_part.index)).astype("string").fillna("").str.lower().str.strip()
        return int(mk.eq("ou25").sum())

    audit = audit.copy()
    # Ensure expected keys exist so audit columns are stable across runs
    for _k in [
        "ou25_over_model_p_missing",
        "ou25_over_struct_inputs_missing",
        "ou25_under_model_p_missing",
        "ou25_under_struct_inputs_missing",
        "ou25_under_low_goal_inputs_missing",
    ]:
        if _k not in audit:
            audit[_k] = 0
    audit["ou25_final_elite"] = _count_ou25(deploy_elite)
    audit["ou25_final_standard"] = _count_ou25(deploy_standard)
    audit["ou25_final_observe"] = _count_ou25(observe)

    window_id = params.get("window_id") or ""
    date_from, date_to = _extract_date_range_from_name(src.name)
    audit["window_id"] = window_id
    audit["date_from"] = date_from or ""
    audit["date_to"] = date_to or ""
    audit["src"] = str(src)

    suppressor_cols = [
        "ou25_over_signal_fail",
        "ou25_over_model_floor_fail",
        "ou25_over_struct_combo_fail",
        "ou25_over_top3_fail",
        "ou25_over_one_sided_veto",
        "ou25_under_model_floor_fail",
        "ou25_under_struct_fail",
        "ou25_under_low_goal_fail",
    ]
    top_gate = ""
    top_count = 0
    for col in suppressor_cols:
        val = int(pd.to_numeric(pd.Series([audit.get(col, 0)]), errors="coerce").fillna(0).iloc[0])
        if val > top_count:
            top_count = val
            top_gate = col
    audit["top_suppressor_gate"] = top_gate
    audit["top_suppressor_count"] = int(top_count)
    ou_input = float(pd.to_numeric(pd.Series([audit.get("ou25_input", 0)]), errors="coerce").fillna(0).iloc[0])
    audit["top_suppressor_share_of_ou25_input"] = float(top_count / (ou_input if ou_input > 0 else 1.0))

    ranking = []
    for col in suppressor_cols:
        val = int(pd.to_numeric(pd.Series([audit.get(col, 0)]), errors="coerce").fillna(0).iloc[0])
        ranking.append((col, val))
    ranking.sort(key=lambda x: x[1], reverse=True)
    for i in range(3):
        gate, count = ranking[i] if i < len(ranking) else ("", 0)
        audit[f"top{i+1}_suppressor_gate"] = gate
        audit[f"top{i+1}_suppressor_count"] = int(count)
        audit[f"top{i+1}_suppressor_share_of_ou25_input"] = float(count / (ou_input if ou_input > 0 else 1.0))

    if date_from and date_to:
        out_name = f"OU25_GATE_AUDIT__{date_from}_to_{date_to}.csv"
    else:
        out_name = f"OU25_GATE_AUDIT__{src.stem}.csv"

    out_path = outdir / out_name
    pd.DataFrame([audit]).to_csv(out_path, index=False)
    try:
        print(f"[deploy_rulebook] OU25 gate top suppressor: {top_gate} count={top_count}")
    except Exception:
        pass

    by_league = audit.get("by_league")
    if isinstance(by_league, dict) and by_league:
        # Fallback: ensure ou25_input per-league counts are present for rate calculations
        if "ou25_input" not in by_league:
            fallback = audit.get("_ou25_input_by_league", {})
            if isinstance(fallback, dict) and fallback:
                by_league["ou25_input"] = dict(fallback)
        league_rows: list[dict[str, object]] = []
        for gate, league_map in by_league.items():
            if not isinstance(league_map, dict):
                continue
            for league, count in league_map.items():
                league_rows.append(
                    {
                        "window_id": window_id,
                        "date_from": date_from or "",
                        "date_to": date_to or "",
                        "gate": gate,
                        "league": league,
                        "fail_count": int(count),
                        "ou25_input": int(ou_input),
                        "src": str(src),
                    }
                )
        if league_rows:
            if date_from and date_to:
                league_name = f"OU25_GATE_AUDIT_BY_LEAGUE__{date_from}_to_{date_to}.csv"
            else:
                league_name = f"OU25_GATE_AUDIT_BY_LEAGUE__{src.stem}.csv"
            league_path = outdir / league_name
            pd.DataFrame(league_rows).to_csv(league_path, index=False)
    return out_path


