def _get_btts_signal_series(df: pd.DataFrame, default: str = "") -> pd.Series:
    """
    Canonical BTTS signal label column is `signal_btts`.
    Returns an index-aligned string Series.
    """
    if df is None:
        return pd.Series(dtype="string")

    s = None
    if "signal_btts" in df.columns:
        s = df["signal_btts"]

    if s is None:
        s = pd.Series(default, index=df.index, dtype="string")
    else:
        s = pd.Series(s, index=df.index)

    return s.astype("string").fillna(default)

def _normalize_signal_label_series(s: pd.Series, default: str = "") -> pd.Series:
    """
    Normalize learned-gate signal label values for robust comparisons.

    - Cast to pandas StringDtype
    - Fill nulls
    - Trim whitespace
    - Uppercase

    Returns an index-preserving string Series.
    """
    if s is None:
        return pd.Series(dtype="string")
    return pd.Series(s).astype("string").fillna(default).str.strip().str.upper()

def _normalize_allowed_labels(labels: object) -> set[str]:
    """
    Normalize learned side-gate allowlist labels for robust membership checks.

    Accepts set/list/tuple/iterable-ish values and returns uppercase trimmed strings.
    Empty/blank values are dropped.
    """
    if labels is None:
        return set()
    try:
        return {str(x).strip().upper() for x in labels if str(x).strip()}
    except Exception:
        return set()
