def _select_ftr_valueev_lane(
    ftr: pd.DataFrame,
    *,
    params: Dict[str, Any],
) -> pd.DataFrame:
    """Select ValueEV FTR rows (lane selection).

    Selects from ANCHOR_CAND rows, ranks by edge and stability, and returns only
    the chosen set.

    Expects `_compute_ftr_valueev_edge(df, metric=...)` to exist elsewhere in this module.
    """
    if ftr is None or ftr.empty:
        return ftr

    prof = _normalize_ftr_profile(params.get("ftr_profile", "valueev_balanced") or "valueev_balanced")

    # Default ValueEV edge metric should be ratio_novig unless explicitly overridden.
    metric = str(params.get("ftr_edge_metric", "") or "").strip().lower()
    if metric not in ("gap_novig", "ratio_novig"):
        metric = "ratio_novig"

    topk = int(params.get("ftr_valueev_topk_per_league", 0)) # default 0 = no cap

    # Only from ANCHOR_CAND by default (this is the “value hunting” pool)
    pt = ftr.get("pool_tier", pd.Series("", index=ftr.index)).astype("string").fillna("").str.upper().str.strip()
    is_anchor = pt.eq("ANCHOR_CAND")

    cand = ftr.loc[is_anchor].copy()

    if cand.empty:
        # Fallback: candidates weren’t emitted into ALLMARKETS (common if --emit-ftr-candidates wasn’t used).
        cand = ftr.copy()

        # breadcrumb for audit/debug
        if "context_reason_codes" not in cand.columns:
            cand["context_reason_codes"] = ""
        cand["context_reason_codes"] = cand["context_reason_codes"].astype("string").fillna("").map(
            lambda x: _combine_pipe(x, "VALUEEV_FALLBACK_NONANCHOR")
        )

        if bool(params.get("debug", False)):
            try:
                print(f"[deploy_rulebook] ValueEV: no ANCHOR_CAND rows found; using fallback pool. pool_tier_counts={pt.value_counts(dropna=False).to_dict()}")
            except Exception:
                pass

    # Compute edge
    cand["ftr_valueev_edge"] = _compute_ftr_valueev_edge(cand, metric=metric)

    # Basic sanity thresholds (aligned to audited ValueEV lanes)
    # ratio_novig edge = (p/imp - 1). So 1.05 => 0.05.
    if prof == "valueev_aggressive":
        od_min = 1.80
        margin_min = 0.03
        edge_min = 0.08 if metric == "ratio_novig" else 0.03
    else:
        # valueev_balanced (default)
        od_min = 1.80
        margin_min = 0.03  # you can push to 0.05 later if you want stricter stability
        edge_min = 0.05 if metric == "ratio_novig" else 0.02

    od = pd.to_numeric(cand.get("bookie_od", np.nan), errors="coerce")
    marg = pd.to_numeric(cand.get("ftr_margin", np.nan), errors="coerce")
    edge = pd.to_numeric(cand.get("ftr_valueev_edge", np.nan), errors="coerce")

    keep = (
        od.notna() & (od >= od_min) &
        edge.notna() & (edge >= edge_min) &
        (marg.isna() | (marg >= margin_min))  # fail-open if margin missing
    )
    # Debug breakdown: which gate is killing candidates?
    if bool(params.get("debug", False)):
        try:
            od_ok = od.notna() & (od >= od_min)
            edge_ok = edge.notna() & (edge >= edge_min)
            marg_ok = (marg.isna() | (marg >= margin_min))

            n_all = int(len(cand))
            n_od = int(od_ok.sum())
            n_edge = int(edge_ok.sum())
            n_marg = int(marg_ok.sum())
            n_keep = int(keep.fillna(False).sum())

            # Edge stats for ANCHOR_CAND subset (pre-keep)
            pt_dbg = cand.get("pool_tier", pd.Series("", index=cand.index)).astype("string").fillna("").str.upper().str.strip()
            is_anchor_dbg = pt_dbg.eq("ANCHOR_CAND")
            e_anchor = pd.to_numeric(edge.where(is_anchor_dbg), errors="coerce")

            def _fmt_stats(s: pd.Series) -> str:
                s = pd.to_numeric(s, errors="coerce")
                s = s.replace([np.inf, -np.inf], np.nan).dropna()
                if s.empty:
                    return ""
                return f"min/med/max={float(s.min()):.3f}/{float(s.median()):.3f}/{float(s.max()):.3f}"

            print(
                "[deploy_rulebook] ValueEV lane gate breakdown: "
                f"n={n_all} od_ok={n_od} edge_ok={n_edge} marg_ok={n_marg} keep={n_keep} | "
                f"metric={metric} od_min={float(od_min):.2f} edge_min={float(edge_min):.3f} margin_min={float(margin_min):.3f}"
            )
            st = _fmt_stats(e_anchor)
            if st:
                print(f"[deploy_rulebook] ValueEV lane edge stats (ANCHOR_CAND): {st}")

            # Show near-misses by edge (closest below edge_min) for quick tuning
            miss = (~edge_ok.fillna(False)) & od_ok.fillna(False) & marg_ok.fillna(False) & edge.notna()
            if bool(miss.any()):
                cols_dbg = [c for c in (
                    "league","fixture_key","home_team_name","away_team_name",
                    "bookie_pick","bookie_od",
                    "bookie_implied_used","bookie_implied_novig","model_p_for_bookie",
                    "ftr_valueev_edge"
                ) if c in cand.columns]
                samp = cand.loc[miss, cols_dbg].copy()
                samp["_edge"] = pd.to_numeric(samp.get("ftr_valueev_edge", np.nan), errors="coerce")
                samp["_edge_diff"] = float(edge_min) - samp["_edge"]
                samp = samp.sort_values(["_edge_diff"], ascending=[True]).head(12)
                print("[deploy_rulebook] ValueEV near-misses (edge below edge_min) sample:")
                print(samp.drop(columns=["_edge_diff"], errors="ignore").to_string(index=False))
        except Exception:
            pass
    cand = cand.loc[keep.fillna(False)].copy()
    if cand.empty:
        return cand

    # Rank: edge desc, margin desc, then lower odds (less extreme)
    cand["_edge"] = pd.to_numeric(cand["ftr_valueev_edge"], errors="coerce").fillna(-1e9)
    cand["_marg"] = pd.to_numeric(cand.get("ftr_margin", np.nan), errors="coerce").fillna(0.0)
    cand["_od"] = pd.to_numeric(cand.get("bookie_od", np.nan), errors="coerce").fillna(99.0)

    cand = cand.sort_values(
        ["league", "_edge", "_marg", "_od"],
        ascending=[True, False, False, True],
    )

    # Optional diversification guard (0 disables)
    if topk and topk > 0:
        cand = cand.groupby("league", as_index=False, group_keys=False).head(topk)

    # Mark lane/product
    cand["ftr_lane"] = "VALUEEV"
    cand["ftr_profile"] = prof

    cand = cand.drop(columns=["_edge", "_marg", "_od"], errors="ignore")
    return cand

def _fill_ftr_bookie_od_from_1x2(df: pd.DataFrame) -> pd.DataFrame:
    """Backfill FTR bookie_od from 1X2 odds columns (od_home/od_draw/od_away).

    Rules:
      - market == 'ftr' and bookie_pick == 'HOME' -> bookie_od = od_home
      - market == 'ftr' and bookie_pick == 'DRAW' -> bookie_od = od_draw
      - market == 'ftr' and bookie_pick == 'AWAY' -> bookie_od = od_away

    Only fills where bookie_od is missing/non-finite.
    """
    if df is None or df.empty:
        return df

    out = df.copy()
    if "market" not in out.columns:
        return out

    mk = out["market"].astype("string").fillna("").str.strip().str.lower()
    is_ftr = mk.eq("ftr")
    if not bool(is_ftr.any()):
        return out

    if not {"od_home", "od_draw", "od_away"}.issubset(set(out.columns)):
        return out

    # Normalize pick
    if "bookie_pick" in out.columns:
        pick = out["bookie_pick"]
    else:
        pick = out.get("selection", pd.Series("", index=out.index))

    pick = (
        pick.astype("string")
        .fillna("")
        .str.strip()
        .str.upper()
        .replace({"1": "HOME", "X": "DRAW", "2": "AWAY", "H": "HOME", "D": "DRAW", "A": "AWAY"})
    )

    if "bookie_od" not in out.columns:
        out["bookie_od"] = np.nan
    bod = pd.to_numeric(out["bookie_od"], errors="coerce")

    need = is_ftr & (~np.isfinite(bod))
    if not bool(need.any()):
        return out

    od_home = pd.to_numeric(out["od_home"], errors="coerce")
    od_draw = pd.to_numeric(out["od_draw"], errors="coerce")
    od_away = pd.to_numeric(out["od_away"], errors="coerce")

    fill = pd.Series(np.nan, index=out.index)
    m_home = is_ftr & pick.eq("HOME")
    m_draw = is_ftr & pick.eq("DRAW")
    m_away = is_ftr & pick.eq("AWAY")

    fill.loc[m_home] = od_home.loc[m_home]
    fill.loc[m_draw] = od_draw.loc[m_draw]
    fill.loc[m_away] = od_away.loc[m_away]

    m = need & fill.notna()
    if bool(m.any()):
        bod2 = bod.copy()
        bod2.loc[m] = fill.loc[m]
        out["bookie_od"] = bod2

    return out

def _safe_num(df: pd.DataFrame, col: str, default=np.nan) -> pd.Series:
    return pd.to_numeric(df.get(col, pd.Series(default, index=df.index)), errors="coerce")


def _attach_ftr_combo_overlay_fields(df: pd.DataFrame) -> pd.DataFrame:
    if df is None or df.empty:
        return df

    out = df.copy()

    home_lambda = _safe_num(out, "lambda_home").clip(lower=0.0, upper=10.0)
    away_lambda = _safe_num(out, "lambda_away").clip(lower=0.0, upper=10.0)

    for col in ["p_hw_and_hge2", "p_aw_and_age2"]:
        if col not in out.columns:
            out[col] = np.nan

    # Full Poisson combo probabilities from lambdas, not top-3 scoreline mass.
    max_goals = 10

    home_pmf_cols = []
    away_pmf_cols = []
    for k in range(max_goals + 1):
        fact_k = float(math.factorial(k))
        home_k = np.exp(-home_lambda) * np.power(home_lambda, k) / fact_k
        away_k = np.exp(-away_lambda) * np.power(away_lambda, k) / fact_k
        home_pmf_cols.append(pd.Series(home_k, index=out.index, dtype="float64"))
        away_pmf_cols.append(pd.Series(away_k, index=out.index, dtype="float64"))

    home_probs = pd.concat(home_pmf_cols, axis=1)
    away_probs = pd.concat(away_pmf_cols, axis=1)

    p_hw_and_hge2 = pd.Series(0.0, index=out.index, dtype="float64")
    p_aw_and_age2 = pd.Series(0.0, index=out.index, dtype="float64")

    # HOME win and HOME scores 2+
    for h in range(2, max_goals + 1):
        for a in range(0, h):
            p_hw_and_hge2 = p_hw_and_hge2 + (home_probs.iloc[:, h] * away_probs.iloc[:, a])

    # AWAY win and AWAY scores 2+
    for a in range(2, max_goals + 1):
        for h in range(0, a):
            p_aw_and_age2 = p_aw_and_age2 + (home_probs.iloc[:, h] * away_probs.iloc[:, a])

    out["p_hw_and_hge2"] = p_hw_and_hge2.clip(lower=0.0, upper=1.0)
    out["p_aw_and_age2"] = p_aw_and_age2.clip(lower=0.0, upper=1.0)

    return out


def _classify_hw_hge2_live(df: pd.DataFrame) -> pd.DataFrame:
    if df is None or df.empty:
        return df

    out = df.copy()
    out = _attach_ftr_combo_overlay_fields(out)

    sel = out.get("selection", out.get("bookie_pick", pd.Series("", index=out.index))).astype("string").fillna("").str.upper().str.strip()
    league = out.get("league", pd.Series("", index=out.index)).astype("string").fillna("").str.strip()

    combo_lambda = pd.to_numeric(out.get("lambda_home", np.nan), errors="coerce")
    away_lambda = pd.to_numeric(out.get("lambda_away", np.nan), errors="coerce")
    combo_prob = pd.to_numeric(out.get("p_hw_and_hge2", np.nan), errors="coerce")

    home_ge2_head = pd.to_numeric(out.get("p_home_ge2", out.get("home_ge2_confidence", np.nan)), errors="coerce")
    ge2_gap = (combo_prob - home_ge2_head).abs()

    denylist_hw = {
        "England Championship",
        "England EFL League 1",
        "England FA Cup",
        "Japan J1",
    }

    is_home = sel.eq("HOME")
    allowed_league = ~league.isin(list(denylist_hw))

    hw_lambda_away_ok = away_lambda.lt(1.20)
    hw_premium_monster_flag = away_lambda.lt(0.80)

    moderate = (
        is_home
        & allowed_league
        & hw_lambda_away_ok
        & combo_lambda.ge(2.50)
        & combo_prob.ge(0.60)
        & ge2_gap.lt(0.30)
    )
    strong = (
        is_home
        & allowed_league
        & hw_lambda_away_ok
        & combo_lambda.ge(2.75)
        & combo_prob.ge(0.65)
        & ge2_gap.lt(0.25)
    )
    very_strong = (
        is_home
        & allowed_league
        & hw_lambda_away_ok
        & combo_lambda.ge(3.00)
        & combo_prob.ge(0.70)
        & ge2_gap.lt(0.20)
    )

    out["hw_hge2_live_tier"] = pd.Series("", index=out.index, dtype="string")
    out.loc[moderate, "hw_hge2_live_tier"] = "MODERATE_HW"
    out.loc[strong, "hw_hge2_live_tier"] = "STRONG_HW"
    out.loc[very_strong, "hw_hge2_live_tier"] = "VERY_STRONG_HW"

    out["hw_hge2_live_allowed"] = out["hw_hge2_live_tier"].astype("string").fillna("").ne("").astype(int)
    out["hw_hge2_lambda_away_ok"] = hw_lambda_away_ok.astype(int)
    out["hw_hge2_premium_monster_flag"] = hw_premium_monster_flag.astype(int)
    out["hw_hge2_combo_lambda"] = combo_lambda
    out["hw_hge2_combo_prob"] = combo_prob
    out["hw_hge2_ge2_gap"] = ge2_gap

    return out


def _classify_aw_age2_live(df: pd.DataFrame) -> pd.DataFrame:
    if df is None or df.empty:
        return df

    out = df.copy()
    out = _attach_ftr_combo_overlay_fields(out)

    sel = out.get("selection", out.get("bookie_pick", pd.Series("", index=out.index))).astype("string").fillna("").str.upper().str.strip()
    league = out.get("league", pd.Series("", index=out.index)).astype("string").fillna("").str.strip()

    combo_lambda = pd.to_numeric(out.get("lambda_away", np.nan), errors="coerce")
    combo_prob = pd.to_numeric(out.get("p_aw_and_age2", np.nan), errors="coerce")

    away_ge2_head = pd.to_numeric(out.get("p_away_ge2", out.get("away_ge2_confidence", np.nan)), errors="coerce")
    ge2_gap = (combo_prob - away_ge2_head).abs()

    denylist_aw = {
        "England Championship",
        "England EFL League 1",
        "England FA Cup",
        "Spain La Liga",
        "Belgium Pro",
    }
    high_bar_aw = {
        "Italy Serie A",
        "Netherlands Eredivisie",
    }

    is_away = sel.eq("AWAY")
    allowed_league = ~league.isin(list(denylist_aw))
    is_high_bar = league.isin(list(high_bar_aw))

    moderate = (
        is_away
        & allowed_league
        & (~is_high_bar)
        & combo_lambda.ge(2.50)
        & combo_prob.ge(0.60)
        & ge2_gap.lt(0.30)
    )
    strong = (
        is_away
        & allowed_league
        & (~is_high_bar)
        & combo_lambda.ge(2.75)
        & combo_prob.ge(0.65)
        & ge2_gap.lt(0.25)
    )
    very_strong = (
        is_away
        & allowed_league
        & combo_lambda.ge(3.00)
        & combo_prob.ge(0.70)
        & ge2_gap.lt(0.20)
    )

    out["aw_age2_live_tier"] = pd.Series("", index=out.index, dtype="string")
    out.loc[moderate, "aw_age2_live_tier"] = "MODERATE_AW"
    out.loc[strong, "aw_age2_live_tier"] = "STRONG_AW"
    out.loc[very_strong, "aw_age2_live_tier"] = "VERY_STRONG_AW"

    out["aw_age2_live_allowed"] = out["aw_age2_live_tier"].astype("string").fillna("").ne("").astype(int)
    out["aw_age2_combo_lambda"] = combo_lambda
    out["aw_age2_combo_prob"] = combo_prob
    out["aw_age2_ge2_gap"] = ge2_gap

    return out

# -----------------------------
# Rulebook application
# -----------------------------

def apply_rulebook_close(df: pd.DataFrame, *, params: Dict[str, Any]) -> pd.DataFrame:
    """Apply CLOSE preset rules.

    Deploy ONLY close-match FTR candidate rows (ANCHOR_CAND) without requiring agree_model_vs_bookie.

    Requirements:
      - close_match_flag == 1
      - pool_tier == 'ANCHOR_CAND'
      - candidate_rank <= 2

    Gates (minimal, tunable via params):
      - bookie_implied (raw) >= close_implied_min
      - model_p_for_bookie >= close_pmin
      - gap_used >= close_gap_min

    Selection:
      - keep best 1 per (league, fixture_key) by: candidate_rank asc, gap_used desc, model_p desc, bookie_od asc
      - cap final output by close_max_ftr (fallback to max_ftr/max_per_market)
    """

    if df is None or df.empty:
        return df

    out = df.copy()

    # Normalise key columns
    out["market"] = _market_norm(_col(out, "market"))
    out["league"] = _col(out, "league").astype("string").fillna("").str.strip()
    out["fixture_key"] = _col(out, "fixture_key").astype("string").fillna("").str.strip()
    out["pool_tier"] = _col(out, "pool_tier").astype("string").fillna("").str.strip().str.upper()

    # Activate only on close-match FTR rows
    cm = _to_num(_col(out, "close_match_flag")).fillna(0).astype(int).eq(1)
    ftr = out[out["market"].eq("ftr") & cm].copy()
    if ftr.empty:
        return ftr

    # Candidate rows only
    ftr = ftr[ftr["pool_tier"].eq("ANCHOR_CAND")].copy()
    if ftr.empty:
        return ftr

    # Top-2 only
    rk = _to_num(_col(ftr, "candidate_rank")).fillna(999).astype(int)
    ftr = ftr[rk <= 2].copy()
    if ftr.empty:
        return ftr

    # Numeric coercions used downstream
    for c in [
        "bookie_od",
        "bookie_implied",
        "bookie_implied_novig",
        "model_p_for_bookie",
        "gap",
        "gap_novig",
        "ftr_margin",
    ]:
        if c in ftr.columns:
            ftr[c] = _to_num(ftr[c])

    # implied_used (prefer no-vig)
    imp_raw = _to_num(_col(ftr, "bookie_implied"))
    imp_nv = _to_num(_col(ftr, "bookie_implied_novig"))
    ftr["bookie_implied_used"] = _first_nonnull_series(imp_nv, imp_raw)

    # gap_used (prefer no-vig)
    gap_nv = _to_num(_col(ftr, "gap_novig"))
    gap_raw = _to_num(_col(ftr, "gap"))
    if gap_raw.isna().all():
        gap_raw = _to_num(_col(ftr, "model_p_for_bookie")) - imp_raw
    ftr["gap_used"] = _to_num(_first_nonnull_series(gap_nv, gap_raw))

    # Deterministic score (for sorting): gap_used + small margin bump
    ftr["score"] = ftr["gap_used"].fillna(-1e9) + 0.25 * _to_num(_col(ftr, "ftr_margin")).fillna(0.0)

    # CLOSE gates
    close_implied_min = float(params.get("close_implied_min", 0.18))
    close_pmin = float(params.get("close_pmin", 0.27))
    close_gap_min = float(params.get("close_gap_min", 0.02))

    imp_gate = _to_num(_col(ftr, "bookie_implied")).fillna(_to_num(_col(ftr, "bookie_implied_used")).fillna(-1.0))
    pm = _to_num(_col(ftr, "model_p_for_bookie")).fillna(-1.0)
    gu = _to_num(_col(ftr, "gap_used")).fillna(-1e9)

    ftr = ftr[(imp_gate >= close_implied_min) & (pm >= close_pmin) & (gu >= close_gap_min)].copy()
    if ftr.empty:
        return ftr

    # Choose best 1 per fixture
    ftr["candidate_rank"] = _to_num(_col(ftr, "candidate_rank")).fillna(999).astype(int)
    ftr = ftr.sort_values(
        ["league", "fixture_key", "candidate_rank", "gap_used", "model_p_for_bookie", "bookie_od"],
        ascending=[True, True, True, False, False, True],
    )
    ftr = ftr.groupby(["league", "fixture_key"], as_index=False, group_keys=False).head(1).copy()

    # Cap total output
    close_max_ftr = params.get("close_max_ftr", None)
    if close_max_ftr is None:
        close_max_ftr = params.get("max_ftr", None)
    if close_max_ftr is None:
        close_max_ftr = params.get("max_per_market", 25)

    try:
        close_max_ftr_i = int(close_max_ftr)
    except Exception:
        close_max_ftr_i = 25

    ftr = ftr.sort_values(["score", "bookie_implied_used"], ascending=[False, False]) \
         .head(max(0, close_max_ftr_i)).reset_index(drop=True)

    # Stamp product identity fields (used by downstream routing/reporting)
    try:
        ftr_prof = _normalize_ftr_profile(params.get("ftr_profile", "accuracy") or "accuracy")
        ftr = _stamp_ftr_product_fields(ftr, ftr_profile=ftr_prof)
    except Exception:
        pass

    return ftr

def _compute_ftr_valueev_edge(df: pd.DataFrame, *, metric: str = "gap_novig") -> pd.Series:
    """
    Compute a ValueEV edge signal for FTR candidates.
    Uses no-vig implied when available (bookie_implied_novig or bookie_implied_used).
    """
    if df is None or df.empty:
        return pd.Series(np.nan, index=getattr(df, "index", None))

    pm = _to_num(_col(df, "model_p_for_bookie"))
    imp_nv = _to_num(_col(df, "bookie_implied_novig"))
    imp_used = _to_num(_col(df, "bookie_implied_used"))
    imp = imp_nv.where(imp_nv.notna(), imp_used)

    if metric == "ratio_novig":
        # ratio edge: p / imp - 1
        edge = (pm / imp) - 1.0
    else:
        # gap edge: p - imp
        edge = pm - imp

    edge = edge.replace([np.inf, -np.inf], np.nan)
    return edge



def apply_rulebook_v1(df: pd.DataFrame, *, params: Dict[str, Any]) -> pd.DataFrame:
    """Apply V1 market-specific rules to an ALLMARKETS dataframe."""

    if df is None or df.empty:
        return df

    out = df.copy()

    # Normalise key columns
    out["market"] = _market_norm(_col(out, "market"))

    # Some exports (e.g. __FTR_CONSENSUS) may omit agree_model_vs_bookie.
    # If missing, default to agree=1 so the rulebook can operate; safety is handled
    # upstream by deterministic deploy gates.
    if "agree_model_vs_bookie" in out.columns:
        out["agree_model_vs_bookie"] = _to_num(_col(out, "agree_model_vs_bookie")).fillna(0).astype(int)
    else:
        out["agree_model_vs_bookie"] = 1

    # Normalise bookie_pick across exports (some consensus files use 1/X/2 or H/D/A).
    if "bookie_pick" in out.columns:
        _bp = out["bookie_pick"]
    elif "selection" in out.columns:
        _bp = out["selection"]
    else:
        _bp = pd.Series("", index=out.index, dtype="string")

    out["bookie_pick"] = _bp.astype("string").fillna("")
    out["bookie_pick"] = out["bookie_pick"].str.upper().str.strip()
    out["bookie_pick"] = out["bookie_pick"].replace({
        "1": "HOME",
        "X": "DRAW",
        "2": "AWAY",
        "H": "HOME",
        "D": "DRAW",
        "A": "AWAY",
    })

    # Numeric coercions
    for c in [
        "bookie_od",
        "bookie_implied",
        "bookie_implied_novig",
        "bookie_overround",
        "bookie_spread",
        "model_p_for_bookie",
        "gap",
        "gap_novig",
        "ftr_margin",
        "ftr_ppg_glue_ok",
        "ftr_drawtrap_flag",
        "power_diff",
        "home_power_rating",
        "away_power_rating",
        "model_strength",
        "score",
        "average_goals_per_match_pre_match",
        "xg_sum_pre_match",
        "over_25_percentage_pre_match",
        "bookie_lambda_total_fit",
        # Specialist heads (Team Goals / FTS)
        "p_home_fts",
        "p_away_fts",
        "home_ge2_confidence",
        "away_ge2_confidence",
        "home_ge3_confidence",
        "away_ge3_confidence",
        # WTN related
        "confidence_home",
        "confidence_away",
        "home_wtn_score",
        "away_wtn_score",
        # Pre-match PPG + rolling xG (used for TG gates)
        "ppg_home_pre",
        "ppg_away_pre",
        "ppg_diff_pre",
        "xg_for_avg_5_home",
        "xg_for_avg_5_away",
        "xg_against_avg_5_home",
        "xg_against_avg_5_away",
    ]:
        if c in out.columns:
            out[c] = _to_num(out[c])

    # Derive power_diff when missing/empty (safe): power_diff = home_power_rating - away_power_rating.
    # Only fills rows where power_diff is NaN AND both ratings are finite.
    if ("power_diff" in out.columns) and ("home_power_rating" in out.columns) and ("away_power_rating" in out.columns):
        pdiff = pd.to_numeric(out["power_diff"], errors="coerce")
        hpr = pd.to_numeric(out["home_power_rating"], errors="coerce")
        apr = pd.to_numeric(out["away_power_rating"], errors="coerce")
        derived = hpr - apr
        fill_mask = pdiff.isna() & derived.notna()
        if bool(fill_mask.any()):
            out.loc[fill_mask, "power_diff"] = derived.loc[fill_mask]
    elif ("power_diff" not in out.columns) and ("home_power_rating" in out.columns) and ("away_power_rating" in out.columns):
        hpr = pd.to_numeric(out["home_power_rating"], errors="coerce")
        apr = pd.to_numeric(out["away_power_rating"], errors="coerce")
        out["power_diff"] = hpr - apr

    # If model_p_for_bookie is missing/empty on FTR rows, derive it from the 3-way confidences.
    # This is common in some consensus exports.
    if ("model_p_for_bookie" not in out.columns) or (pd.to_numeric(out.get("model_p_for_bookie"), errors="coerce").isna().all()):
        if {"confidence_home", "confidence_draw", "confidence_away"}.issubset(out.columns):
            pick = out.get("bookie_pick", pd.Series("", index=out.index)).astype("string").fillna("").str.upper().str.strip()
            ch = pd.to_numeric(out["confidence_home"], errors="coerce")
            cd = pd.to_numeric(out["confidence_draw"], errors="coerce")
            ca = pd.to_numeric(out["confidence_away"], errors="coerce")
            mp = pd.Series(np.nan, index=out.index)
            mp = mp.mask(pick.eq("HOME"), ch)
            mp = mp.mask(pick.eq("DRAW"), cd)
            mp = mp.mask(pick.eq("AWAY"), ca)
            out["model_p_for_bookie"] = mp

    # Compute implied_used (prefer no-vig)
    imp_raw = _to_num(_col(out, "bookie_implied"))
    imp_nv = _to_num(_col(out, "bookie_implied_novig"))
    out["bookie_implied_used"] = _first_nonnull_series(imp_nv, imp_raw)

    # Compute gap_used (prefer no-vig per-row)
    gap_nv = _to_num(_col(out, "gap_novig"))

    # Prefer provided raw gap if present; otherwise compute from raw implied.
    # IMPORTANT: fill per-row NaNs from fallback (consensus exports often have a gap column that is empty).
    gap_raw = _to_num(_col(out, "gap"))
    gap_fallback = _to_num(_col(out, "model_p_for_bookie")) - imp_raw
    if gap_raw.isna().all():
        gap_raw = gap_fallback
    else:
        gap_raw = gap_raw.fillna(gap_fallback)

    out["gap_used"] = _to_num(_first_nonnull_series(gap_nv, gap_raw))

    # Ensure score exists (deterministic)
    if "score" not in out.columns or not out["score"].notna().any():
        out["score"] = out["gap_used"]
        is_ftr = out["market"].eq("ftr")
        if "ftr_margin" in out.columns:
            out.loc[is_ftr, "score"] = out.loc[is_ftr, "gap_used"].fillna(0.0) + out.loc[is_ftr, "ftr_margin"].fillna(0.0)

    # --- Derived WTN scores (Win-To-Nil) ---
    # HOME_WTN ~ P(HOME win) * P(away FTS)
    # AWAY_WTN ~ P(AWAY win) * P(home FTS)
    if ("confidence_home" in out.columns) and ("confidence_away" in out.columns) and ("p_home_fts" in out.columns) and ("p_away_fts" in out.columns):
        ch = pd.to_numeric(out["confidence_home"], errors="coerce")
        ca = pd.to_numeric(out["confidence_away"], errors="coerce")
        ph_fts = pd.to_numeric(out["p_home_fts"], errors="coerce")
        pa_fts = pd.to_numeric(out["p_away_fts"], errors="coerce")
        out["home_wtn_score"] = (ch * pa_fts).clip(lower=0.0, upper=1.0)
        out["away_wtn_score"] = (ca * ph_fts).clip(lower=0.0, upper=1.0)
    else:
        if "home_wtn_score" not in out.columns:
            out["home_wtn_score"] = np.nan
        if "away_wtn_score" not in out.columns:
            out["away_wtn_score"] = np.nan

    # Common knobs
    max_per_market = int(params.get("max_per_market", 25))
    max_ftr = params.get("max_ftr", None)
    max_ou25 = params.get("max_ou25", None)
    max_btts = params.get("max_btts", None)
    max_tg15 = params.get("max_tg15", None)
    max_tg25 = params.get("max_tg25", None)

    try: max_ftr_i = int(max_ftr) if max_ftr is not None else int(max_per_market)
    except Exception: max_ftr_i = int(max_per_market)
    try: max_ou25_i = int(max_ou25) if max_ou25 is not None else int(max_per_market)
    except Exception: max_ou25_i = int(max_per_market)
    try: max_btts_i = int(max_btts) if max_btts is not None else int(max_per_market)
    except Exception: max_btts_i = int(max_per_market)
    max_wtn = params.get("max_wtn", None)
    try: max_wtn_i = int(max_wtn) if max_wtn is not None else int(max_per_market)
    except Exception: max_wtn_i = int(max_per_market)
    try: max_tg15_i = int(max_tg15) if max_tg15 is not None else int(max_per_market)
    except Exception: max_tg15_i = int(max_per_market)
    try: max_tg25_i = int(max_tg25) if max_tg25 is not None else int(max_per_market)
    except Exception: max_tg25_i = int(max_per_market)

    cap_map = {
        "ftr": max_ftr_i,
        "ou25": max_ou25_i,
        "btts": max_btts_i,
        "wtn": max_wtn_i,
        "tg15": max_tg15_i,
        "tg25": max_tg25_i,
    }
    tol_side = float(params.get("tol_side", 0.05))
    # Allow separate tolerances per market (fallback to tol_side for backward compatibility)
    tol_ou = params.get("tol_ou", None)
    tol_btts = params.get("tol_btts", None)
    try:
        tol_ou_f = float(tol_ou) if tol_ou is not None else float(tol_side)
    except Exception:
        tol_ou_f = float(tol_side)
    try:
        tol_btts_f = float(tol_btts) if tol_btts is not None else float(tol_side)
    except Exception:
        tol_btts_f = float(tol_side)
    debug = bool(params.get("debug", False))
    # Gate-mode awareness (preset vs learned/hybrid)
    gate_mode = str(params.get("gate_mode", "preset") or "preset").strip().lower()

    # --- FTR rules ---
    ftr_implied_min = float(
        params.get(
            "ftr_accuracy_implied_min",
            params.get("ftr_implied_min", 0.20),
        )
    )
    ftr_margin_min = float(params.get("ftr_margin_min", 0.05))
    ftr_od_min = params.get("ftr_od_min", None)
    ftr_pd_home_min = float(params.get("ftr_pd_home_min", 5.0))
    ftr_pd_away_min = float(params.get("ftr_pd_away_min", -5.0))
    ftr_draw_pd_max = float(params.get("ftr_draw_pd_max", 10.0))
    use_draw_rule = bool(params.get("use_draw_rule", True))
    ftr_gap_min = float(params.get("ftr_gap_min", -0.10))
    # In learned/hybrid modes, learned gates already filtered by per-league stability.
    # If the caller did not override ftr_gap_min (still at the default -0.10),
    # relax it to avoid wiping all FTR rows.
    if gate_mode in ("hybrid", "learned"):
        try:
            if abs(float(ftr_gap_min) - (-0.10)) < 1e-9:
                ftr_gap_min = -1.0
        except Exception:
            pass
    ftr_xgfor_min = float(params.get("ftr_xgfor_min", 1.10))
    ftr_xgagainst_min = float(params.get("ftr_xgagainst_min", 1.00))
    ftr_home_xga_max = float(params.get("ftr_home_xga_max", 1.15))
    ftr_h2h_min_n = int(params.get("ftr_h2h_min_n", 3))
    ftr_h2h_draw_veto_min = params.get("ftr_h2h_draw_veto_min", None)
    ftr_ppg_diff_home_min = float(params.get("ftr_ppg_diff_home_min", 0.45))
    ftr_ppg_diff_away_min = float(params.get("ftr_ppg_diff_away_min", 0.25))
    ftr_ppg_diff_draw_max = params.get("ftr_ppg_diff_draw_max", None)

    # --- OU25 rules ---
    # Default OU25 implied bands should cover typical totals prices (~1.55–2.05 => implied ~0.49–0.65).
    # Keep defaults broad; later gates (pmin, tol, structure) do the real filtering.
    ou_implied_lo = float(params.get("ou_implied_lo", 0.50))
    ou_implied_hi = float(params.get("ou_implied_hi", 0.70))

    # Optional per-side implied bands (fallback to shared OU band when not provided)
    _ou_over_lo = params.get("ou_over_implied_lo", None)
    _ou_over_hi = params.get("ou_over_implied_hi", None)
    _ou_under_lo = params.get("ou_under_implied_lo", None)
    _ou_under_hi = params.get("ou_under_implied_hi", None)

    try:
        ou_over_implied_lo = float(_ou_over_lo) if _ou_over_lo is not None else float(ou_implied_lo)
    except Exception:
        ou_over_implied_lo = float(ou_implied_lo)
    try:
        ou_over_implied_hi = float(_ou_over_hi) if _ou_over_hi is not None else float(ou_implied_hi)
    except Exception:
        ou_over_implied_hi = float(ou_implied_hi)

    try:
        ou_under_implied_lo = float(_ou_under_lo) if _ou_under_lo is not None else float(ou_implied_lo)
    except Exception:
        ou_under_implied_lo = float(ou_implied_lo)
    try:
        ou_under_implied_hi = float(_ou_under_hi) if _ou_under_hi is not None else float(ou_implied_hi)
    except Exception:
        ou_under_implied_hi = float(ou_implied_hi)
    ou_abs_pd_min = float(params.get("ou_abs_pd_min", 0.0))
    ou_pmin_floor = float(params.get("ou_pmin_floor", 0.57))
    ou_lambda_override_min = float(params.get("ou_lambda_override_min", 3.0))
    ou_override_pmin = float(params.get("ou_override_pmin", 0.50))
    # Separate knobs for UNDER25 (different calibration regime)
    ou_under_pmin_floor = float(params.get("ou_under_pmin_floor", 0.52))
    tol_ou_under = params.get("tol_ou_under", None)
    try:
        tol_ou_under_f = float(tol_ou_under) if tol_ou_under is not None else float(tol_ou_f)
    except Exception:
        tol_ou_under_f = float(tol_ou_f)

    # OU25 structural rate confirmations (used only if columns exist)
    ou_over_rate_min = float(params.get("ou_over_rate_min", 0.60))
    ou_over_goaliness_min = float(params.get("ou_over_goaliness_min", 2.70))
    ou_under_rate_min = float(params.get("ou_under_rate_min", 0.60))
    ou_under_goaliness_max = float(params.get("ou_under_goaliness_max", 2.30))
    # OU25 rolling xG confirmation knobs
    ou_over_xgsum_min = float(params.get("ou_over_xgsum_min", 2.70))
    ou_under_xgsum_max = float(params.get("ou_under_xgsum_max", 2.10))

    # Specialist heads (Team Goals / FTS) structural knobs
    fts_yes_max = float(params.get("fts_yes_max", 0.35))
    fts_no_min = float(params.get("fts_no_min", 0.35))
    ou_over_ge_min = float(params.get("ou_over_ge_min", 0.55))
    ou_under_fts_min = float(params.get("ou_under_fts_min", 0.35))

    # Optional H2H gates
    h2h_min_n = int(params.get("h2h_min_n", 3))
    ou_over_h2h_min = params.get("ou_over_h2h_min", None)
    ou_under_h2h_max = params.get("ou_under_h2h_max", None)
    
    # --- BTTS rules ---
    btts_implied_max = float(params.get("btts_implied_max", 0.72))

    # Prepare market frames
    agree = out["agree_model_vs_bookie"].eq(1)

    # Backfill FTR bookie_od from 1X2 columns if missing (needed for ValueEV lane filters)
    try:
        out = _fill_ftr_bookie_od_from_1x2(out)
    except Exception:
        pass

    # FTR filter
    ftr = out[out["market"].eq("ftr")].copy()
    if not ftr.empty:
        # FTR lane/profile routing (always define, even when debug=False)
        ftr_profile = _normalize_ftr_profile(params.get("ftr_profile", "accuracy") or "accuracy")
        is_valueev_lane = bool(str(ftr_profile).startswith("valueev"))
        _skip_ftr_post_lane_gates = bool(is_valueev_lane)

        # ------------------------------------------------------------------
        # ValueEV support: stamp ANCHOR_CAND pool for FTR using edge/gap + stability
        # (ValueEV selectors prefer pool_tier == ANCHOR_CAND; when ALLMARKETS doesn't
        # emit anchor candidates, generate a conservative anchor pool here.)
        # ------------------------------------------------------------------
        if is_valueev_lane:
            if "pool_tier" not in out.columns:
                out["pool_tier"] = ""
            out["pool_tier"] = out["pool_tier"].astype("string").fillna("").str.strip().str.upper()

            mk_all = out.get("market", pd.Series("", index=out.index)).astype("string").fillna("").str.lower().str.strip()
            is_ftr_all = mk_all.eq("ftr")

            det_pass = pd.to_numeric(
                out.get("deterministic_pass", pd.Series(1, index=out.index)),
                errors="coerce",
            ).fillna(1).astype(int)
            chaos = pd.to_numeric(
                out.get("chaos_risk_flag", pd.Series(0, index=out.index)),
                errors="coerce",
            ).fillna(0).astype(int)

            not_glue = pd.to_numeric(
                out.get("not_glue_flag", pd.Series(0, index=out.index)),
                errors="coerce",
            ).fillna(0).astype(int)

            edge = pd.to_numeric(out.get("edge", np.nan), errors="coerce")

            # Prefer explicit gap layers if present, but FTR rows often don't have `edge`/`gap_novig`.
            # Build a robust fallback value signal for anchors:
            #   val = edge (if present) else gap_novig else gap_used else (model_p_for_bookie - implied_used)
            gap_nv = _to_num(_col(out, "gap_novig"))
            gap_used = _to_num(_col(out, "gap_used"))

            # Compute implied used (prefer already-stamped bookie_implied_used, else novig, else raw)
            imp_used = _to_num(_col(out, "bookie_implied_used"))
            imp_nv = _to_num(_col(out, "bookie_implied_novig"))
            imp_raw = _to_num(_col(out, "bookie_implied"))
            imp_used = imp_used.where(imp_used.notna(), imp_nv)
            imp_used = imp_used.where(imp_used.notna(), imp_raw)

            p_model = _to_num(_col(out, "model_p_for_bookie"))
            gap_calc = (p_model - imp_used)

            # Final anchor value score
            # Precedence:
            #   val = edge (if present)
            #     else gap_calc (if present)
            #     else gap_used (if present)
            #     else gap_novig (last resort)
            val = edge
            val = val.where(val.notna(), gap_calc)
            val = val.where(val.notna(), gap_used)
            val = val.where(val.notna(), gap_nv)

            # Use same implied series for not-too-short gate
            imp = imp_used

            # Conservative anchor rules (tune via params later)
            val_min = float(params.get("ftr_valueev_anchor_val_min", 0.04))
            imp_max = float(params.get("ftr_valueev_anchor_imp_max", 0.72))
            chaos_max = int(params.get("ftr_valueev_anchor_chaos_max", 1))
            notglue_max = int(params.get("ftr_valueev_anchor_notglue_max", 1))

            val_ok = val.notna() & (val >= val_min)
            stable_ok = (det_pass >= 1) & (chaos <= chaos_max) & (not_glue <= notglue_max)
            not_too_short = imp.notna() & (imp <= imp_max)

            anchor_mask = is_ftr_all & val_ok & stable_ok & not_too_short

            if debug:
                try:
                    n_ftr_all = int(is_ftr_all.sum())
                    n_val = int((is_ftr_all & val_ok).sum())
                    n_stable = int((is_ftr_all & stable_ok).sum())
                    n_short_ok = int((is_ftr_all & not_too_short).sum())
                    n_anchor = int(anchor_mask.sum())

                    # Coverage diagnostics for the *chosen* value signal source
                    # Precedence used above:
                    #   val = edge (if present)
                    #     else gap_used (if present)
                    #     else gap_calc (if present)
                    #     else gap_nv (last resort)
                    #
                    # NOTE: be defensive — ensure these are Series aligned to out.index
                    def _as_series(x):
                        """Always return a Series aligned to out.index (prevents index-alignment bugs)."""
                        if isinstance(x, pd.Series):
                            return x.reindex(out.index)
                        return pd.Series(x, index=out.index)

                    _edge = _as_series(edge)
                    _gap_used = _as_series(gap_used)
                    _gap_calc = _as_series(gap_calc)
                    _gap_nv = _as_series(gap_nv)

                    # IMPORTANT: compute chosen-source masks ONLY on FTR rows.
                    # This prevents non-FTR rows (which can have gap_used populated) from dominating the counters.
                    ftr_mask = is_ftr_all.reindex(out.index).fillna(False).astype(bool)

                    choose_edge = ftr_mask & _edge.notna()
                    choose_gap_calc = ftr_mask & _edge.isna() & _gap_calc.notna()
                    choose_gap_used = ftr_mask & _edge.isna() & _gap_calc.isna() & _gap_used.notna()
                    choose_gap_nv = ftr_mask & _edge.isna() & _gap_calc.isna() & _gap_used.isna() & _gap_nv.notna()

                    # Force alignment + boolean dtype (avoid NaN from index alignment)
                    choose_edge = choose_edge.reindex(out.index).fillna(False).astype(bool)
                    choose_gap_calc = choose_gap_calc.reindex(out.index).fillna(False).astype(bool)
                    choose_gap_used = choose_gap_used.reindex(out.index).fillna(False).astype(bool)
                    choose_gap_nv = choose_gap_nv.reindex(out.index).fillna(False).astype(bool)

                    # Restrict source-choice counting to the rows we actually care about.
                    # Use ANCHOR_CAND mask (preferred); switch to (is_ftr_all & val_ok) if you want val_ok distribution.
                    count_mask = anchor_mask.reindex(out.index).fillna(False).astype(bool)
                    # count_mask = (is_ftr_all & val_ok).reindex(out.index).fillna(False).astype(bool)

                    choose_edge = choose_edge & count_mask
                    choose_gap_calc = choose_gap_calc & count_mask
                    choose_gap_used = choose_gap_used & count_mask
                    choose_gap_nv = choose_gap_nv & count_mask

                    # Now counts are directly for the chosen-source distribution among anchors (or val_ok if you switch mask)
                    v_src_edge = int(choose_edge.sum())
                    v_src_gap_calc = int(choose_gap_calc.sum())
                    v_src_gap_used = int(choose_gap_used.sum())
                    v_src_gap_nv = int(choose_gap_nv.sum())

                    print(
                        "[deploy_rulebook] ValueEV anchor filters(FTR): "
                        f"ftr={n_ftr_all} val_ok={n_val} stable_ok={n_stable} not_too_short={n_short_ok} anchors={n_anchor} | "
                        f"val_src(edge/gap_calc/gap_used/gap_nv)={v_src_edge}/{v_src_gap_calc}/{v_src_gap_used}/{v_src_gap_nv} | "
                        f"thr(val_min={val_min:.3f} imp_max={imp_max:.3f} chaos_max={chaos_max} notglue_max={notglue_max})"
                    )
                except Exception:
                    pass

            blank_tier = out["pool_tier"].eq("") | out["pool_tier"].eq("GLUE")
            out.loc[anchor_mask & blank_tier, "pool_tier"] = "ANCHOR_CAND"

            if debug:
                try:
                    pt_counts = out.loc[is_ftr_all, "pool_tier"].value_counts(dropna=False).to_dict()
                    print(f"[deploy_rulebook] ValueEV pool_tier_counts(FTR): {pt_counts}")
                except Exception:
                    pass

            # Re-sync ftr slice after stamping pool_tier
            ftr = out[out["market"].eq("ftr")].copy()

        if debug:
            print(f"[deploy_rulebook] FTR start n={len(ftr)}")
            try:
                print(f"[deploy_rulebook] FTR profile={ftr_profile} skip_post_lane_gates={int(_skip_ftr_post_lane_gates)}")
            except Exception:
                pass
        # Do NOT hard-gate FTR by agree_model_vs_bookie.
        # FTR is model-led now; downstream gates do the real filtering.
        if debug:
            try:
                _agree_ftr = pd.to_numeric(
                    ftr.get("agree_model_vs_bookie", pd.Series(1, index=ftr.index)),
                    errors="coerce",
                ).fillna(1).astype(int)
                print(
                    f"[deploy_rulebook] FTR agree gate bypassed n={len(ftr)} "
                    f"agree={int((_agree_ftr == 1).sum())} disagree={int((_agree_ftr != 1).sum())}"
                )
            except Exception:
                print(f"[deploy_rulebook] FTR agree gate bypassed n={len(ftr)}")
        # ---------------------------------------------------------
        # Lane selection (ValueEV)
        # ---------------------------------------------------------
        if is_valueev_lane:
            try:
                ftr = _select_ftr_valueev_lane(ftr, params=params)
            except Exception as e:
                if debug:
                    print(f"[deploy_rulebook] FTR valueev lane selection failed: {e}")
                ftr = ftr.iloc[0:0].copy()

            if debug:
                print(f"[deploy_rulebook] FTR lane=valueev profile={ftr_profile} n={len(ftr)}")
        else:
            if debug:
                print(f"[deploy_rulebook] FTR lane=accuracy profile={ftr_profile} n={len(ftr)}")

        # Stamp product identity fields for FTR rows (downstream bucket routing/reporting)
        ftr = _stamp_ftr_product_fields(ftr, ftr_profile=ftr_profile)

        # If we're running a ValueEV lane, lane selection already did the job.
        # Do NOT apply the downstream accuracy gates (implied/margin/xG/PPG/draw-chaos/od_min/power_diff etc.).
        if _skip_ftr_post_lane_gates:
            if debug:
                print("[deploy_rulebook] FTR post-lane gates skipped (ValueEV lane)")

            try:
                od = pd.to_numeric(ftr.get("bookie_od", np.nan), errors="coerce")
                od_min = float(params.get("ftr_valueev_od_min", 1.80))
                ftr = ftr.loc[od.notna() & (od >= od_min)].copy()
            except Exception:
                pass
        else:
            # For the *implied_min* gate we want the **raw market price** (vigged implied).
            # HOWEVER, some exports (notably __FTR_CONSENSUS) may have bookie_implied present but empty/NaN.
            # In that case, fall back to bookie_implied_used so we don't wipe the set.
            # NOTE: implied-min is an ACCURACY-lane favourite filter; ValueEV lanes skip it.
            if ftr_profile == "accuracy":
                imp_raw_gate = _to_num(_col(ftr, "bookie_implied"))
                imp_used_gate = _to_num(_col(ftr, "bookie_implied_used"))
                imp_gate = _first_nonnull_series(imp_raw_gate, imp_used_gate).fillna(-1.0)

                if debug:
                    try:
                        print(
                            f"[deploy_rulebook] FTR implied_min gate thr={float(ftr_implied_min):.3f} | "
                            f"raw_finite={int(imp_raw_gate.notna().sum())}/{len(ftr)} | "
                            f"used_finite={int(imp_used_gate.notna().sum())}/{len(ftr)}"
                        )
                        if imp_gate.notna().any():
                            ig = pd.to_numeric(imp_gate, errors="coerce")
                            if ig.notna().any():
                                print(
                                    f"[deploy_rulebook] FTR imp_gate stats min/med/max: "
                                    f"{float(ig.min()):.3f}/{float(ig.median()):.3f}/{float(ig.max()):.3f}"
                                )
                        # show a small sample to diagnose empty implieds
                        cols_dbg = [
                            c
                            for c in (
                                "league",
                                "home_team_name",
                                "away_team_name",
                                "bookie_pick",
                                "bookie_od",
                                "bookie_implied",
                                "bookie_implied_used",
                                "od_home",
                                "od_draw",
                                "od_away",
                            )
                            if c in ftr.columns
                        ]
                        if cols_dbg:
                            print("[deploy_rulebook] FTR sample (pre implied_min):")
                            print(ftr[cols_dbg].head(5).to_string(index=False))
                    except Exception as e:
                        print(f"[deploy_rulebook] FTR implied_min debug failed: {e}")

                ftr = ftr[imp_gate >= ftr_implied_min].copy()
                if debug:
                    print(f"[deploy_rulebook] FTR after implied_min n={len(ftr)}")
            else:
                if debug:
                    print("[deploy_rulebook] FTR implied_min gate skipped (ValueEV lane)")
            # Gap handling (value-vs-bookie).
            # Post-rebuild calibration can lag, so don't use gap as a strict veto.
            # Hard veto ONLY for extreme negative gaps.
            gap_used = pd.to_numeric(ftr.get("gap_used", ftr.get("gap", np.nan)), errors="coerce")
            imp_used = pd.to_numeric(ftr.get("bookie_implied_used", ftr.get("bookie_implied", np.nan)), errors="coerce")

            ftr_gap_hard_min = float(params.get("ftr_gap_hard_min", -0.80))
            ftr_gap_min = float(params.get("ftr_gap_min", -0.10))
            ftr_gap_min_short = float(params.get("ftr_gap_min_short", -0.55))
            ftr_gap_min_anchor = float(params.get("ftr_gap_min_anchor", -0.65))

            is_short = imp_used.notna() & (imp_used >= 0.65)
            floor = pd.Series(ftr_gap_min, index=ftr.index, dtype=float)
            floor = floor.mask(is_short, float(ftr_gap_min_short))

            if "pool_tier" in ftr.columns:
                pt = ftr["pool_tier"].astype("string").fillna("").str.strip().str.upper()
                is_anchor = pt.eq("ANCHOR_CAND")
                floor = floor.mask(is_anchor, np.minimum(floor, float(ftr_gap_min_anchor)))

            before_n = len(ftr)

            # HARD veto only (extreme negative gaps)
            ftr = ftr[gap_used.notna() & (gap_used >= float(ftr_gap_hard_min))].copy()

            if debug:
                try:
                    print(
                        f"[deploy_rulebook] FTR after gap_min "
                        f"(HARD>={ftr_gap_hard_min:+.2f}; short>=0.65:{ftr_gap_min_short:+.2f} "
                        f"else:{ftr_gap_min:+.2f}; ANCHOR_CAND:{ftr_gap_min_anchor:+.2f}) "
                        f"n={len(ftr)} (dropped={before_n - len(ftr)})"
                    )
                except Exception:
                    print(f"[deploy_rulebook] FTR after gap_min n={len(ftr)}")

            # Consensus-only gap floor (protects against “market says no edge” legs slipping through)
            cons_gap_min = params.get("ftr_cons_gap_min", None)
            if cons_gap_min is not None:
                try:
                    cons_gap_min_f = float(cons_gap_min)
                except Exception:
                    cons_gap_min_f = None

                if cons_gap_min_f is not None:
                    is_cons = ftr.get("od_source", pd.Series("", index=ftr.index)).astype("string").fillna("").str.lower().eq("consensus")
                    if bool(is_cons.any()):
                        gu = _to_num(ftr.get("gap_used", np.nan)).fillna(-1e9)
                        before_n = int(len(ftr))
                        keep_mask = (~is_cons) | (gu >= cons_gap_min_f)

                        if debug:
                            try:
                                drop_mask = is_cons & (~(gu >= cons_gap_min_f))
                                cols_dbg = [c for c in (
                                    "league","fixture_key","home_team_name","away_team_name",
                                    "bookie_pick","gap_used","bookie_od","bookie_implied_used",
                                    "consensus_tier","consensus_lane","consensus_margin",
                                    "implied_prob_diff","bookie_spread","odds_diff",
                                    "reason_codes"
                                ) if c in ftr.columns]
                                if cols_dbg and bool(drop_mask.any()):
                                    print(f"[deploy_rulebook] FTR CONS gap floor drops (gap<{cons_gap_min_f:.3f}) sample:")
                                    print(ftr.loc[drop_mask, cols_dbg].sort_values("gap_used").head(12).to_string(index=False))
                            except Exception as e:
                                print(f"[deploy_rulebook] FTR CONS gap floor drop-sample failed: {e}")

                        ftr = ftr.loc[keep_mask].copy()
                        if debug:
                            print(f"[deploy_rulebook] FTR after CONS gap_min>={cons_gap_min_f:.3f} n={len(ftr)} (dropped={before_n - len(ftr)})")
            # stability
            if "ftr_margin" in ftr.columns:
                ftr = ftr[_to_num(ftr["ftr_margin"]).fillna(-1.0) >= ftr_margin_min].copy()
            if debug:
                print(f"[deploy_rulebook] FTR after margin_min n={len(ftr)}")

            # ---------------------------------------------------------
            # Rolling xG directional confirmation (only when the xG rolling cols exist)
            # Applied only in preset mode (learned/hybrid may already have league-specific gates).
            # ---------------------------------------------------------
            have_xg = (
                ("xg_for_avg_5_home" in ftr.columns) and ("xg_for_avg_5_away" in ftr.columns) and
                ("xg_against_avg_5_home" in ftr.columns) and ("xg_against_avg_5_away" in ftr.columns)
            )
            if have_xg and (gate_mode == "preset"):
                pick = ftr["bookie_pick"].astype("string").str.upper().fillna("")

                # Home pick: prefer a 2-of-3 confirmation to avoid wiping strong favourites.
                # Conditions:
                #   1) home creates:      xg_for_avg_5_home >= ftr_xgfor_min
                #   2) away concedes:     xg_against_avg_5_away >= ftr_xgagainst_min
                #   3) home not leaky:    xg_against_avg_5_home <= ftr_home_xga_max
                h_for = pd.to_numeric(ftr["xg_for_avg_5_home"], errors="coerce")
                a_con = pd.to_numeric(ftr["xg_against_avg_5_away"], errors="coerce")
                h_xga = pd.to_numeric(ftr["xg_against_avg_5_home"], errors="coerce")

                home_missing = h_for.isna() | a_con.isna() | h_xga.isna()
                h_for_ok = (h_for >= float(ftr_xgfor_min)).fillna(False)
                a_con_ok = (a_con >= float(ftr_xgagainst_min)).fillna(False)
                h_xga_ok = (h_xga <= float(ftr_home_xga_max)).fillna(False)
                home_points = h_for_ok.astype(int) + a_con_ok.astype(int) + h_xga_ok.astype(int)
                home_pass = (home_points >= 2)
                m_home_xg = pick.eq("HOME") & (home_missing | home_pass)

                # Away pick: away creates, home concedes (keep strict 2-of-2)
                a_for = pd.to_numeric(ftr["xg_for_avg_5_away"], errors="coerce")
                h_con = pd.to_numeric(ftr["xg_against_avg_5_home"], errors="coerce")

                away_missing = a_for.isna() | h_con.isna()
                away_pass = (a_for >= float(ftr_xgfor_min)) & (h_con >= float(ftr_xgagainst_min))
                m_away_xg = pick.eq("AWAY") & (away_missing | away_pass)

                # Draw: do not require xG confirm (neutral)
                m_draw_xg = pick.eq("DRAW")

                # Apply xG confirm. If it would wipe all surviving FTR rows, fail-open (skip xG confirm)
                # so we preserve coverage while we tune thresholds.
                pre_n = int(len(ftr))
                _keep_xg = (m_home_xg | m_away_xg | m_draw_xg)
                if isinstance(_keep_xg, pd.Series):
                    _keep_xg = _keep_xg.reindex(ftr.index)
                else:
                    _keep_xg = pd.Series(_keep_xg, index=ftr.index)
                _keep_xg = _keep_xg.fillna(False)

                ftr_xg = ftr.loc[_keep_xg].copy()

                if bool(debug):
                    try:
                        kept_n = int(_keep_xg.sum())
                        print(f"[deploy_rulebook] FTR xg confirm kept {kept_n}/{pre_n}")
                        cols_dbg = [c for c in (
                            "league","home_team_name","away_team_name","bookie_pick","bookie_od",
                            "xg_for_avg_5_home","xg_against_avg_5_away","xg_against_avg_5_home",
                            "xg_for_avg_5_away","xg_against_avg_5_home",
                            "ftr_margin","gap_used"
                        ) if c in ftr.columns]
                        if cols_dbg:
                            print("[deploy_rulebook] FTR xg confirm sample (kept):")
                            print(ftr_xg[cols_dbg].head(10).to_string(index=False))
                    except Exception:
                        pass

                # Fail-open if xG confirm wipes the set
                if (pre_n > 0) and ftr_xg.empty:
                    if bool(debug):
                        print("[deploy_rulebook] FTR xg confirm wiped all survivors; skipping xG confirm (fail-open)")
                    # keep original survivors
                else:
                    ftr = ftr_xg

                if debug:
                    print(f"[deploy_rulebook] FTR after xg confirm n={len(ftr)}")

            # ---------------------------------------------------------
            # PPG dominance confirmation (pre-match)
            # ---------------------------------------------------------
            if "ppg_diff_pre" in ftr.columns:
                ppgd = pd.to_numeric(ftr["ppg_diff_pre"], errors="coerce")
                pick = ftr["bookie_pick"].astype("string").str.upper().fillna("")

                # UEFA comps: domestic PPG diffs can be weak/non-comparable for gating.
                # Fail-open on UEFA rows (do not veto) and also fail-open when PPG is missing.
                lg = ftr.get("league", pd.Series("", index=ftr.index)).astype("string").fillna("").str.lower()
                is_uefa = lg.str.contains("champions league|europa league|europa conference", regex=True, na=False)
                missing = ppgd.isna() | is_uefa

                fm_ppg = pd.to_numeric(ftr.get("ftr_margin", np.nan), errors="coerce")
                pm_ppg = pd.to_numeric(ftr.get("model_p_for_bookie", np.nan), errors="coerce")
                pt_ppg = ftr.get("pool_tier", pd.Series("", index=ftr.index)).astype("string").fillna("").str.strip().str.upper()

                strong_margin_fail_open = fm_ppg.notna() & (fm_ppg >= float(params.get("ftr_ppg_strong_margin_fail_open", 0.18)))
                high_pm_fail_open = pm_ppg.notna() & (pm_ppg >= float(params.get("ftr_ppg_high_pm_fail_open", 0.58)))
                anchor_fail_open = pt_ppg.eq("ANCHOR_CAND")
                fail_open = missing | strong_margin_fail_open | high_pm_fail_open | anchor_fail_open

                m_home_ppg = pick.eq("HOME") & (fail_open | (ppgd >= float(ftr_ppg_diff_home_min)))
                m_away_ppg = pick.eq("AWAY") & (fail_open | (ppgd <= -float(ftr_ppg_diff_away_min)))

                if ftr_ppg_diff_draw_max is not None:
                    m_draw_ppg = pick.eq("DRAW") & (fail_open | (ppgd.abs() <= float(ftr_ppg_diff_draw_max)))
                else:
                    m_draw_ppg = pick.eq("DRAW")

                before_n = int(len(ftr))
                ftr = ftr[(m_home_ppg | m_away_ppg | m_draw_ppg).fillna(False)].copy()
                if debug:
                    try:
                        print(
                            f"[deploy_rulebook] FTR after ppg confirm n={len(ftr)} (dropped={before_n - int(len(ftr))}) "
                            f"uefa_fail_open={int(is_uefa.sum())} missing_ppg={int(ppgd.isna().sum())} "
                            f"strong_margin_fail_open={int(strong_margin_fail_open.sum())} "
                            f"high_pm_fail_open={int(high_pm_fail_open.sum())} "
                            f"anchor_fail_open={int(anchor_fail_open.sum())}"
                        )
                    except Exception:
                        print(f"[deploy_rulebook] FTR after ppg confirm n={len(ftr)}")

            # ---------------------------------------------------------
            # Optional PPG glue gate (HOME/AWAY only)
            # Uses precomputed ftr_ppg_glue_ok when --ftr-use-precomputed-flags is set.
            # ---------------------------------------------------------
            if bool(params.get("ftr_use_ppg_glue_gate", False)) and (not ftr.empty):
                pick = ftr["bookie_pick"].astype("string").str.upper().fillna("")
                use_pre = bool(params.get("ftr_use_precomputed_flags", False)) and ("ftr_ppg_glue_ok" in ftr.columns)
                league_name = ftr.get("league", pd.Series("", index=ftr.index)).astype("string").fillna("")
                model_p_for_bookie = pd.to_numeric(ftr.get("model_p_for_bookie", np.nan), errors="coerce")
                cs_ftr_alignment = (
                    ftr.get("cs_ftr_alignment", pd.Series("", index=ftr.index))
                    .astype("string")
                    .fillna("")
                    .str.upper()
                )
                hybrid_ppg_override = (
                    pick.isin(["HOME", "AWAY"])
                    & league_name.isin(list(FTR_HYBRID_PPG_OVERRIDE_LEAGUES))
                    & model_p_for_bookie.ge(float(FTR_HYBRID_PPG_OVERRIDE_MODEL_P_MIN))
                    & cs_ftr_alignment.isin(list(FTR_HYBRID_PPG_OVERRIDE_ALIGNMENTS))
                )

                before_n = int(len(ftr))
                if use_pre:
                    glue_ok = pd.to_numeric(
                        ftr.get("ftr_ppg_glue_ok", pd.Series(0, index=ftr.index)),
                        errors="coerce",
                    ).fillna(0).astype(int).eq(1)
                    override_used = pick.isin(["HOME", "AWAY"]) & (~glue_ok) & hybrid_ppg_override
                    keep = (pick.eq("DRAW")) | (pick.isin(["HOME", "AWAY"]) & (glue_ok | hybrid_ppg_override))
                    ftr = ftr.loc[keep.fillna(False)].copy()
                else:
                    dmin = float(params.get("ftr_ppg_glue_diff_min", 0.70))
                    opp_max = float(params.get("ftr_ppg_glue_opp_max", 1.00))

                    ppg_home = pd.to_numeric(ftr.get("ppg_home_pre", np.nan), errors="coerce")
                    ppg_away = pd.to_numeric(ftr.get("ppg_away_pre", np.nan), errors="coerce")
                    ppg_diff = pd.to_numeric(ftr.get("ppg_diff_pre", np.nan), errors="coerce")

                    ppg_opp = pd.Series(np.nan, index=ftr.index)
                    ppg_opp.loc[pick.eq("HOME")] = ppg_away.loc[pick.eq("HOME")]
                    ppg_opp.loc[pick.eq("AWAY")] = ppg_home.loc[pick.eq("AWAY")]

                    m_home = pick.eq("HOME") & ppg_diff.notna() & (ppg_diff >= dmin) & ppg_opp.notna() & (ppg_opp <= opp_max)
                    m_away = pick.eq("AWAY") & ppg_diff.notna() & (ppg_diff <= -dmin) & ppg_opp.notna() & (ppg_opp <= opp_max)
                    m_draw = pick.eq("DRAW")
                    base_pass = (m_home | m_away | m_draw).fillna(False)
                    override_used = pick.isin(["HOME", "AWAY"]) & (~base_pass) & hybrid_ppg_override

                    ftr = ftr.loc[(base_pass | hybrid_ppg_override).fillna(False)].copy()

                if "context_reason_codes" not in ftr.columns:
                    ftr["context_reason_codes"] = ""
                ftr["context_reason_codes"] = ftr["context_reason_codes"].astype("string").fillna("")
                kept_override = override_used.loc[ftr.index].fillna(False)
                if bool(kept_override.any()):
                    ftr.loc[kept_override, "context_reason_codes"] = ftr.loc[
                        kept_override, "context_reason_codes"
                    ].map(lambda x: _combine_pipe(x, "FTR_HYBRID_PPG_OVERRIDE"))

                if debug:
                    mode = "precomputed" if use_pre else "computed"
                    removed = before_n - int(len(ftr))
                    print(f"[deploy_rulebook] FTR PPG glue gate ({mode}) removed {removed} rows")
                    print(
                        "[deploy_rulebook] FTR hybrid PPG override kept "
                        f"{int(override_used.sum())} rows in {sorted(FTR_HYBRID_PPG_OVERRIDE_LEAGUES)}"
                    )
                    print(f"[deploy_rulebook] FTR after ppg_glue_gate n={len(ftr)}")


        # ---------------------------------------------------------
        # End of post-lane FTR gates (Accuracy lane only)
        # ---------------------------------------------------------
        # Only apply the following post-lane FTR gates if _skip_ftr_post_lane_gates is False
        if not _skip_ftr_post_lane_gates:
            # ---------------------------------------------------------
            # Optional draw-trap veto for ultra-short favourites (HOME/AWAY)
            # Uses precomputed ftr_drawtrap_flag when --ftr-use-precomputed-flags is set.
            # Allows trap rows only if margin/xg_sum confirmations are met.
            # ---------------------------------------------------------
            if bool(params.get("ftr_use_drawtrap_veto", False)) and (not ftr.empty):
                pick = ftr["bookie_pick"].astype("string").str.upper().fillna("")
                use_pre = bool(params.get("ftr_use_precomputed_flags", False)) and ("ftr_drawtrap_flag" in ftr.columns)

                before_n = int(len(ftr))

                if use_pre:
                    trap = pd.to_numeric(
                        ftr.get("ftr_drawtrap_flag", pd.Series(0, index=ftr.index)),
                        errors="coerce",
                    ).fillna(0).astype(int).eq(1)
                    trap = trap & pick.isin(["HOME", "AWAY"])
                else:
                    od_max = float(params.get("ftr_drawtrap_od_max", 1.30))
                    opp_min = float(params.get("ftr_drawtrap_opp_ppg_min", 1.20))

                    od = pd.to_numeric(ftr.get("bookie_od", np.nan), errors="coerce")
                    ppg_home = pd.to_numeric(ftr.get("ppg_home_pre", np.nan), errors="coerce")
                    ppg_away = pd.to_numeric(ftr.get("ppg_away_pre", np.nan), errors="coerce")

                    ppg_opp = pd.Series(np.nan, index=ftr.index)
                    ppg_opp.loc[pick.eq("HOME")] = ppg_away.loc[pick.eq("HOME")]
                    ppg_opp.loc[pick.eq("AWAY")] = ppg_home.loc[pick.eq("AWAY")]

                    trap = pick.isin(["HOME", "AWAY"]) & od.notna() & (od <= od_max) & ppg_opp.notna() & (ppg_opp >= opp_min)

                req_margin = float(params.get("ftr_drawtrap_require_margin_min", 0.18))
                req_xgsum = float(params.get("ftr_drawtrap_require_xgsum_min", 2.60))

                m_allow = pd.Series(False, index=ftr.index)
                if "ftr_margin" in ftr.columns:
                    m_allow = m_allow | (pd.to_numeric(ftr["ftr_margin"], errors="coerce") >= req_margin)
                if "xg_sum_pre_match" in ftr.columns:
                    m_allow = m_allow | (pd.to_numeric(ftr["xg_sum_pre_match"], errors="coerce") >= req_xgsum)

                keep = (~trap) | (trap & m_allow)
                ftr = ftr.loc[keep.fillna(False)].copy()

                if debug:
                    mode = "precomputed" if use_pre else "computed"
                    removed = before_n - int(len(ftr))
                    print(f"[deploy_rulebook] FTR drawtrap veto ({mode}) removed {removed} rows")
                    print(f"[deploy_rulebook] FTR after drawtrap veto n={len(ftr)}")

            # --- Draw/Chaos veto (GLUE hygiene) ---
            if params.get("ftr_draw_chaos_veto", False):
                try:
                    # Apply ONLY to GLUE-tier rows (do not kill anchor candidates)
                    if "pool_tier" in ftr.columns:
                        _tier = ftr["pool_tier"].astype("string").fillna("").str.strip().str.upper()
                        _is_glue = _tier.eq("GLUE") | _tier.eq("")
                    else:
                        # If pool_tier is missing/unknown, do NOT treat as GLUE (fail-open).
                        _is_glue = pd.Series(False, index=ftr.index)

                    _ftr_glue = ftr.loc[_is_glue].copy()
                    _ftr_other = ftr.loc[~_is_glue].copy()

                    before = int(len(_ftr_glue))

                    if "not_glue_flag" in _ftr_glue.columns:
                        ng = pd.to_numeric(_ftr_glue["not_glue_flag"], errors="coerce").fillna(0).astype(int)
                        if debug:
                            try:
                                cols_dbg = [c for c in (
                                    "league", "fixture_key", "home_team_name", "away_team_name",
                                    "bookie_pick", "bookie_od", "bookie_implied", "bookie_implied_used",
                                    "model_p_for_bookie", "agree_model_vs_bookie", "gap_used", "ftr_margin", "power_diff",
                                    "ppg_diff_pre", "not_glue_flag", "draw_chaos_score", "chaos_risk_flag", "draw_risk_flag",
                                    "deterministic_pass", "deterministic_veto_reason", "reason_codes",
                                    "pool_tier", "candidate_rank", "close_match_flag", "context_reason_codes"
                                ) if c in _ftr_glue.columns]
                                print(f"[deploy_rulebook] FTR(GLUE) pre not_glue diagnostic rows={len(_ftr_glue)} flagged={int((ng > 0).sum())}")
                                if cols_dbg:
                                    flagged = _ftr_glue.loc[(ng > 0), cols_dbg].copy()
                                    if not flagged.empty:
                                        sort_cols = [c for c in ("not_glue_flag", "draw_chaos_score", "ftr_margin", "gap_used") if c in flagged.columns]
                                        if sort_cols:
                                            # high flags/chaos first, weak margin/gap first
                                            asc = []
                                            for c in sort_cols:
                                                if c in ("ftr_margin", "gap_used"):
                                                    asc.append(True)
                                                else:
                                                    asc.append(False)
                                            flagged = flagged.sort_values(sort_cols, ascending=asc, na_position="last")
                                        print("[deploy_rulebook] FTR(GLUE) flagged rows before not_glue handling (sample):")
                                        print(flagged.head(12).to_string(index=False))
                            except Exception as e:
                                print(f"[deploy_rulebook] FTR(GLUE) pre not_glue debug failed: {e}")

                        # Default: no UEFA override (A/B toggle can disable UEFA effects)
                        uefa_override = pd.Series(False, index=_ftr_glue.index)

                        if (os.getenv("OG_UEFA_MODE", "on").lower() != "off") and bool(params.get("uefa_enable_not_glue_fail_open", False)):
                            # UEFA fail-open for strong favourites: don't let not_glue_flag wipe these.
                            lg = _ftr_glue.get("league", pd.Series("", index=_ftr_glue.index)).astype("string").fillna("").str.lower()
                            is_uefa = lg.str.contains("champions league|europa league|europa conference", regex=True, na=False)

                            # Use RAW implied for the short-favourite test; fall back to implied_used only if raw is missing.
                            imp_raw = pd.to_numeric(_ftr_glue.get("bookie_implied", np.nan), errors="coerce")
                            imp_used_fallback = pd.to_numeric(_ftr_glue.get("bookie_implied_used", np.nan), errors="coerce")
                            imp_for_override = imp_raw.where(imp_raw.notna(), imp_used_fallback)

                            fm = pd.to_numeric(_ftr_glue.get("ftr_margin", np.nan), errors="coerce")

                            # False-positive guards (prevent rescuing draw-trap favourites like PSG 1-1 Newcastle)
                            gap_used = pd.to_numeric(_ftr_glue.get("gap_used", np.nan), errors="coerce")
                            xga_home = pd.to_numeric(_ftr_glue.get("xg_against_avg_5_home", np.nan), errors="coerce")

                            uefa_imp_min = float(params.get("ftr_not_glue_veto_uefa_implied_min", 0.68))
                            uefa_margin_min = float(params.get("ftr_not_glue_veto_uefa_margin_min", 0.25))
                            uefa_gap_min = float(params.get("ftr_not_glue_veto_uefa_gap_min", 0.0))
                            uefa_xga_home_max = float(params.get("ftr_not_glue_veto_uefa_xga_home_max", 1.15))

                            uefa_override = (
                                is_uefa
                                & imp_for_override.notna()
                                & fm.notna()
                                & (imp_for_override >= uefa_imp_min)
                                & (fm >= uefa_margin_min)
                                # Guard A: require non-negative edge
                                & gap_used.notna()
                                & (gap_used >= uefa_gap_min)
                                # Guard B: require not-leaky favourite (home xGA)
                                & xga_home.notna()
                                & (xga_home <= uefa_xga_home_max)
                            )

                        dcs = pd.to_numeric(_ftr_glue.get("draw_chaos_score", np.nan), errors="coerce")
                        draw_flag = pd.to_numeric(
                            _ftr_glue.get("draw_risk_flag", pd.Series(0, index=_ftr_glue.index)),
                            errors="coerce",
                        ).fillna(0).astype(int)

                        chaos_flag = pd.to_numeric(
                            _ftr_glue.get("chaos_risk_flag", pd.Series(0, index=_ftr_glue.index)),
                            errors="coerce",
                        ).fillna(0).astype(int)
                        hard_ng_pre = pd.to_numeric(_ftr_glue.get("hard_not_glue_flag", np.nan), errors="coerce")
                        hard_not_glue = hard_ng_pre.fillna(0).astype(int).gt(0)
                        if hard_ng_pre.isna().all():
                            hard_not_glue = (draw_flag > 0) & dcs.notna() & (dcs >= float(params.get("ftr_draw_chaos_score_max", 0.60)))

                        soft_saved = pd.Series(False, index=_ftr_glue.index, dtype="bool")
                        if bool(params.get("soft_ftr_not_glue", False)):
                            fm_soft = pd.to_numeric(_ftr_glue.get("ftr_margin", np.nan), errors="coerce")
                            soft_margin_min = float(params.get("soft_ftr_not_glue_margin_min", 0.14))
                            soft_saved = hard_not_glue & fm_soft.notna() & fm_soft.ge(soft_margin_min)

                        keep_mask = (~hard_not_glue) | uefa_override | soft_saved
                        warn_only_mask = (ng > 0) & (~hard_not_glue)
                        dropped_n = int((~keep_mask).sum())
                        saved_n = int((uefa_override & hard_not_glue).sum())
                        warn_only_n = int(warn_only_mask.sum())
                        soft_saved_n = int(soft_saved.sum())

                        _ftr_glue = _ftr_glue.loc[keep_mask].copy()

                        if "context_reason_codes" not in _ftr_glue.columns:
                            _ftr_glue["context_reason_codes"] = ""
                        _ftr_glue["context_reason_codes"] = _ftr_glue["context_reason_codes"].astype("string").fillna("")

                        kept_warn_only = warn_only_mask.loc[_ftr_glue.index].fillna(False)
                        if bool(kept_warn_only.any()):
                            _ftr_glue.loc[kept_warn_only, "context_reason_codes"] = _ftr_glue.loc[
                                kept_warn_only, "context_reason_codes"
                            ].map(lambda x: _combine_pipe(x, "FTR_NOT_GLUE_WARN"))

                        kept_chaos_only = ((chaos_flag > 0) & (draw_flag <= 0)).loc[_ftr_glue.index].fillna(False)
                        if bool(kept_chaos_only.any()):
                            _ftr_glue.loc[kept_chaos_only, "context_reason_codes"] = _ftr_glue.loc[
                                kept_chaos_only, "context_reason_codes"
                            ].map(lambda x: _combine_pipe(x, "FTR_CHAOS_WARN"))

                        kept_draw_warn = ((draw_flag > 0) & (~hard_not_glue)).loc[_ftr_glue.index].fillna(False)
                        if bool(kept_draw_warn.any()):
                            _ftr_glue.loc[kept_draw_warn, "context_reason_codes"] = _ftr_glue.loc[
                                kept_draw_warn, "context_reason_codes"
                            ].map(lambda x: _combine_pipe(x, "FTR_DRAW_RISK_WARN"))

                        kept_uefa_saved = (uefa_override & hard_not_glue).loc[_ftr_glue.index].fillna(False)
                        if bool(kept_uefa_saved.any()):
                            _ftr_glue.loc[kept_uefa_saved, "context_reason_codes"] = _ftr_glue.loc[
                                kept_uefa_saved, "context_reason_codes"
                            ].map(lambda x: _combine_pipe(x, "UEFA_NOT_GLUE_FAIL_OPEN"))

                        kept_soft_saved = soft_saved.loc[_ftr_glue.index].fillna(False)
                        if bool(kept_soft_saved.any()):
                            _ftr_glue.loc[kept_soft_saved, "context_reason_codes"] = _ftr_glue.loc[
                                kept_soft_saved, "context_reason_codes"
                            ].map(lambda x: _combine_pipe(x, "FTR_NOT_GLUE_SOFT_AB"))

                        if debug:
                            print(
                                f"[deploy_rulebook] FTR(GLUE) after not_glue_flag handling n={len(_ftr_glue)} "
                                f"(dropped={dropped_n}, warn_only={warn_only_n}, saved_uefa={saved_n}, soft_saved={soft_saved_n})"
                            )

                    elif "draw_chaos_score" in _ftr_glue.columns:
                        thr = float(params.get("ftr_draw_chaos_score_max", 0.60))
                        dcs = pd.to_numeric(_ftr_glue["draw_chaos_score"], errors="coerce").fillna(0.0)
                        _ftr_glue = _ftr_glue.loc[dcs <= thr].copy()
                        if debug:
                            print(
                                f"[deploy_rulebook] FTR(GLUE) after draw_chaos_score<= {thr:.2f} n={len(_ftr_glue)} "
                                f"(dropped={before - len(_ftr_glue)})"
                            )

                    # Recombine, preserving original indices
                    ftr = pd.concat([_ftr_glue, _ftr_other], axis=0)
                except Exception:
                    # Never fail deploy on veto logic
                    pass

            # Optional H2H draw-veto for non-DRAW picks (proxy)
            if (ftr_h2h_draw_veto_min is not None) and ("h2h_n" in ftr.columns) and ("h2h_btts_rate" in ftr.columns):
                hn = pd.to_numeric(ftr["h2h_n"], errors="coerce")
                proxy_drawish = 1.0 - pd.to_numeric(ftr["h2h_btts_rate"], errors="coerce")
                pick = ftr["bookie_pick"].astype("string").str.upper().fillna("")
                m_ok = (hn < float(ftr_h2h_min_n)) | pick.eq("DRAW") | (proxy_drawish < float(ftr_h2h_draw_veto_min))
                ftr = ftr[m_ok.fillna(False)].copy()
                if debug:
                    print(f"[deploy_rulebook] FTR after H2H veto n={len(ftr)}")

            # optional odds min
            if ftr_od_min is not None:
                try:
                    ftr_od_min_f = float(ftr_od_min)
                    before_n = int(len(ftr))
                    ftr = ftr[_to_num(ftr["bookie_od"]).fillna(0.0) >= ftr_od_min_f].copy()
                    if debug:
                        print(f"[deploy_rulebook] FTR after od_min>={ftr_od_min_f:.3f} n={len(ftr)} (dropped={before_n - len(ftr)})")
                except Exception:
                    pass

            # directional PD
            pdiff = _to_num(_col(ftr, "power_diff"))
            pick = ftr["bookie_pick"].astype("string").str.upper().fillna("")

            if debug:
                try:
                    before_n = int(len(ftr))
                    miss_pd = pdiff.isna()

                    below_home = pick.eq("HOME") & pdiff.notna() & (pdiff < float(ftr_pd_home_min))
                    below_away = pick.eq("AWAY") & pdiff.notna() & (pdiff > float(ftr_pd_away_min))
                    below_draw = pick.eq("DRAW") & pdiff.notna() & (pdiff.abs() > float(ftr_draw_pd_max)) if use_draw_rule else pd.Series(False, index=ftr.index)

                    print(
                        "[deploy_rulebook] FTR power_diff pre-gate: "
                        f"n={before_n} | missing_pd={int(miss_pd.sum())} | "
                        f"home_below_thr={int(below_home.sum())} | away_below_thr={int(below_away.sum())} | "
                        f"draw_outside_thr={int(below_draw.sum()) if use_draw_rule else 0} | "
                        f"strong_margin_relax={int((pd.to_numeric(ftr.get('ftr_margin', np.nan), errors='coerce') >= float(params.get('ftr_pd_relax_margin_min', 0.14))).fillna(False).sum())}"
                    )
                except Exception as e:
                    print(f"[deploy_rulebook] FTR power_diff debug failed: {e}")

            od = pd.to_numeric(ftr.get("bookie_od", np.nan), errors="coerce")
            imp_used2 = pd.to_numeric(ftr.get("bookie_implied_used", ftr.get("bookie_implied", np.nan)), errors="coerce")

            short_od_max = float(params.get("ftr_short_od_max", 1.10))
            short_imp_min = float(params.get("ftr_short_imp_min", 0.85))
            pd_home_min_short = float(params.get("ftr_pd_home_min_short", 2.0))
            strong_margin_pd_bypass = float(params.get("ftr_pd_relax_margin_min", 0.14))
            strong_margin_pd_home_min = float(params.get("ftr_pd_home_min_strong_margin", 0.0))
            strong_margin_pd_away_max = float(params.get("ftr_pd_away_min_strong_margin", 0.0))

            fm_pd = pd.to_numeric(ftr.get("ftr_margin", np.nan), errors="coerce")
            is_ultra_short = (od.notna() & (od <= short_od_max)) | (imp_used2.notna() & (imp_used2 >= short_imp_min))
            strong_margin_mask = fm_pd.notna() & (fm_pd >= strong_margin_pd_bypass)

            thr_home = pd.Series(float(ftr_pd_home_min), index=ftr.index, dtype=float)
            thr_home = thr_home.mask(is_ultra_short.fillna(False), float(pd_home_min_short))
            thr_home = thr_home.mask(strong_margin_mask.fillna(False), float(strong_margin_pd_home_min))

            thr_away = pd.Series(float(ftr_pd_away_min), index=ftr.index, dtype=float)
            thr_away = thr_away.mask(strong_margin_mask.fillna(False), float(strong_margin_pd_away_max))

            m_home = pick.eq("HOME") & (pdiff >= thr_home)
            m_away = pick.eq("AWAY") & (pdiff <= thr_away)
            if use_draw_rule:
                m_draw = pick.eq("DRAW") & (pdiff.abs() <= float(ftr_draw_pd_max))
            else:
                m_draw = pick.eq("DRAW")

            keep_mask = (m_home | m_away | m_draw).fillna(False)

            if debug:
                try:
                    drop_mask = ~keep_mask
                    cols_dbg = [c for c in ("league","fixture_key","home_team_name","away_team_name","bookie_pick","power_diff","ftr_margin","model_p_for_bookie","gap_used") if c in ftr.columns]
                    if cols_dbg and bool(drop_mask.any()):
                        print("[deploy_rulebook] FTR power_diff drops (sample):")
                        print(ftr.loc[drop_mask, cols_dbg].head(8).to_string(index=False))
                except Exception as e:
                    print(f"[deploy_rulebook] FTR power_diff drop-sample failed: {e}")

            before_n2 = int(len(ftr))
            ftr = ftr[keep_mask].copy()

            if debug:
                print(f"[deploy_rulebook] FTR after power_diff gate n={len(ftr)} (dropped={before_n2 - len(ftr)})")
            # End of post-lane FTR gates (Accuracy lane only)


        # (No further FTR gating pipeline outside the else branch. All post-lane gates are handled above.)

        # OU25 filter

    # OU25 filter
    ou = out[out["market"].eq("ou25")].copy()
    if not ou.empty:
        if debug:
            print(f"[deploy_rulebook] OU25 start n={len(ou)}")
        _ou_audit = params.get("_ou25_gate_audit") if isinstance(params, dict) else None
        if isinstance(_ou_audit, dict):
            _ou_audit["ou25_input"] = int(len(ou))
            def _ou_audit_add_league_counts(gate: str, league_series: pd.Series, mask: pd.Series) -> None:
                if not isinstance(_ou_audit, dict):
                    return
                if gate not in _ou_audit["by_league"]:
                    _ou_audit["by_league"][gate] = {}

                league_series = pd.Series(league_series, copy=False)
                mask_series = pd.Series(mask, index=getattr(mask, "index", league_series.index), copy=False)
                mask_series = mask_series.reindex(league_series.index, fill_value=False).fillna(False).astype(bool)

                league_counts = (
                    league_series.loc[mask_series]
                    .astype("string")
                    .fillna("")
                    .replace("", "UNKNOWN")
                    .value_counts()
                )
                for lg, cnt in league_counts.items():
                    _ou_audit["by_league"][gate][str(lg)] = int(
                        _ou_audit["by_league"][gate].get(str(lg), 0)
                    ) + int(cnt)
            if "_ou25_input_by_league" not in _ou_audit:
                _ou_audit["_ou25_input_by_league"] = {}
            _ou_audit_add_league_counts(
                "ou25_input",
                ou.get("league", pd.Series("", index=ou.index)),
                pd.Series(True, index=ou.index),
            )
            if isinstance(_ou_audit.get("_ou25_input_by_league"), dict):
                lc = ou.get("league", pd.Series("", index=ou.index)).astype("string").fillna("").replace("", "UNKNOWN").value_counts()
                for lg, cnt in lc.items():
                    _ou_audit["_ou25_input_by_league"][str(lg)] = int(
                        _ou_audit["_ou25_input_by_league"].get(str(lg), 0)
                    ) + int(cnt)
        ou = ou[agree.loc[ou.index]].copy()
        if debug:
            print(f"[deploy_rulebook] OU25 after agree n={len(ou)}")
        if isinstance(_ou_audit, dict):
            _ou_audit["ou25_after_agree"] = int(len(ou))
        if debug:
            print(f"[deploy_rulebook] OU25 before per-side implied band n={len(ou)}")
        # optional abs power gate (knob)
        if ou_abs_pd_min and np.isfinite(ou_abs_pd_min) and ou_abs_pd_min > 0:
            pdiff = _to_num(_col(ou, "power_diff")).abs().fillna(0.0)
            ou = ou[pdiff >= ou_abs_pd_min].copy()
        if debug:
            print(f"[deploy_rulebook] OU25 after abs power gate n={len(ou)}")
        if isinstance(_ou_audit, dict):
            _ou_audit["ou25_after_abs_pd"] = int(len(ou))
        
        # --- OU25: branch on bookie_pick (OVER25 vs UNDER25) ---
        _pick = ou.get("bookie_pick", pd.Series("OVER25", index=ou.index))
        _pick = _pick.astype("string").fillna("").str.upper().str.strip()

        ou_over = ou[_pick.eq("OVER25")].copy()
        ou_under = ou[_pick.eq("UNDER25")].copy()
        ou_other = ou[~_pick.isin(["OVER25", "UNDER25"])].copy()  # safety; treat as pass-through
        if isinstance(_ou_audit, dict):
            _ou_audit["ou25_over_input"] = int(len(ou_over))
            _ou_audit["ou25_under_input"] = int(len(ou_under))

        if debug:
            print(f"[deploy_rulebook] OU25 split over={len(ou_over)} under={len(ou_under)} other={len(ou_other)}")

        def _apply_implied_band(df_part: pd.DataFrame, lo: float, hi: float, label: str) -> pd.DataFrame:
            if df_part is None or df_part.empty:
                return df_part

            # Prefer raw implied if present, otherwise fall back to implied_used.
            imp_part = _to_num(df_part.get("bookie_implied", df_part.get("bookie_implied_used"))).fillna(-1.0)
            m = (imp_part >= float(lo)) & (imp_part < float(hi))

            # Fail-open: if the band would wipe this side entirely, skip the band.
            if not bool(m.any()):
                if debug:
                    print(f"[deploy_rulebook] OU25({label}) implied band wiped all rows; skipping band (fail-open)")
                return df_part

            df_part2 = df_part.loc[m].copy()
            if debug:
                print(f"[deploy_rulebook] OU25({label}) after implied band n={len(df_part2)}")
            return df_part2

        ou_over = _apply_implied_band(ou_over, ou_over_implied_lo, ou_over_implied_hi, "OVER")
        ou_under = _apply_implied_band(ou_under, ou_under_implied_lo, ou_under_implied_hi, "UNDER")

        def _safe_num_series(df: pd.DataFrame, col: str, default=np.nan) -> pd.Series:
            return pd.to_numeric(df.get(col, pd.Series(default, index=df.index)), errors="coerce")


        def _score_total_goals_from_cs(score: object) -> float:
            try:
                s = str(score).strip()
                if "-" not in s:
                    return np.nan
                h, a = s.split("-", 1)
                return float(int(h) + int(a))
            except Exception:
                return np.nan


        def _first_existing_num_series(df: pd.DataFrame, cols: list[str], default=np.nan) -> pd.Series:
            for col in cols:
                if col in df.columns:
                    s = _safe_num_series(df, col, default=default)
                    if s.notna().any():
                        return s
            return pd.Series(default, index=df.index, dtype="float64")


        def _compute_avg_btts_rate_live(df: pd.DataFrame) -> pd.Series:
            home = _first_existing_num_series(
                df,
                [
                    "btts_rate_5_home",
                    "avg_btts_rate_home",
                    "rolling_btts_rate_5_home",
                    "btts_rate_10_home",
                    "home_snap__btts_percentage_home",
                    "home_snap__btts_percentage",
                ],
            )
            away = _first_existing_num_series(
                df,
                [
                    "btts_rate_5_away",
                    "avg_btts_rate_away",
                    "rolling_btts_rate_5_away",
                    "btts_rate_10_away",
                    "away_snap__btts_percentage_away",
                    "away_snap__btts_percentage",
                ],
            )

            home = home.where(home <= 1.0, home / 100.0)
            away = away.where(away <= 1.0, away / 100.0)

            pre_match_btts = _safe_num_series(df, "btts_percentage_pre_match")
            pre_match_btts = pre_match_btts.where(pre_match_btts <= 1.0, pre_match_btts / 100.0)

            home = home.where(home.notna(), pre_match_btts)
            away = away.where(away.notna(), pre_match_btts)
            return (home + away) / 2.0


        def _compute_cs_over25_mass_live(df: pd.DataFrame) -> pd.Series:
            out_part = pd.Series(0.0, index=df.index, dtype="float64")
            for score_col, prob_col in [("cs1", "cs1_p"), ("cs2", "cs2_p"), ("cs3", "cs3_p")]:
                if score_col not in df.columns or prob_col not in df.columns:
                    continue
                totals = df[score_col].map(_score_total_goals_from_cs)
                probs = _safe_num_series(df, prob_col).fillna(0.0)
                out_part = out_part + probs.where(totals > 2.0, 0.0)
            return out_part


        def _compute_top3_over_count_live(df: pd.DataFrame) -> pd.Series:
            out_part = pd.Series(0, index=df.index, dtype="int64")
            for score_col in ["cs1", "cs2", "cs3"]:
                if score_col not in df.columns:
                    continue
                totals = df[score_col].map(_score_total_goals_from_cs)
                out_part = out_part + (totals > 2.0).fillna(False).astype(int)
            return out_part


        def _stamp_ou25_over_live_features(df_part: pd.DataFrame) -> pd.DataFrame:
            if df_part is None:
                return pd.DataFrame()

            out_part = df_part.copy()
            if out_part.empty:
                for c in ["avg_btts_rate", "cs_over25_mass", "top3_over_count"]:
                    if c not in out_part.columns:
                        out_part[c] = pd.Series(dtype="float64")
                return out_part

            out_part["avg_btts_rate"] = _compute_avg_btts_rate_live(out_part)
            out_part["cs_over25_mass"] = _compute_cs_over25_mass_live(out_part)
            out_part["top3_over_count"] = _compute_top3_over_count_live(out_part).astype("float64")
            return out_part


        def _apply_over_rules(df_over: pd.DataFrame) -> pd.DataFrame:
            if df_over is None or df_over.empty:
                return df_over
            if "ou25_over_struct_pass" not in df_over.columns:
                df_over["ou25_over_struct_pass"] = 0

            # Model probability floor: p_model >= max(ou_pmin_floor, implied_used - tol_ou)
            league_series = df_over.get("league", pd.Series("", index=df_over.index))
            _imp_used = df_over.get("bookie_implied_used", df_over.get("bookie_implied"))
            _imp_used = pd.to_numeric(_imp_used, errors="coerce")
            _pm = pd.to_numeric(df_over.get("model_p_for_bookie"), errors="coerce")

            _floor = np.maximum(float(ou_pmin_floor), _imp_used.fillna(0.0) - float(tol_ou_f))
            mask_floor = _pm.fillna(-1e9) >= _floor
            if isinstance(_ou_audit, dict):
                _ou_audit["ou25_over_model_p_missing"] = int(_pm.isna().sum())
                if bool(_pm.isna().any()):
                    _ou_audit_add_league_counts("ou25_over_model_p_missing", league_series, _pm.isna())

            # Override only when overround is missing (single-sided odds) but lambda is strongly high
            _lam = pd.to_numeric(df_over.get("bookie_lambda_total_fit"), errors="coerce")
            _overround = pd.to_numeric(df_over.get("bookie_overround"), errors="coerce")
            mask_override = (_overround.isna()) & (_lam >= float(ou_lambda_override_min)) & (_pm >= float(ou_override_pmin))

            df_over = df_over.loc[(mask_floor | mask_override).fillna(False)].copy()
            if debug:
                print(f"[deploy_rulebook] OU25(OVER) after model floor/override n={len(df_over)}")

            # ===========================
            # OVER25: pmin + veto layer
            # ===========================
            sig = _normalize_signal_label_series(_get_ou25_signal_series(df_over, default=""), default="")
            elite_sig = sig.isin(["STRONG_OVER", "VERY_STRONG_OVER"]).fillna(False)

            # Require OVER signal for OVER25 picks (prevents STRONG_UNDER / NEUTRAL rows slipping through)
            _pre_sig = int(len(df_over))
            sig_mask = elite_sig.reindex(df_over.index).fillna(False)
            df_over = df_over.loc[sig_mask].copy()
            if isinstance(_ou_audit, dict):
                _ou_audit["ou25_over_signal_fail"] = int(_pre_sig - len(df_over))
                if bool((~sig_mask).any()):
                    _ou_audit_add_league_counts("ou25_over_signal_fail", league_series, ~sig_mask)
            if debug:
                print(f"[deploy_rulebook] OU25(OVER) after STRONG/VERY_STRONG over-signal gate n={len(df_over)}")

            pm_over = pd.to_numeric(df_over.get("model_p_for_bookie", np.nan), errors="coerce")
            m_floor = pm_over >= float(ou_pmin_floor)
            _pre_floor = int(len(df_over))
            df_over = df_over.loc[m_floor.fillna(False)].copy()
            if isinstance(_ou_audit, dict):
                _ou_audit["ou25_over_model_floor_fail"] = int(_pre_floor - len(df_over))
                _ou_audit_add_league_counts("ou25_over_model_floor_fail", league_series, ~m_floor.fillna(False))
            if debug:
                print(f"[deploy_rulebook] OU25(OVER) after p>={float(ou_pmin_floor):.2f} n={len(df_over)}")

            if "context_reason_codes" not in df_over.columns:
                df_over["context_reason_codes"] = ""
            df_over["context_reason_codes"] = df_over["context_reason_codes"].astype("string").fillna("")


            # Optional H2H confirmation for OVER
            if ou_over_h2h_min is not None and ("h2h_n" in df_over.columns) and ("h2h_over25_rate" in df_over.columns):
                hn = pd.to_numeric(df_over["h2h_n"], errors="coerce")
                hr = pd.to_numeric(df_over["h2h_over25_rate"], errors="coerce")
                m_h2h = (hn < float(h2h_min_n)) | (hr >= float(ou_over_h2h_min))
                df_over = df_over[m_h2h.fillna(False)].copy()
                if debug:
                    print(f"[deploy_rulebook] OU25(OVER) after H2H gate n={len(df_over)}")

            # ==========================================================
            # OU25 OVER structural confirmation layer
            # walk-forward validated variant logic
            # ==========================================================
            df_over = _stamp_ou25_over_live_features(df_over)

            if not df_over.empty:
                top3_over = pd.to_numeric(df_over["top3_over_count"], errors="coerce")
                m_struct_combo = _ou25_struct_combo_mask(df_over)
                m_top3 = _ou25_top3_mask(df_over)
                soft_top3 = pd.Series(False, index=df_over.index, dtype="bool")
                if bool(params.get("soft_ou25_top3", False)):
                    model_p_soft = pd.to_numeric(df_over.get("model_p_for_bookie", np.nan), errors="coerce")
                    soft_model_p_min = float(params.get("soft_ou25_top3_model_p_min", 0.60))
                    soft_top3_min = float(params.get("soft_ou25_top3_min_count", 1.0))
                    soft_top3 = top3_over.ge(soft_top3_min) & model_p_soft.ge(soft_model_p_min)
                keep_mask = (m_struct_combo & (m_top3 | soft_top3)).fillna(False)
                if isinstance(_ou_audit, dict):
                    _ou_audit["ou25_over_struct_combo_fail"] = int((~m_struct_combo.fillna(False)).sum())
                    _ou_audit["ou25_over_top3_fail"] = int((~m_top3.fillna(False)).sum())
                    _ou_audit_add_league_counts("ou25_over_struct_combo_fail", df_over.get("league", pd.Series("", index=df_over.index)), ~m_struct_combo.fillna(False))
                    _ou_audit_add_league_counts("ou25_over_top3_fail", df_over.get("league", pd.Series("", index=df_over.index)), ~m_top3.fillna(False))
                    avg_btts = pd.to_numeric(df_over["avg_btts_rate"], errors="coerce")
                    cs_mass = pd.to_numeric(df_over["cs_over25_mass"], errors="coerce")
                    missing_struct_inputs = avg_btts.isna() | cs_mass.isna() | top3_over.isna()
                    _ou_audit["ou25_over_struct_inputs_missing"] = int(missing_struct_inputs.sum())
                    if bool(missing_struct_inputs.any()):
                        _ou_audit_add_league_counts(
                            "ou25_over_struct_inputs_missing",
                            df_over.get("league", pd.Series("", index=df_over.index)),
                            missing_struct_inputs,
                        )

                if debug:
                    print(
                        f"[deploy_rulebook] OU25(OVER) after avg_btts>=0.50 AND cs_over25_mass>=0.15 n={int(m_struct_combo.fillna(False).sum())}"
                    )
                    print(f"[deploy_rulebook] OU25(OVER) after top3_over_count>=2 n={int(keep_mask.sum())}")
                    try:
                        print(
                            "[deploy_rulebook] OU25(OVER) top3_over_count dist:",
                            top3_over.value_counts(dropna=False).to_dict(),
                        )
                    except Exception:
                        pass
                    if bool(params.get("soft_ou25_top3", False)):
                        try:
                            print(
                                "[deploy_rulebook] OU25 soft top3 rescue:",
                                {
                                    "soft_saved_rows": int((keep_mask & (~m_top3.fillna(False))).sum()),
                                    "top3_min": float(params.get("soft_ou25_top3_min_count", 1.0)),
                                    "model_p_min": float(params.get("soft_ou25_top3_model_p_min", 0.60)),
                                },
                            )
                        except Exception:
                            pass

                rescued_soft = (keep_mask & (~m_top3.fillna(False))).fillna(False)
                df_over = df_over.loc[keep_mask].copy()
                df_over["ou25_over_struct_pass"] = 1
                if bool(params.get("soft_ou25_top3", False)) and bool(rescued_soft.any()):
                    rescued_soft = rescued_soft.loc[df_over.index].fillna(False)
                    if "context_reason_codes" not in df_over.columns:
                        df_over["context_reason_codes"] = ""
                    df_over["context_reason_codes"] = df_over["context_reason_codes"].astype("string").fillna("")
                    _append_reason_token(df_over, "context_reason_codes", rescued_soft, "OU25_TOP3_SOFT_AB")
                    if "reason_codes" in df_over.columns:
                        _append_reason_token(df_over, "reason_codes", rescued_soft, "OU25_TOP3_SOFT_AB")
                df_over = _stamp_ou25_over_live_features(df_over)

            # Optional veto: one-sided dominant clean-sheet matrix
            # Catches Barcelona-type patterns: 3-0 / 4-0 / 2-0
            if not df_over.empty:
                one_sided_no_btts = pd.to_numeric(
                    df_over.get("one_sided_no_btts", pd.Series(0, index=df_over.index)),
                    errors="coerce",
                ).fillna(0)

                avg_btts = pd.to_numeric(
                    df_over.get("avg_btts_rate", pd.Series(np.nan, index=df_over.index)),
                    errors="coerce",
                )

                veto_one_sided = one_sided_no_btts.ge(1) & avg_btts.le(0.50)

                if debug:
                    print(f"[deploy_rulebook] OU25(OVER) one_sided_no_btts veto dropped n={int(veto_one_sided.sum())}")

                _pre_veto = int(len(df_over))
                df_over = df_over.loc[~veto_one_sided.fillna(False)].copy()
                if isinstance(_ou_audit, dict):
                    _ou_audit["ou25_over_one_sided_veto"] = int(_pre_veto - len(df_over))
                    _ou_audit_add_league_counts("ou25_over_one_sided_veto", df_over.get("league", pd.Series("", index=df_over.index)), veto_one_sided.fillna(False))
                df_over = _stamp_ou25_over_live_features(df_over)

            return df_over


        # Structural confirmation (UNDERS):
        # pass if under25 rates pass,
        # or if both low-goaliness and xG-sum structure pass.
        def _apply_under_rules(df_under: pd.DataFrame) -> pd.DataFrame:
            if df_under is None or df_under.empty:
                return df_under

            # Clean out legacy UNDER trap/allow columns so downstream tiering cannot
            # react to removed OU25 UNDER side-logic.
            for _legacy_col in ("__under_allow_boost", "__ou25_under_11_trap"):
                if _legacy_col in df_under.columns:
                    try:
                        df_under = df_under.drop(columns=[_legacy_col])
                    except Exception:
                        pass

            # Model probability floor: p_model >= max(ou_under_pmin_floor, implied_used - tol_ou_under_f)
            league_series = df_under.get("league", pd.Series("", index=df_under.index))
            _imp_used = df_under.get("bookie_implied_used", df_under.get("bookie_implied"))
            _imp_used = pd.to_numeric(_imp_used, errors="coerce")
            _pm = pd.to_numeric(df_under.get("model_p_for_bookie"), errors="coerce")

            _floor = np.maximum(float(ou_under_pmin_floor), _imp_used.fillna(0.0) - float(tol_ou_under_f))
            if isinstance(_ou_audit, dict):
                _ou_audit["ou25_under_model_p_missing"] = int(_pm.isna().sum())
                if bool(_pm.isna().any()):
                    _ou_audit_add_league_counts("ou25_under_model_p_missing", league_series, _pm.isna())
            _pre_under_floor = int(len(df_under))
            df_under = df_under.loc[_pm.fillna(-1e9) >= _floor].copy()
            if isinstance(_ou_audit, dict):
                _ou_audit["ou25_under_model_floor_fail"] = int(_pre_under_floor - len(df_under))
                _ou_audit_add_league_counts("ou25_under_model_floor_fail", league_series, _pm.fillna(-1e9) < _floor)
            if debug:
                print(f"[deploy_rulebook] OU25(UNDER) after model floor n={len(df_under)}")

            # Structural confirmation (UNDERS): use under25_rate + goaliness_avg when available
            have_under_rates = ("under25_rate_5_home" in df_under.columns) and ("under25_rate_5_away" in df_under.columns)
            have_goal_avg = ("goaliness_avg_5_home" in df_under.columns) and ("goaliness_avg_5_away" in df_under.columns)
            have_xg_roll = ("xg_for_avg_5_home" in df_under.columns) and ("xg_for_avg_5_away" in df_under.columns)

            if have_under_rates or have_goal_avg or have_xg_roll:
                pass_rates = pd.Series(False, index=df_under.index)
                pass_goal = pd.Series(False, index=df_under.index)
                pass_xg = pd.Series(False, index=df_under.index)

                if have_under_rates:
                    r_h = pd.to_numeric(df_under["under25_rate_5_home"], errors="coerce")
                    r_a = pd.to_numeric(df_under["under25_rate_5_away"], errors="coerce")
                    pass_rates = ((r_h >= ou_under_rate_min) & (r_a >= ou_under_rate_min)).fillna(False)

                if have_goal_avg:
                    g_h = pd.to_numeric(df_under["goaliness_avg_5_home"], errors="coerce")
                    g_a = pd.to_numeric(df_under["goaliness_avg_5_away"], errors="coerce")
                    pass_goal = ((((g_h + g_a) / 2.0) <= ou_under_goaliness_max)).fillna(False)

                if have_xg_roll:
                    xh = pd.to_numeric(df_under["xg_for_avg_5_home"], errors="coerce")
                    xa = pd.to_numeric(df_under["xg_for_avg_5_away"], errors="coerce")
                    pass_xg = (((xh + xa) <= ou_under_xgsum_max)).fillna(False)

                m_struct = pass_rates | (pass_goal & pass_xg)
                if isinstance(_ou_audit, dict):
                    rates_missing = (
                        pd.Series(True, index=df_under.index)
                        if not have_under_rates
                        else (r_h.isna() & r_a.isna())
                    )
                    goal_missing = (
                        pd.Series(True, index=df_under.index)
                        if not have_goal_avg
                        else (g_h.isna() & g_a.isna())
                    )
                    xg_missing = (
                        pd.Series(True, index=df_under.index)
                        if not have_xg_roll
                        else (xh.isna() & xa.isna())
                    )
                    struct_inputs_missing = rates_missing & goal_missing & xg_missing
                    _ou_audit["ou25_under_struct_inputs_missing"] = int(struct_inputs_missing.sum())
                    if bool(struct_inputs_missing.any()):
                        _ou_audit_add_league_counts(
                            "ou25_under_struct_inputs_missing",
                            df_under.get("league", pd.Series("", index=df_under.index)),
                            struct_inputs_missing,
                        )

                # Debug: show which sub-conditions are passing for UNDER struct
                if debug:
                    try:
                        keep_mask = m_struct.fillna(False)
                        dropped_mask = ~keep_mask

                        print(
                            "[deploy_rulebook] OU25(UNDER) rate/goal/xg struct counts:",
                            {
                                "n_in": int(len(df_under)),
                                "pass_rates": int(pass_rates.sum()),
                                "pass_goal": int(pass_goal.sum()),
                                "pass_xg": int(pass_xg.sum()),
                                "pass_any": int(keep_mask.sum()),
                                "dropped": int(dropped_mask.sum()),
                                "have_rates": bool(have_under_rates),
                                "have_goal": bool(have_goal_avg),
                                "have_xg": bool(have_xg_roll),
                                "ou_under_rate_min": float(ou_under_rate_min),
                                "ou_under_goaliness_max": float(ou_under_goaliness_max),
                                "ou_under_xgsum_max": float(ou_under_xgsum_max),
                            },
                        )

                        cols_dbg = [c for c in (
                            "league","fixture_key","home_team_name","away_team_name","bookie_pick","bookie_od","model_p_for_bookie",
                            "under25_rate_5_home","under25_rate_5_away","goaliness_avg_5_home","goaliness_avg_5_away",
                            "xg_for_avg_5_home","xg_for_avg_5_away","bookie_lambda_total_fit","exp_goals_sum"
                        ) if c in df_under.columns]

                        if cols_dbg and bool(dropped_mask.any()):
                            print("[deploy_rulebook] OU25(UNDER) struct dropped sample:")
                            print(df_under.loc[dropped_mask, cols_dbg].head(10).to_string(index=False))

                        if cols_dbg and bool(keep_mask.any()):
                            print("[deploy_rulebook] OU25(UNDER) struct kept sample:")
                            print(df_under.loc[keep_mask, cols_dbg].head(10).to_string(index=False))
                    except Exception:
                        pass

            _pre_struct = int(len(df_under))
            df_under = df_under.loc[m_struct.fillna(False)].copy()
            if isinstance(_ou_audit, dict):
                _ou_audit["ou25_under_struct_fail"] = int(_pre_struct - len(df_under))
                _ou_audit_add_league_counts("ou25_under_struct_fail", df_under.get("league", pd.Series("", index=df_under.index)), ~m_struct.fillna(False))
            if debug:
                print(f"[deploy_rulebook] OU25(UNDER) after rate/goaliness struct n={len(df_under)}")

            # Optional H2H confirmation for UNDER
            if ou_under_h2h_max is not None and ("h2h_n" in df_under.columns) and ("h2h_over25_rate" in df_under.columns):
                hn = pd.to_numeric(df_under["h2h_n"], errors="coerce")
                hr = pd.to_numeric(df_under["h2h_over25_rate"], errors="coerce")
                m_h2h = (hn < float(h2h_min_n)) | (hr <= float(ou_under_h2h_max))
                df_under = df_under[m_h2h.fillna(False)].copy()
                if debug:
                    print(f"[deploy_rulebook] OU25(UNDER) after H2H gate n={len(df_under)}")

            # Low-goaliness confirmation (UNDERS): keep if ANY low-goaliness signal passes
            _low_conds = []
            missing_low = pd.Series(True, index=df_under.index)

            if "average_goals_per_match_pre_match" in df_under.columns:
                _avg_g = pd.to_numeric(df_under["average_goals_per_match_pre_match"], errors="coerce")
                _low_conds.append(_avg_g <= 2.6)
                missing_low = missing_low & _avg_g.isna()

            if "xg_sum_pre_match" in df_under.columns:
                _xg_sum = pd.to_numeric(df_under["xg_sum_pre_match"], errors="coerce")
                _low_conds.append(_xg_sum <= 2.4)
                missing_low = missing_low & _xg_sum.isna()

            if "over_25_percentage_pre_match" in df_under.columns:
                _o25 = pd.to_numeric(df_under["over_25_percentage_pre_match"], errors="coerce")
                _o25 = _o25.where(_o25 <= 1.0, _o25 / 100.0)
                _low_conds.append(_o25 <= 0.52)
                missing_low = missing_low & _o25.isna()

            if "bookie_lambda_total_fit" in df_under.columns:
                _lam2 = pd.to_numeric(df_under["bookie_lambda_total_fit"], errors="coerce")
                _low_conds.append(_lam2 <= 2.6)
                missing_low = missing_low & _lam2.isna()

            if _low_conds:
                _ok_low = _low_conds[0]
                for _c in _low_conds[1:]:
                    _ok_low = _ok_low | _c
            _pre_low = int(len(df_under))
            df_under = df_under[_ok_low.fillna(False)].copy()
            if isinstance(_ou_audit, dict):
                _ou_audit["ou25_under_low_goal_fail"] = int(_pre_low - len(df_under))
                _ou_audit_add_league_counts("ou25_under_low_goal_fail", df_under.get("league", pd.Series("", index=df_under.index)), ~_ok_low.fillna(False))
                _ou_audit["ou25_under_low_goal_inputs_missing"] = int(missing_low.sum())
                if bool(missing_low.any()):
                    _ou_audit_add_league_counts(
                        "ou25_under_low_goal_inputs_missing",
                        df_under.get("league", pd.Series("", index=df_under.index)),
                        missing_low,
                    )

            if debug:
                print(f"[deploy_rulebook] OU25(UNDER) after low-goaliness n={len(df_under)}")

            return df_under

        ou_over = _apply_over_rules(ou_over)
        ou_under = _apply_under_rules(ou_under)

        # Recombine OU25 (keep any 'other' rows only if you want them; default keeps them)
        ou = pd.concat([ou_over, ou_under, ou_other], axis=0, ignore_index=True)

        if debug:
            print(f"[deploy_rulebook] OU25 after over/under rules n={len(ou)}")

    # BTTS filter (branch YES vs NO)
    btts = out[out["market"].eq("btts")].copy()
    if not btts.empty:
        if debug:
            print(f"[deploy_rulebook] BTTS start n={len(btts)}")

        btts = btts[agree.loc[btts.index]].copy()
        if debug:
            print(f"[deploy_rulebook] BTTS after agree n={len(btts)}")
        if isinstance(params.get("_btts_gate_audit"), dict):
            params["_btts_gate_audit"]["btts_input"] = int(len(btts))

        _pick_b = btts.get("bookie_pick", pd.Series("YES", index=btts.index))
        _pick_b = _pick_b.astype("string").fillna("").str.upper().str.strip()

        # ---------------------------------------------------------
        # BTTS runtime signal:
        #   - aligned rows keep side-aware label
        #   - contrarian rows are downgraded to NEUTRAL
        # Apply this on the full BTTS frame first so downstream live +
        # observe/shadow outputs all carry the same stamped fields.
        # ---------------------------------------------------------
        _sel_all = btts.get("selection", pd.Series("", index=btts.index)).astype("string").fillna("").str.upper().str.strip()
        _top_all = btts.get("model_top_pick", pd.Series("", index=btts.index)).astype("string").fillna("").str.upper().str.strip()

        _side_sig_all = btts.get("signal_btts_side", pd.Series(pd.NA, index=btts.index)).astype("string")
        _base_sig_all = btts.get("signal_btts", pd.Series("", index=btts.index)).astype("string").fillna("").str.upper().str.strip()

        _aligned_all = _sel_all.eq(_top_all)
        _runtime_all = _side_sig_all.fillna(_base_sig_all).astype("string").fillna("").str.upper().str.strip()
        _runtime_all = _runtime_all.where(_aligned_all, "NEUTRAL")

        btts["btts_alignment"] = np.where(_aligned_all, "ALIGNED", "CONTRARIAN")
        btts["signal_btts_runtime"] = _runtime_all

        # Keep canonical runtime signal in signal_btts for deploy logic.
        btts["signal_btts"] = btts["signal_btts_runtime"]

        # Refresh splits from stamped BTTS frame so all child frames inherit
        # alignment/runtime columns and the canonical runtime signal.
        b_yes = btts[_pick_b.eq("YES")].copy()
        b_no  = btts[_pick_b.eq("NO")].copy()
        b_other = btts[~_pick_b.isin(["YES", "NO"])].copy()
        # ---------------------------------------------------------
        # BTTS runtime signal:
        #   - aligned rows keep side-aware label
        #   - contrarian rows are downgraded to NEUTRAL
        # ---------------------------------------------------------
        for _df_part in (b_yes, b_no, b_other):
            if _df_part is None or _df_part.empty:
                continue

            _sel = _df_part.get("selection", pd.Series("", index=_df_part.index)).astype("string").fillna("").str.upper().str.strip()
            _top = _df_part.get("model_top_pick", pd.Series("", index=_df_part.index)).astype("string").fillna("").str.upper().str.strip()

            _side_sig = _df_part.get("signal_btts_side", pd.Series(pd.NA, index=_df_part.index)).astype("string")
            _base_sig = _df_part.get("signal_btts", pd.Series("", index=_df_part.index)).astype("string").fillna("").str.upper().str.strip()

            _aligned = _sel.eq(_top)
            _runtime = _side_sig.fillna(_base_sig).astype("string").fillna("").str.upper().str.strip()
            _runtime = _runtime.where(_aligned, "NEUTRAL")

            _df_part["btts_alignment"] = np.where(_aligned, "ALIGNED", "CONTRARIAN")
            _df_part["signal_btts_runtime"] = _runtime

        if debug:
            print(f"[deploy_rulebook] BTTS split yes={len(b_yes)} no={len(b_no)} other={len(b_other)}")
            if debug:
                try:
                    if not b_yes.empty:
                        cols_yes = [c for c in (
                            "league", "fixture_key", "home_team_name", "away_team_name",
                            "bookie_pick", "selection", "model_top_pick", "btts_alignment",
                            "signal_btts", "signal_btts_side", "signal_btts_runtime", "model_p_for_bookie",
                            "bookie_implied", "bookie_implied_used", "gap_used",
                            "p_home_fts", "p_away_fts", "p00_est", "exp_goals_sum",
                            "reason_codes", "deterministic_veto_reason"
                        ) if c in b_yes.columns]
                        print("[deploy_rulebook] BTTS(YES) signal_btts counts:",
                            b_yes.get("signal_btts", pd.Series("", index=b_yes.index)).astype(str).value_counts(dropna=False).to_dict())
                        if cols_yes:
                            print("[deploy_rulebook] BTTS(YES) pre strong-label sample:")
                            print(b_yes[cols_yes].head(10).to_string(index=False))

                    if not b_no.empty:
                        cols_no = [c for c in (
                            "league", "fixture_key", "home_team_name", "away_team_name",
                            "bookie_pick", "selection", "model_top_pick", "btts_alignment",
                            "signal_btts", "signal_btts_side", "signal_btts_runtime", "model_p_for_bookie",
                            "bookie_implied", "bookie_implied_used", "gap_used",
                            "p_home_fts", "p_away_fts", "p00_est", "exp_goals_sum",
                            "reason_codes", "deterministic_veto_reason"
                        ) if c in b_no.columns]
                        print("[deploy_rulebook] BTTS(NO) signal_btts counts:",
                            b_no.get("signal_btts", pd.Series("", index=b_no.index)).astype(str).value_counts(dropna=False).to_dict())
                        if cols_no:
                            print("[deploy_rulebook] BTTS(NO) pre strong-label sample:")
                            print(b_no[cols_no].head(10).to_string(index=False))
                except Exception as e:
                    print(f"[deploy_rulebook] BTTS pre strong-label debug failed: {e}")

        # ---------------------------------------------------------
        # Optional BTTS label tightening (signal_btts allowlist)
        # ---------------------------------------------------------
        def _parse_labels(x: object) -> set[str]:
            txt = str(x or "").strip()
            if not txt:
                return set()
            return {t.strip().upper() for t in txt.split(",") if t.strip()}

        yes_allow = _parse_labels(params.get("btts_yes_labels", ""))
        no_allow  = _parse_labels(params.get("btts_no_labels", ""))

        def _apply_label_allow(df_part: pd.DataFrame, allow: set[str], side: str) -> pd.DataFrame:
            if df_part is None or df_part.empty or not allow:
                return df_part
            sig = df_part.get("signal_btts_runtime", df_part.get("signal_btts", pd.Series("", index=df_part.index)))
            sig = sig.astype("string").fillna("").str.strip().str.upper()
            before_n = len(df_part)
            df_part = df_part[sig.isin(list(allow))].copy()
            if debug:
                try:
                    print(f"[deploy_rulebook] BTTS({side}) label_allow={sorted(list(allow))} kept {len(df_part)}/{before_n}")
                    print(f"[deploy_rulebook] BTTS({side}) signal_btts counts:", sig.value_counts(dropna=False).to_dict())
                except Exception:
                    pass
            return df_part

        b_yes = _apply_label_allow(b_yes, yes_allow, "YES")
        b_no  = _apply_label_allow(b_no,  no_allow,  "NO")
        # Optional side enablement (YES-only / NO-only)
        btts_enable_yes = bool(params.get("btts_enable_yes", True))
        btts_enable_no = bool(params.get("btts_enable_no", True))

        if not btts_enable_yes:
            b_yes = b_yes.iloc[0:0].copy()
        if not btts_enable_no:
            b_no = b_no.iloc[0:0].copy()

        if debug:
            print(f"[deploy_rulebook] BTTS enabled yes={btts_enable_yes} no={btts_enable_no} -> yes={len(b_yes)} no={len(b_no)}")

        # Optional per-side pmin floors (no CLI flags yet; override via params dict if desired)
        btts_yes_pmin_floor = float(params.get("btts_yes_pmin_floor", 0.53))
        btts_no_pmin_floor  = float(params.get("btts_no_pmin_floor",  0.52))

        # Optional BTTS YES/NO rate-gate thresholds (used only if rate cols exist)
        btts_yes_scored_min = float(params.get("btts_yes_scored_min", 0.60))
        btts_yes_cs_max = float(params.get("btts_yes_cs_max", 0.40))
        btts_no_cs_min = float(params.get("btts_no_cs_min", 0.35))
        btts_no_scored_max = float(params.get("btts_no_scored_max", 0.70))

        btts_yes_conceded_min = float(params.get("btts_yes_conceded_min", 0.60))
        btts_yes_bttsrate_min = float(params.get("btts_yes_bttsrate_min", 0.50))
        btts_no_conceded_max = float(params.get("btts_no_conceded_max", 0.55))
        btts_no_bttsrate_max = float(params.get("btts_no_bttsrate_max", 0.55))
        # BTTS rolling xG knobs
        btts_yes_xgfor_min = float(params.get("btts_yes_xgfor_min", 1.10))
        btts_yes_xgagainst_min = float(params.get("btts_yes_xgagainst_min", 1.00))
        btts_no_xgfor_max = float(params.get("btts_no_xgfor_max", 1.00))
        btts_no_xgagainst_max = float(params.get("btts_no_xgagainst_max", 1.00))
        # BTTS structural GE/FTS knobs (used only if GE heads exist)
        btts_yes_ge2_min = float(params.get("btts_yes_ge2_min", 0.22))

        btts_no_fts_min = float(params.get("btts_no_fts_min", 0.50))
        btts_no_ge2_sum_max = float(params.get("btts_no_ge2_sum_max", 0.95))
        btts_no_use_low_total_confirm = bool(params.get("btts_no_use_low_total_confirm", False))
        btts_no_low_total_max = float(params.get("btts_no_low_total_max", 2.55))
        btts_no_p00_min = float(params.get("btts_no_p00_min", 0.08))

        h2h_min_n = int(params.get("h2h_min_n", 3))
        btts_yes_h2h_min = params.get("btts_yes_h2h_min", None)
        btts_no_h2h_max = params.get("btts_no_h2h_max", None)

        def _apply_btts_yes_rules(df_yes: pd.DataFrame) -> pd.DataFrame:
            """BTTS YES: avoid ultra-short YES, require model floor, and require confirmation gate."""
            if df_yes is None or df_yes.empty:
                return df_yes

            sig = df_yes.get(
                "signal_btts_runtime",
                df_yes.get("signal_btts", pd.Series("", index=df_yes.index)),
            ).astype("string").fillna("").str.strip().str.upper()
            league = df_yes.get(
                "league",
                pd.Series("", index=df_yes.index),
            ).astype("string").fillna("").str.strip()

            _audit = params.get("_btts_gate_audit") if isinstance(params, dict) else None
            if isinstance(_audit, dict):
                def _audit_add_league_counts(gate: str, league_series: pd.Series, mask: pd.Series) -> None:
                    if not isinstance(_audit, dict):
                        return
                    if gate not in _audit["by_league"]:
                        _audit["by_league"][gate] = {}

                    league_series = pd.Series(league_series, copy=False)
                    mask_series = pd.Series(mask, index=getattr(mask, "index", league_series.index), copy=False)
                    mask_series = mask_series.reindex(league_series.index, fill_value=False).fillna(False).astype(bool)

                    league_counts = (
                        league_series.loc[mask_series]
                        .astype("string")
                        .fillna("")
                        .replace("", "UNKNOWN")
                        .value_counts()
                    )
                    for lg, cnt in league_counts.items():
                        _audit["by_league"][gate][str(lg)] = int(
                            _audit["by_league"][gate].get(str(lg), 0)
                        ) + int(cnt)

                _audit["btts_yes_input"] = int(len(df_yes))
                _audit["btts_yes_strong_input"] = int(sig.eq("STRONG_YES").sum())
                _audit["btts_yes_very_strong_input"] = int(sig.eq("VERY_STRONG_YES").sum())
                _audit["btts_yes_very_strong_brazil_input"] = int(
                    (sig.eq("VERY_STRONG_YES") & league.eq("Brazil Serie A")).sum()
                )
                _audit["btts_yes_weak_input"] = int(sig.eq("WEAK_YES").sum())
                if "_btts_yes_input_by_league" not in _audit:
                    _audit["_btts_yes_input_by_league"] = {}
                _audit_add_league_counts(
                    "btts_yes_input",
                    league,
                    pd.Series(True, index=league.index),
                )
                # Pre-label missing-feature audit on full BTTS YES pool
                ge2_h_pre = pd.to_numeric(
                    df_yes.get("home_ge2_confidence", pd.Series(np.nan, index=df_yes.index)),
                    errors="coerce",
                )
                ge2_a_pre = pd.to_numeric(
                    df_yes.get("away_ge2_confidence", pd.Series(np.nan, index=df_yes.index)),
                    errors="coerce",
                )
                ge2_missing_pre = ge2_h_pre.isna() | ge2_a_pre.isna()

                fts_h_pre = pd.to_numeric(
                    df_yes.get("p_home_fts", pd.Series(np.nan, index=df_yes.index)),
                    errors="coerce",
                )
                fts_a_pre = pd.to_numeric(
                    df_yes.get("p_away_fts", pd.Series(np.nan, index=df_yes.index)),
                    errors="coerce",
                )
                fts_missing_pre = fts_h_pre.isna() | fts_a_pre.isna()

                cs_h_pre = pd.to_numeric(
                    df_yes.get("cs_home", pd.Series(np.nan, index=df_yes.index)),
                    errors="coerce",
                )
                cs_a_pre = pd.to_numeric(
                    df_yes.get("cs_away", pd.Series(np.nan, index=df_yes.index)),
                    errors="coerce",
                )
                cs_missing_pre = cs_h_pre.isna() | cs_a_pre.isna()

                _audit["btts_yes_ge2_missing_prelabel"] = int(ge2_missing_pre.sum())
                _audit["btts_yes_fts_missing_prelabel"] = int(fts_missing_pre.sum())
                _audit["btts_yes_cs_missing_prelabel"] = int(cs_missing_pre.sum())
                if bool(ge2_missing_pre.any()):
                    _audit_add_league_counts("btts_yes_ge2_missing_prelabel", league, ge2_missing_pre)
                if bool(fts_missing_pre.any()):
                    _audit_add_league_counts("btts_yes_fts_missing_prelabel", league, fts_missing_pre)
                if bool(cs_missing_pre.any()):
                    _audit_add_league_counts("btts_yes_cs_missing_prelabel", league, cs_missing_pre)
                # Also persist a direct per-league yes-input map for writer fallback
                if isinstance(_audit.get("_btts_yes_input_by_league"), dict):
                    lc = league.astype("string").fillna("").replace("", "UNKNOWN").value_counts()
                    for lg, cnt in lc.items():
                        _audit["_btts_yes_input_by_league"][str(lg)] = int(
                            _audit["_btts_yes_input_by_league"].get(str(lg), 0)
                        ) + int(cnt)
                if bool(sig.eq("WEAK_YES").any()):
                    _audit_add_league_counts(
                        "btts_yes_weak_input",
                        league,
                        sig.eq("WEAK_YES"),
                    )

            allow_strong = sig.eq("STRONG_YES")
            allow_very_strong_non_brazil = sig.eq("VERY_STRONG_YES") & (~league.eq("Brazil Serie A"))
            keep_live_labels = allow_strong | allow_very_strong_non_brazil
            label_pass = keep_live_labels.fillna(False)
            brazil_block_mask = sig.eq("VERY_STRONG_YES") & league.eq("Brazil Serie A")

            if isinstance(_audit, dict):
                _pre_label = int(len(df_yes))
                _audit["btts_yes_label_ok"] = int(keep_live_labels.sum())
                _audit["btts_yes_brazil_block"] = int(brazil_block_mask.sum())
                _audit["btts_yes_label_fail"] = int(_pre_label - keep_live_labels.sum())
                label_fail_mask = ~keep_live_labels
                if bool(label_fail_mask.any()):
                    _audit_add_league_counts("btts_yes_label_fail", league, label_fail_mask)
                if bool(brazil_block_mask.any()):
                    _audit_add_league_counts("btts_yes_brazil_block", league, brazil_block_mask)

            if debug:
                try:
                    print(
                        "[deploy_rulebook] BTTS(YES) live label gate:",
                        {
                            "rows_after_gate": int(label_pass.sum()),
                            "strong_yes_kept": int(allow_strong.sum()),
                            "very_strong_non_brazil_kept": int(allow_very_strong_non_brazil.sum()),
                            "very_strong_brazil_blocked": int(brazil_block_mask.sum()),
                            "weak_yes_blocked": int(sig.eq("WEAK_YES").sum()),
                        },
                    )
                except Exception:
                    pass

            if not bool(label_pass.any()):
                return df_yes.iloc[0:0].copy()

            df_yes = _stamp_btts_yes_live_features(df_yes)
            df_yes = _stamp_btts_yes_double_blank_live_features(df_yes)

            cs_home = pd.to_numeric(
                df_yes.get("cs_home", pd.Series(np.nan, index=df_yes.index)),
                errors="coerce",
            )
            cs_away = pd.to_numeric(
                df_yes.get("cs_away", pd.Series(np.nan, index=df_yes.index)),
                errors="coerce",
            )
            cs_max = pd.concat([cs_home, cs_away], axis=1).max(axis=1)

            p00_est = pd.to_numeric(
                df_yes.get("p00_est", pd.Series(np.nan, index=df_yes.index)),
                errors="coerce",
            )
            exp_goals_sum = pd.to_numeric(
                df_yes.get("exp_goals_sum", pd.Series(np.nan, index=df_yes.index)),
                errors="coerce",
            )
            cs00_top3_mass = pd.to_numeric(
                df_yes.get("cs00_top3_mass", pd.Series(np.nan, index=df_yes.index)),
                errors="coerce",
            )
            btts_top3_mass = pd.to_numeric(
                df_yes.get("btts_top3_mass", pd.Series(np.nan, index=df_yes.index)),
                errors="coerce",
            )
            top3_any_00 = pd.to_numeric(
                df_yes.get("top3_any_00", pd.Series(np.nan, index=df_yes.index)),
                errors="coerce",
            )
            fts_sum = pd.to_numeric(
                df_yes.get("fts_sum", pd.Series(np.nan, index=df_yes.index)),
                errors="coerce",
            )
            cs_sum = pd.to_numeric(
                df_yes.get("cs_sum", pd.Series(np.nan, index=df_yes.index)),
                errors="coerce",
            )
            double_blank_shadow = pd.to_numeric(
                df_yes.get("btts_yes_double_blank_shadow_block", pd.Series(0, index=df_yes.index)),
                errors="coerce",
            ).fillna(0)

            df_yes["cs_home"] = cs_home
            df_yes["cs_away"] = cs_away
            df_yes["cs_max"] = cs_max
            df_yes["cs00_top3_mass"] = cs00_top3_mass
            df_yes["btts_top3_mass"] = btts_top3_mass
            df_yes["top3_any_00"] = top3_any_00
            df_yes["fts_sum"] = fts_sum
            df_yes["cs_sum"] = cs_sum
            df_yes["btts_yes_double_blank_shadow_block"] = double_blank_shadow

            df_yes["btts_yes_cs_shadow_block"] = (
                cs_max.notna() & (cs_max > float(btts_yes_cs_max))
            ).astype(int)

            if isinstance(_audit, dict):
                _audit["btts_yes_cs_shadow_flag"] = int(df_yes["btts_yes_cs_shadow_block"].sum())
                _audit["btts_yes_double_blank_flag"] = int(double_blank_shadow.ge(1).sum())
                if "btts_yes_cs_shadow_block" in df_yes.columns:
                    cs_shadow_mask = df_yes["btts_yes_cs_shadow_block"].astype(int).eq(1)
                    if bool(cs_shadow_mask.any()):
                        _audit_add_league_counts("btts_yes_cs_shadow_flag", league, cs_shadow_mask)
                dbl_mask = double_blank_shadow.ge(1)
                if bool(dbl_mask.any()):
                    _audit_add_league_counts("btts_yes_double_blank_flag", league, dbl_mask)

            if debug:
                try:
                    print(
                        "[deploy_rulebook] BTTS(YES) cs_max shadow:",
                        {
                            "rows": int(len(df_yes)),
                            "shadow_blocked": int(df_yes["btts_yes_cs_shadow_block"].sum()),
                            "btts_yes_cs_max": float(btts_yes_cs_max),
                            "double_blank_shadow_blocked": int(df_yes["btts_yes_double_blank_shadow_block"].fillna(0).sum()),
                            "p00_est_ge_010": int(p00_est.ge(0.10).fillna(False).sum()),
                            "top3_any_00": int(top3_any_00.ge(1).fillna(False).sum()),
                            "cs00_top3_mass_ge_012": int(cs00_top3_mass.ge(0.12).fillna(False).sum()),
                            "fts_sum_ge_062": int(fts_sum.ge(0.62).fillna(False).sum()),
                            "cs_sum_ge_062": int(cs_sum.ge(0.62).fillna(False).sum()),
                            "exp_goals_sum_le_220": int(exp_goals_sum.le(2.20).fillna(False).sum()),
                            "btts_top3_mass_le_018": int(btts_top3_mass.le(0.18).fillna(False).sum()),
                        },
                    )
                except Exception:
                    pass

            # -----------------------------------------------------------------
            # Gate pass flags (do not drop until final decision)
            # -----------------------------------------------------------------
            sig_local = sig.astype("string").fillna("").str.strip().str.upper()
            is_strong_only = sig_local.eq("STRONG_YES")

            # GE2 gate (fail-open on missing, and on wipe)
            have_ge2 = ("home_ge2_confidence" in df_yes.columns) and ("away_ge2_confidence" in df_yes.columns)
            ge2_pass = pd.Series(True, index=df_yes.index, dtype="bool")
            ge2_min = pd.Series(np.nan, index=df_yes.index, dtype="float64")
            ge2_base_floor = _league_override_threshold_series(
                league,
                BTTS_YES_GE2_LEAGUE_OVERRIDES,
                "base_min",
                float(btts_yes_ge2_min),
            )
            strong_ge2_floor = _league_override_threshold_series(
                league,
                BTTS_YES_GE2_LEAGUE_OVERRIDES,
                "strong_min",
                max(float(btts_yes_ge2_min), 0.30),
            )
            if have_ge2:
                ge2h = pd.to_numeric(df_yes["home_ge2_confidence"], errors="coerce")
                ge2a = pd.to_numeric(df_yes["away_ge2_confidence"], errors="coerce")
                ge2_min = pd.concat([ge2h, ge2a], axis=1).min(axis=1)
                ge2_floor = ge2_base_floor.copy()
                ge2_floor.loc[is_strong_only] = strong_ge2_floor
                ge2_pass = ge2_min.isna() | (ge2_min >= ge2_floor)
                if int(label_pass.sum()) > 0 and int((label_pass & ge2_pass.fillna(True)).sum()) == 0:
                    ge2_pass = pd.Series(True, index=df_yes.index, dtype="bool")
                    if debug:
                        print("[deploy_rulebook] BTTS(YES) GE2 struct wiped all rows; skipping gate (fail-open)")

            if isinstance(_audit, dict):
                ge2_fail_mask = label_pass & (~ge2_pass.fillna(True))
                _audit["btts_yes_ge2_fail"] = int(ge2_fail_mask.sum())
                if bool(ge2_fail_mask.any()):
                    _audit_add_league_counts("btts_yes_ge2_fail", league, ge2_fail_mask)

            if debug:
                try:
                    print(
                        "[deploy_rulebook] BTTS(YES) GE2 struct:",
                        {
                            "n_in": int(label_pass.sum()),
                            "kept": int((label_pass & ge2_pass.fillna(True)).sum()),
                            "dropped": int((label_pass & (~ge2_pass.fillna(True))).sum()),
                            "btts_yes_ge2_min": float(btts_yes_ge2_min),
                            "strong_ge2_floor_min": float(pd.to_numeric(strong_ge2_floor, errors="coerce").min()),
                            "strong_ge2_floor_max": float(pd.to_numeric(strong_ge2_floor, errors="coerce").max()),
                            "strong_rows": int(is_strong_only.sum()),
                            "strong_rows_below_floor": int((is_strong_only & ge2_min.lt(strong_ge2_floor)).fillna(False).sum()),
                        },
                    )
                except Exception:
                    pass

            # Model probability floor
            _imp_used = _to_num(df_yes.get("bookie_implied_used", df_yes.get("bookie_implied")))
            _pm = _to_num(df_yes.get("model_p_for_bookie"))
            _floor = np.maximum(float(btts_yes_pmin_floor), _imp_used.fillna(0.0) - float(tol_btts_f))
            model_floor_pass = _pm.fillna(-1e9) >= _floor
            if isinstance(_audit, dict):
                mf_fail_mask = label_pass & ge2_pass.fillna(True) & (~model_floor_pass.fillna(False))
                _audit["btts_yes_model_floor_fail"] = int(mf_fail_mask.sum())
                if bool(mf_fail_mask.any()):
                    _audit_add_league_counts("btts_yes_model_floor_fail", league, mf_fail_mask)
            if debug:
                print(
                    "[deploy_rulebook] BTTS(YES) after model floor:",
                    {
                        "kept": int((label_pass & ge2_pass.fillna(True) & model_floor_pass.fillna(False)).sum()),
                        "dropped": int((label_pass & ge2_pass.fillna(True) & (~model_floor_pass.fillna(False))).sum()),
                    },
                )

            # FTS veto
            fts_pass = pd.Series(True, index=df_yes.index, dtype="bool")
            if ("p_home_fts" in df_yes.columns) and ("p_away_fts" in df_yes.columns):
                ph = pd.to_numeric(df_yes["p_home_fts"], errors="coerce")
                pa = pd.to_numeric(df_yes["p_away_fts"], errors="coerce")
                fts_max_local = pd.concat([ph, pa], axis=1).max(axis=1)

                strong_fts_cap = min(float(fts_yes_max), 0.38)
                fts_cap = pd.Series(float(fts_yes_max), index=df_yes.index, dtype="float64")
                fts_cap.loc[is_strong_only] = strong_fts_cap
                fts_pass = fts_max_local.isna() | (fts_max_local <= fts_cap)

                if debug:
                    print(
                        "[deploy_rulebook] BTTS(YES) after FTS veto:",
                        {
                            "kept": int((label_pass & ge2_pass.fillna(True) & model_floor_pass.fillna(False) & fts_pass.fillna(True)).sum()),
                            "dropped": int((label_pass & ge2_pass.fillna(True) & model_floor_pass.fillna(False) & (~fts_pass.fillna(True))).sum()),
                            "fts_yes_max": float(fts_yes_max),
                            "strong_fts_cap": float(strong_fts_cap),
                            "strong_rows": int(is_strong_only.sum()),
                            "strong_rows_above_cap": int((is_strong_only & fts_max_local.gt(strong_fts_cap)).fillna(False).sum()),
                        },
                    )

            if isinstance(_audit, dict):
                fts_fail_mask = label_pass & ge2_pass.fillna(True) & model_floor_pass.fillna(False) & (~fts_pass.fillna(True))
                _audit["btts_yes_fts_fail"] = int(fts_fail_mask.sum())
                if bool(fts_fail_mask.any()):
                    _audit_add_league_counts("btts_yes_fts_fail", league, fts_fail_mask)

            # STRONG_YES-only clean-sheet / shutout suppression guard.
            cs_pass = pd.Series(True, index=df_yes.index, dtype="bool")
            if ("cs_home" in df_yes.columns) and ("cs_away" in df_yes.columns):
                cs_home_local = pd.to_numeric(df_yes["cs_home"], errors="coerce")
                cs_away_local = pd.to_numeric(df_yes["cs_away"], errors="coerce")
                cs_max_local = pd.concat([cs_home_local, cs_away_local], axis=1).max(axis=1)
                strong_cs_cap = min(float(btts_yes_cs_max), 0.44)
                cs_pass = (~is_strong_only) | cs_max_local.isna() | (cs_max_local <= strong_cs_cap)

                if debug:
                    print(
                        "[deploy_rulebook] BTTS(YES) STRONG cs_max veto:",
                        {
                            "kept": int((label_pass & ge2_pass.fillna(True) & model_floor_pass.fillna(False) & fts_pass.fillna(True) & cs_pass.fillna(True)).sum()),
                            "dropped": int((label_pass & ge2_pass.fillna(True) & model_floor_pass.fillna(False) & fts_pass.fillna(True) & (~cs_pass.fillna(True))).sum()),
                            "strong_cs_cap": float(strong_cs_cap),
                            "strong_rows": int(is_strong_only.sum()),
                            "strong_rows_above_cap": int((is_strong_only & cs_max_local.gt(strong_cs_cap)).fillna(False).sum()),
                        },
                    )

            if isinstance(_audit, dict):
                cs_fail_mask = label_pass & ge2_pass.fillna(True) & model_floor_pass.fillna(False) & fts_pass.fillna(True) & (~cs_pass.fillna(True))
                _audit["btts_yes_csmax_fail"] = int(cs_fail_mask.sum())
                if bool(cs_fail_mask.any()):
                    _audit_add_league_counts("btts_yes_csmax_fail", league, cs_fail_mask)

            # STRONG_YES double-blank warning guard.
            double_blank_pass = pd.Series(True, index=df_yes.index, dtype="bool")
            if "btts_yes_double_blank_shadow_block" in df_yes.columns:
                dbl_blank_warn = pd.to_numeric(
                    df_yes.get("btts_yes_double_blank_shadow_block", pd.Series(0, index=df_yes.index)),
                    errors="coerce",
                ).fillna(0).ge(1)

                cs_max_local = pd.to_numeric(
                    df_yes.get("cs_max", pd.Series(np.nan, index=df_yes.index)),
                    errors="coerce",
                )
                btts_top3_mass_local = pd.to_numeric(
                    df_yes.get("btts_top3_mass", pd.Series(np.nan, index=df_yes.index)),
                    errors="coerce",
                )
                p00_local = pd.to_numeric(
                    df_yes.get("p00_est", pd.Series(np.nan, index=df_yes.index)),
                    errors="coerce",
                )
                fts_sum_local = pd.to_numeric(
                    df_yes.get("fts_sum", pd.Series(np.nan, index=df_yes.index)),
                    errors="coerce",
                )

                warning_bad_shape = (
                    dbl_blank_warn
                    & is_strong_only
                    & (
                        (cs_max_local.gt(0.30) & btts_top3_mass_local.lt(0.10))
                        | (p00_local.gt(0.14) & fts_sum_local.gt(0.58))
                    )
                )

                double_blank_pass = ~warning_bad_shape.fillna(False)

                if debug:
                    print(
                        "[deploy_rulebook] BTTS(YES) STRONG double-blank warning guard:",
                        {
                            "kept": int((label_pass & ge2_pass.fillna(True) & model_floor_pass.fillna(False) & fts_pass.fillna(True) & cs_pass.fillna(True) & double_blank_pass.fillna(True)).sum()),
                            "dropped": int((label_pass & ge2_pass.fillna(True) & model_floor_pass.fillna(False) & fts_pass.fillna(True) & cs_pass.fillna(True) & (~double_blank_pass.fillna(True))).sum()),
                            "strong_warning_rows": int((is_strong_only & dbl_blank_warn).sum()),
                            "warning_bad_shape_rows": int(warning_bad_shape.fillna(False).sum()),
                        },
                    )

            if isinstance(_audit, dict):
                dbl_fail_mask = label_pass & ge2_pass.fillna(True) & model_floor_pass.fillna(False) & fts_pass.fillna(True) & cs_pass.fillna(True) & (~double_blank_pass.fillna(True))
                _audit["btts_yes_double_blank_fail"] = int(dbl_fail_mask.sum())
                if bool(dbl_fail_mask.any()):
                    _audit_add_league_counts("btts_yes_double_blank_fail", league, dbl_fail_mask)

            # Confirmation gate (YES)
            have_rate_scored = ("scored_rate_5_home" in df_yes.columns) and ("scored_rate_5_away" in df_yes.columns)
            have_rate_cs = ("clean_sheet_rate_5_home" in df_yes.columns) and ("clean_sheet_rate_5_away" in df_yes.columns)
            confirmation_pass = pd.Series(False, index=df_yes.index, dtype="bool")

            if have_rate_scored and have_rate_cs:
                _sr_h = _to_num(df_yes["scored_rate_5_home"])
                _sr_a = _to_num(df_yes["scored_rate_5_away"])
                scored_ok = (_sr_h >= float(btts_yes_scored_min)) & (_sr_a >= float(btts_yes_scored_min))

                _cs_h = _to_num(df_yes["clean_sheet_rate_5_home"])
                _cs_a = _to_num(df_yes["clean_sheet_rate_5_away"])
                cs_risk = np.maximum(_cs_h, _cs_a)
                cs_ok = (cs_risk <= float(btts_yes_cs_max))

                have_rate_conc = ("conceded_rate_5_home" in df_yes.columns) and ("conceded_rate_5_away" in df_yes.columns)
                have_rate_btts = ("btts_rate_5_home" in df_yes.columns) and ("btts_rate_5_away" in df_yes.columns)

                conc_ok = pd.Series(True, index=df_yes.index)
                if have_rate_conc:
                    c_h = _to_num(df_yes["conceded_rate_5_home"])
                    c_a = _to_num(df_yes["conceded_rate_5_away"])
                    conc_ok = (c_h >= float(btts_yes_conceded_min)) & (c_a >= float(btts_yes_conceded_min))

                btts_ok = pd.Series(True, index=df_yes.index)
                if have_rate_btts:
                    br_h = _to_num(df_yes["btts_rate_5_home"])
                    br_a = _to_num(df_yes["btts_rate_5_away"])
                    btts_ok = (br_h >= float(btts_yes_bttsrate_min)) & (br_a >= float(btts_yes_bttsrate_min))

                xg_ok = pd.Series(True, index=df_yes.index)
                have_xg_for = ("xg_for_avg_5_home" in df_yes.columns) and ("xg_for_avg_5_away" in df_yes.columns)
                have_xg_against = ("xg_against_avg_5_home" in df_yes.columns) and ("xg_against_avg_5_away" in df_yes.columns)
                if have_xg_for:
                    xf_h = pd.to_numeric(df_yes["xg_for_avg_5_home"], errors="coerce")
                    xf_a = pd.to_numeric(df_yes["xg_for_avg_5_away"], errors="coerce")
                    xg_ok = xg_ok & (xf_h >= float(btts_yes_xgfor_min)) & (xf_a >= float(btts_yes_xgfor_min))
                if have_xg_against:
                    xa_h = pd.to_numeric(df_yes["xg_against_avg_5_home"], errors="coerce")
                    xa_a = pd.to_numeric(df_yes["xg_against_avg_5_away"], errors="coerce")
                    xg_ok = xg_ok & (xa_h >= float(btts_yes_xgagainst_min)) & (xa_a >= float(btts_yes_xgagainst_min))

                sig = df_yes.get("signal_btts_runtime", df_yes.get("signal_btts", pd.Series("", index=df_yes.index)))
                sig = sig.astype("string").fillna("").str.strip().str.upper()
                is_strong = sig.isin(["VERY_STRONG_YES", "STRONG_YES"]).fillna(False)

                strict_mask = (scored_ok & cs_ok & conc_ok & btts_ok & xg_ok).fillna(False)
                loose_mask = (((scored_ok & cs_ok) | (conc_ok & btts_ok) | xg_ok)).fillna(False)

                goal_ok = pd.Series(False, index=df_yes.index)
                if "average_goals_per_match_pre_match" in df_yes.columns:
                    goal_ok = goal_ok | (pd.to_numeric(df_yes["average_goals_per_match_pre_match"], errors="coerce") >= 2.6)
                if "xg_sum_pre_match" in df_yes.columns:
                    goal_ok = goal_ok | (pd.to_numeric(df_yes["xg_sum_pre_match"], errors="coerce") >= 2.4)
                if "over_25_percentage_pre_match" in df_yes.columns:
                    _o25 = pd.to_numeric(df_yes["over_25_percentage_pre_match"], errors="coerce")
                    _o25 = _o25.where(_o25 <= 1.0, _o25 / 100.0)
                    goal_ok = goal_ok | (_o25 >= 0.52)
                if "bookie_lambda_total_fit" in df_yes.columns:
                    goal_ok = goal_ok | (pd.to_numeric(df_yes["bookie_lambda_total_fit"], errors="coerce") >= 2.6)

                keep_mask = strict_mask.copy()
                keep_mask.loc[is_strong] = (loose_mask | goal_ok).loc[is_strong].fillna(False)
                confirmation_pass = keep_mask.fillna(False)

                if debug:
                    try:
                        print(
                            f"[deploy_rulebook] BTTS(YES) label-aware gate: STRONG={int(is_strong.sum())} "
                            f"kept_strong={int((keep_mask & is_strong).sum())} kept_total={int(keep_mask.sum())}"
                        )
                    except Exception:
                        pass

            else:
                _conds = []

                if "average_goals_per_match_pre_match" in df_yes.columns:
                    _avg_g = _to_num(df_yes["average_goals_per_match_pre_match"])
                    _conds.append(_avg_g >= 2.6)

                if "xg_sum_pre_match" in df_yes.columns:
                    _xg_sum = _to_num(df_yes["xg_sum_pre_match"])
                    _conds.append(_xg_sum >= 2.4)

                if "over_25_percentage_pre_match" in df_yes.columns:
                    _o25 = _to_num(df_yes["over_25_percentage_pre_match"])
                    _o25 = _o25.where(_o25 <= 1.0, _o25 / 100.0)
                    _conds.append(_o25 >= 0.52)

                if "bookie_lambda_total_fit" in df_yes.columns:
                    _lam = _to_num(df_yes["bookie_lambda_total_fit"])
                    _conds.append(_lam >= 2.6)

                if have_rate_scored:
                    _sr_h = _to_num(df_yes["scored_rate_5_home"])
                    _sr_a = _to_num(df_yes["scored_rate_5_away"])
                    _conds.append((_sr_h >= float(btts_yes_scored_min)) & (_sr_a >= float(btts_yes_scored_min)))

                if have_rate_cs:
                    _cs_h = _to_num(df_yes["clean_sheet_rate_5_home"])
                    _cs_a = _to_num(df_yes["clean_sheet_rate_5_away"])
                    cs_risk = np.maximum(_cs_h, _cs_a)
                    _conds.append(cs_risk <= float(btts_yes_cs_max))

                if _conds:
                    ok = _conds[0]
                    for c in _conds[1:]:
                        ok = ok | c
                    confirmation_pass = ok.fillna(False)

                if debug:
                    print(f"[deploy_rulebook] BTTS(YES) after goaliness fallback n={int(confirmation_pass.sum())}")

            # Baseline live decision (pre-override)
            ge2_ok = ge2_pass.fillna(True)
            mf_ok = model_floor_pass.fillna(False)
            fts_ok = fts_pass.fillna(True)
            cs_ok = cs_pass.fillna(True)
            dbl_ok = double_blank_pass.fillna(True)
            conf_ok = confirmation_pass.fillna(False)

            baseline_live = label_pass & ge2_ok & mf_ok & fts_ok & cs_ok & dbl_ok & conf_ok

            df_yes["label_pass"] = label_pass.astype(int)
            df_yes["brazil_block"] = brazil_block_mask.astype(int)
            df_yes["ge2_pass"] = ge2_ok.astype(int)
            df_yes["model_floor_pass"] = mf_ok.astype(int)
            df_yes["fts_pass"] = fts_ok.astype(int)
            df_yes["cs_pass"] = cs_ok.astype(int)
            df_yes["double_blank_pass"] = dbl_ok.astype(int)
            df_yes["confirmation_pass"] = conf_ok.astype(int)
            df_yes["final_live_pass"] = baseline_live.astype(int)

            reason_col = "btts_yes_policy_reason"
            if reason_col not in df_yes.columns:
                df_yes[reason_col] = ""
            df_yes[reason_col] = df_yes.apply(lambda r: btts_yes_reason(r), axis=1)
            df_yes["final_live_pass"] = df_yes.apply(lambda r: int(btts_yes_is_live(r)), axis=1)

            df_yes = df_yes[df_yes["final_live_pass"].eq(1)].copy()
            return df_yes

        def _apply_btts_no_rules(df_no: pd.DataFrame) -> pd.DataFrame:
            """BTTS NO: require model floor and a low-goaliness / clean-sheet-risk style confirmation."""
            if df_no is None or df_no.empty:
                return df_no

            # Require STRONG / VERY_STRONG labels by default
            sig = df_no.get("signal_btts_runtime", df_no.get("signal_btts", pd.Series("", index=df_no.index))).astype("string").fillna("").str.strip().str.upper()
            df_no = df_no[sig.isin(["STRONG_NO","VERY_STRONG_NO"])].copy()
            if debug:
                print(f"[deploy_rulebook] BTTS(NO) after strong-label gate n={len(df_no)}")                    

            df_no_dbg = df_no.copy()

            # Require at least one blank plausible
            ph = pd.to_numeric(df_no.get("p_home_fts", np.nan), errors="coerce")
            pa = pd.to_numeric(df_no.get("p_away_fts", np.nan), errors="coerce")
            # NaN-safe max: if both NaN -> NaN; allow to pass this stage (do not block coverage)
            fts_max = pd.concat([ph, pa], axis=1).max(axis=1)
            df_no = df_no[(fts_max.isna()) | (fts_max >= 0.35)].copy()
            # ---------------------------------------------------------
            # BTTS NO: veto OU25 UNDER 1–1 trap fixtures
            # If OU25 UNDER indicates a strong 1-1 mode, BTTS NO is structurally risky.
            # Tunable via params: btts_no_veto_ou25_under_11_trap (default True)
            # ---------------------------------------------------------
            trap_veto_on = bool(params.get("btts_no_veto_ou25_under_11_trap", True))
            if trap_veto_on and ("__fixture_ou25_under_11_trap" in df_no.columns):
                before_tv = int(len(df_no))
                tv = pd.to_numeric(df_no["__fixture_ou25_under_11_trap"], errors="coerce").fillna(0).astype(int).ge(1)
                df_no = df_no.loc[~tv].copy()
                if debug:
                    try:
                        print(f"[deploy_rulebook] BTTS(NO) after 1-1-trap veto n={len(df_no)} (dropped={before_tv - len(df_no)})")
                    except Exception:
                        pass
            # BTTS NO purity gate: strong blank pressure + not-both-teams-2+ pressure
            # Balanced defaults:
            #   - require fts_max >= 0.50 (when present)
            #   - require ge2_sum <= 0.95 (when GE heads present)
            # Optional extra safety vs 1-1 traps (disabled by default):
            #   - require low-total regime: exp_goals_sum <= 2.55 OR p00_est >= 0.08
            ph = pd.to_numeric(df_no.get("p_home_fts", np.nan), errors="coerce")
            pa = pd.to_numeric(df_no.get("p_away_fts", np.nan), errors="coerce")
            fts_max2 = pd.concat([ph, pa], axis=1).max(axis=1)
            m_fts_purity = fts_max2.isna() | (fts_max2 >= float(btts_no_fts_min))

            have_ge2 = ("home_ge2_confidence" in df_no.columns) and ("away_ge2_confidence" in df_no.columns)
            m_ge2_purity = pd.Series(True, index=df_no.index)
            if have_ge2:
                ge2h = pd.to_numeric(df_no["home_ge2_confidence"], errors="coerce")
                ge2a = pd.to_numeric(df_no["away_ge2_confidence"], errors="coerce")
                ge2_sum = ge2h.fillna(0.0) + ge2a.fillna(0.0)
                # Fail-open on missing
                m_ge2_purity = ge2h.isna() | ge2a.isna() | (ge2_sum <= float(btts_no_ge2_sum_max))

            # Optional low-total confirmation
            m_low_total = pd.Series(True, index=df_no.index)
            if bool(btts_no_use_low_total_confirm):
                eg = pd.to_numeric(df_no.get("exp_goals_sum", np.nan), errors="coerce")
                p00 = pd.to_numeric(df_no.get("p00_est", np.nan), errors="coerce")
                m_low_total = (eg.isna() & p00.isna()) | (eg <= float(btts_no_low_total_max)) | (p00 >= float(btts_no_p00_min))

            m_purity = (m_fts_purity & m_ge2_purity & m_low_total).fillna(True)
            _pre_purity = int(len(df_no))
            df_no2 = df_no[m_purity].copy()

            # Fail-open if this would wipe all rows
            if (_pre_purity > 0) and df_no2.empty:
                if debug:
                    print("[deploy_rulebook] BTTS(NO) purity gate wiped all rows; skipping gate (fail-open)")
            else:
                df_no = df_no2

            if debug:
                try:
                    print(
                        "[deploy_rulebook] BTTS(NO) purity gate:",
                        {
                            "n_in": _pre_purity,
                            "kept": int(len(df_no)),
                            "dropped": int(_pre_purity - len(df_no)),
                            "btts_no_fts_min": float(btts_no_fts_min),
                            "have_ge2": bool(have_ge2),
                            "btts_no_ge2_sum_max": float(btts_no_ge2_sum_max),
                            "use_low_total": bool(btts_no_use_low_total_confirm),
                            "low_total_max": float(btts_no_low_total_max),
                            "p00_min": float(btts_no_p00_min),
                        },
                    )
                    cols_dbg = [c for c in (
                        "league","fixture_key","home_team_name","away_team_name","bookie_pick","bookie_od","model_p_for_bookie",
                        "p_home_fts","p_away_fts","home_ge2_confidence","away_ge2_confidence","exp_goals_sum","p00_est"
                    ) if c in df_no.columns]
                    if cols_dbg and (_pre_purity - len(df_no) > 0):
                        print("[deploy_rulebook] BTTS(NO) purity dropped sample:")
                        print(df_no.loc[~m_purity, cols_dbg].head(10).to_string(index=False))
                except Exception:
                    pass

            # 1) Model probability floor: p_model >= max(pmin_floor, implied_used - tol)
            _imp_used = _to_num(df_no.get("bookie_implied_used", df_no.get("bookie_implied")))
            _pm = _to_num(df_no.get("model_p_for_bookie"))
            _floor = np.maximum(float(btts_no_pmin_floor), _imp_used.fillna(0.0) - float(tol_btts_f))
            df_no = df_no[_pm.fillna(-1e9) >= _floor].copy()
            if debug:
                print(f"[deploy_rulebook] BTTS(NO) after model floor n={len(df_no)}")

            # Structural confirmation for BTTS NO using FTS heads (need at least one likely blank)
            if ("p_home_fts" in df_no.columns) and ("p_away_fts" in df_no.columns):
                ph = pd.to_numeric(df_no["p_home_fts"], errors="coerce")
                pa = pd.to_numeric(df_no["p_away_fts"], errors="coerce")
                m_fts_no = (ph.notna() & (ph >= float(fts_no_min))) | (pa.notna() & (pa >= float(fts_no_min)))
                # If both are NaN, fail-open (do not drop here)
                m_fts_no = m_fts_no | (ph.isna() & pa.isna())
                df_no = df_no[m_fts_no.fillna(True)].copy()
                if debug:
                    print(f"[deploy_rulebook] BTTS(NO) after FTS struct n={len(df_no)}")

            # 2) Low-goaliness confirmation (NO): keep if ANY low-goaliness signal passes
            _low = []

            if "average_goals_per_match_pre_match" in df_no.columns:
                _avg_g = _to_num(df_no["average_goals_per_match_pre_match"])
                _low.append(_avg_g <= 2.6)

            if "xg_sum_pre_match" in df_no.columns:
                _xg_sum = _to_num(df_no["xg_sum_pre_match"])
                _low.append(_xg_sum <= 2.4)

            if "over_25_percentage_pre_match" in df_no.columns:
                _o25 = _to_num(df_no["over_25_percentage_pre_match"])
                _o25 = _o25.where(_o25 <= 1.0, _o25 / 100.0)
                _low.append(_o25 <= 0.52)

            if "bookie_lambda_total_fit" in df_no.columns:
                _lam = _to_num(df_no["bookie_lambda_total_fit"])
                _low.append(_lam <= 2.6)

            if _low:
                ok_low = _low[0]
                for c in _low[1:]:
                    ok_low = ok_low | c
                df_no = df_no[ok_low.fillna(False)].copy()

            if debug:
                print(f"[deploy_rulebook] BTTS(NO) after low-goaliness n={len(df_no)}")

            # 3) Clean-sheet / blanking risk confirmation (uses future rate features if present)
            # If these columns exist, require either:
            #   - one side has meaningful clean-sheet tendency, OR
            #   - at least one side has poor scored-rate tendency.
            cs_cols = []
            if "clean_sheet_rate_5_home" in df_no.columns:
                cs_cols.append("clean_sheet_rate_5_home")
            if "clean_sheet_rate_5_away" in df_no.columns:
                cs_cols.append("clean_sheet_rate_5_away")

            sr_cols = []
            if "scored_rate_5_home" in df_no.columns:
                sr_cols.append("scored_rate_5_home")
            if "scored_rate_5_away" in df_no.columns:
                sr_cols.append("scored_rate_5_away")

            if cs_cols or sr_cols:
                cs_risk = None
                if cs_cols:
                    cs_vals = [_to_num(df_no[c]) for c in cs_cols]
                    cs_risk = cs_vals[0]
                    for s in cs_vals[1:]:
                        cs_risk = np.maximum(cs_risk, s)

                scored_floor = None
                if sr_cols:
                    sr_vals = [_to_num(df_no[c]) for c in sr_cols]
                    scored_floor = sr_vals[0]
                    for s in sr_vals[1:]:
                        scored_floor = np.minimum(scored_floor, s)

                # default thresholds (override via params dict if desired)
                cs_min = float(btts_no_cs_min)
                scored_max = float(btts_no_scored_max)

                m1 = (cs_risk >= cs_min) if cs_risk is not None else pd.Series(False, index=df_no.index)
                m2 = (scored_floor <= scored_max) if scored_floor is not None else pd.Series(False, index=df_no.index)

                conceded_floor = None
                if "conceded_rate_5_home" in df_no.columns and "conceded_rate_5_away" in df_no.columns:
                    c_h = _to_num(df_no["conceded_rate_5_home"])
                    c_a = _to_num(df_no["conceded_rate_5_away"])
                    conceded_floor = np.minimum(c_h, c_a)

                btts_floor = None
                if "btts_rate_5_home" in df_no.columns and "btts_rate_5_away" in df_no.columns:
                    br_h = _to_num(df_no["btts_rate_5_home"])
                    br_a = _to_num(df_no["btts_rate_5_away"])
                    btts_floor = np.minimum(br_h, br_a)

                m3 = (conceded_floor <= float(btts_no_conceded_max)) if conceded_floor is not None else pd.Series(False, index=df_no.index)
                m4 = (btts_floor <= float(btts_no_bttsrate_max)) if btts_floor is not None else pd.Series(False, index=df_no.index)

                # Rolling xG availability flags (must be defined before has_struct uses them)
                have_xg_for = ("xg_for_avg_5_home" in df_no.columns) and ("xg_for_avg_5_away" in df_no.columns)
                have_xg_against = ("xg_against_avg_5_home" in df_no.columns) and ("xg_against_avg_5_away" in df_no.columns)

                # New logic: If conceded/btts triggers exist, require at least one of them in addition to the legacy triggers.
                # This prevents m1|m2 from swallowing everything and makes btts_no_conceded_max / btts_no_bttsrate_max meaningful.
                has_struct = (conceded_floor is not None) or (btts_floor is not None) or have_xg_for or have_xg_against

                m_old = (m1 | m2)
                # Rolling xG trigger (when available): allow NO when at least one side is low-creating or low-conceding
                m5 = pd.Series(False, index=df_no.index)
                if have_xg_for:
                    xf_h = _to_num(df_no["xg_for_avg_5_home"])
                    xf_a = _to_num(df_no["xg_for_avg_5_away"])
                    xf_min = np.minimum(xf_h, xf_a)
                    m5 = m5 | (xf_min <= float(btts_no_xgfor_max))
                if have_xg_against:
                    xa_h = _to_num(df_no["xg_against_avg_5_home"])
                    xa_a = _to_num(df_no["xg_against_avg_5_away"])
                    xa_min = np.minimum(xa_h, xa_a)
                    m5 = m5 | (xa_min <= float(btts_no_xgagainst_max))
                m_new = (m3 | m4 | m5)

                # Debug block: show component counts
                if debug:
                    try:
                        print(
                            "[deploy_rulebook] BTTS(NO) cs/blank components: "
                            f"m1_cs={int(m1.fillna(False).sum())} "
                            f"m2_scored={int(m2.fillna(False).sum())} "
                            f"m3_conceded={int(m3.fillna(False).sum())} "
                            f"m4_bttsrate={int(m4.fillna(False).sum())} "
                            f"m5_xg={int(m5.fillna(False).sum())} "
                            f"has_struct={has_struct}"
                        )
                    except Exception:
                        pass

                if has_struct:
                    keep_mask = (m_old & m_new)
                else:
                    keep_mask = m_old

                df_no = df_no[keep_mask.fillna(False)].copy()

                if debug:
                    try:
                        po = float(m_old.fillna(False).mean())
                        pn = float(m_new.fillna(False).mean())
                        pb = float((m_old & m_new).fillna(False).mean())
                    except Exception:
                        po = pn = pb = float('nan')
                    print(f"[deploy_rulebook] BTTS(NO) trigger_frac old={po:.3f} new={pn:.3f} both={pb:.3f} has_struct={has_struct}")

            if debug:
                print(f"[deploy_rulebook] BTTS(NO) after cs/blanking risk n={len(df_no)}")
            # Optional H2H gate for BTTS NO
            if btts_no_h2h_max is not None and ("h2h_n" in df_no.columns) and ("h2h_btts_rate" in df_no.columns):
                hn = pd.to_numeric(df_no["h2h_n"], errors="coerce")
                hr = pd.to_numeric(df_no["h2h_btts_rate"], errors="coerce")
                m_h2h = (hn < float(h2h_min_n)) | (hr <= float(btts_no_h2h_max))
                df_no = df_no[m_h2h.fillna(False)].copy()
                if debug:
                    print(f"[deploy_rulebook] BTTS(NO) after H2H gate n={len(df_no)}")
            return df_no

        b_yes = _apply_btts_yes_rules(b_yes)
        b_no  = _apply_btts_no_rules(b_no)

        # Robust recombine (guards against None/empty)
        parts = [p for p in [b_yes, b_no, b_other] if isinstance(p, pd.DataFrame) and (not p.empty)]
        btts = pd.concat(parts, axis=0, ignore_index=True) if parts else btts.iloc[0:0].copy()

        if debug:
            ny = int(len(b_yes)) if isinstance(b_yes, pd.DataFrame) else -1
            nn = int(len(b_no)) if isinstance(b_no, pd.DataFrame) else -1
            no = int(len(b_other)) if isinstance(b_other, pd.DataFrame) else -1
            print(f"[deploy_rulebook] BTTS recombine yes={ny} no={nn} other={no} -> n={len(btts)}")


    # --- Team Goals markets (TG15/TG25) ---
    tg15 = out[out["market"].eq("tg15")].copy()
    tg25 = out[out["market"].eq("tg25")].copy()

    tg_enable_15 = bool(params.get("tg15_enable", True))
    tg_enable_25 = bool(params.get("tg25_enable", True))

    tg15_pmin = float(params.get("tg15_pmin", 0.65))
    tg25_pmin = float(params.get("tg25_pmin", 0.45))

    tg15_home_pmin = float(params.get("tg15_home_pmin", tg15_pmin))
    tg15_away_pmin = float(params.get("tg15_away_pmin", tg15_pmin))
    tg25_home_pmin = float(params.get("tg25_home_pmin", tg25_pmin))
    tg25_away_pmin = float(params.get("tg25_away_pmin", tg25_pmin))

    tg_ppg_diff_min = params.get("tg_ppg_diff_min", None)          # float or None
    tg_pd_min = params.get("tg_pd_min", None)          # float or None
    tg15_pd_min = params.get("tg15_pd_min", None)      # float or None
    tg25_pd_min = params.get("tg25_pd_min", None)      # float or None
    # Shared fallback (backward compatible)
    tg_xgfor_min = params.get("tg_xgfor_min", None)                # float or None

    # Per-market overrides
    tg15_xgfor_min = params.get("tg15_xgfor_min", None)            # float or None
    tg25_xgfor_min = params.get("tg25_xgfor_min", None)            # float or None

    tg_opp_xga_min = params.get("tg_opp_xga_min", None)            # float or None
    tg_opp_blank_min = params.get("tg_opp_blank_min", None)        # float or None (uses p_home_fts/p_away_fts)

    # Resolve effective xg_for thresholds (specific overrides take precedence)
    tg15_xgfor_thr = tg15_xgfor_min if tg15_xgfor_min is not None else tg_xgfor_min
    tg25_xgfor_thr = tg25_xgfor_min if tg25_xgfor_min is not None else tg_xgfor_min
    tg15_pd_thr = tg15_pd_min if tg15_pd_min is not None else tg_pd_min
    tg25_pd_thr = tg25_pd_min if tg25_pd_min is not None else tg_pd_min

    tg15_home_xgfor_thr = params.get("tg15_home_xgfor_min", tg15_xgfor_thr)
    tg15_away_xgfor_thr = params.get("tg15_away_xgfor_min", tg15_xgfor_thr)
    tg25_home_xgfor_thr = params.get("tg25_home_xgfor_min", tg25_xgfor_thr)
    tg25_away_xgfor_thr = params.get("tg25_away_xgfor_min", tg25_xgfor_thr)

    tg15_home_pd_thr = params.get("tg15_home_pd_min", tg15_pd_thr)
    tg15_away_pd_thr = params.get("tg15_away_pd_max", (-float(tg15_pd_thr) if tg15_pd_thr is not None else None))
    tg25_home_pd_thr = params.get("tg25_home_pd_min", tg25_pd_thr)
    tg25_away_pd_thr = params.get("tg25_away_pd_max", (-float(tg25_pd_thr) if tg25_pd_thr is not None else None))

    def _apply_tg_rules(df_tg: pd.DataFrame, pmin: float, label: str, xgfor_thr: Optional[float], pd_thr: Optional[float]) -> pd.DataFrame:
        if df_tg is None or df_tg.empty:
            return df_tg
        if debug:
            print(f"[deploy_rulebook] {label} start n={len(df_tg)}")

        # Helper for pick/flags
        def _tg_flags(frame: pd.DataFrame) -> tuple[pd.Series, pd.Series, pd.Series]:
            p = frame.get("bookie_pick", pd.Series("", index=frame.index))
            p = p.astype("string").fillna("").str.upper().str.strip()
            hf = p.str.contains(r"^HOME_", regex=True, na=False)
            af = p.str.contains(r"^AWAY_", regex=True, na=False)
            return p, hf, af

        # Always require agreement flag (tg rows are model-only, agree is set to 1 upstream)
        df_tg = df_tg[agree.loc[df_tg.index]].copy()
        if debug:
            print(f"[deploy_rulebook] {label} after agree n={len(df_tg)}")

        pm = pd.to_numeric(df_tg.get("model_p_for_bookie"), errors="coerce")
        df_tg = df_tg[pm.fillna(-1e9) >= float(pmin)].copy()
        if debug:
            print(f"[deploy_rulebook] {label} after pmin n={len(df_tg)}")

        # Require tg_pois_ok when present
        if "tg_pois_ok" in df_tg.columns:
            tgok = pd.to_numeric(df_tg["tg_pois_ok"], errors="coerce").fillna(0).astype(int)
            df_tg = df_tg[tgok.eq(1)].copy()
            if debug:
                print(f"[deploy_rulebook] {label} after tg_pois_ok==1 n={len(df_tg)}")

        pick, hf, af = _tg_flags(df_tg)

        side_home_pmin = float(params.get(f"{label.lower()}_home_pmin", pmin))
        side_away_pmin = float(params.get(f"{label.lower()}_away_pmin", pmin))
        side_pmin_mask = (
            (hf & pm.ge(side_home_pmin))
            | (af & pm.ge(side_away_pmin))
            | (~(hf | af) & pm.ge(float(pmin)))
        )
        df_tg = df_tg[side_pmin_mask.fillna(False)].copy()
        pick, hf, af = _tg_flags(df_tg)
        if debug:
            print(
                f"[deploy_rulebook] {label} after side pmin n={len(df_tg)} "
                f"(home_pmin={side_home_pmin:.3f}, away_pmin={side_away_pmin:.3f})"
            )

        # Poisson tail support for TG15 (team>=2)
        if "pois_home_ge2" in df_tg.columns and "pois_away_ge2" in df_tg.columns and label.upper().startswith("TG15"):
            ph2 = pd.to_numeric(df_tg["pois_home_ge2"], errors="coerce")
            pa2 = pd.to_numeric(df_tg["pois_away_ge2"], errors="coerce")
            ok_tail = (hf & (ph2 >= 0.50)) | (af & (pa2 >= 0.50)) | (~(hf|af))
            df_tg = df_tg[ok_tail.fillna(False)].copy()
            if debug:
                print(f"[deploy_rulebook] {label} after pois_ge2>=0.50 n={len(df_tg)}")

        # Opponent FTS veto (don’t take TG when match is suppression/blanky)
        ph_fts = pd.to_numeric(df_tg.get("p_home_fts", np.nan), errors="coerce")
        pa_fts = pd.to_numeric(df_tg.get("p_away_fts", np.nan), errors="coerce")
        opp_fts = pd.Series(np.nan, index=df_tg.index)
        # HOME_TG -> opponent is away -> use p_away_fts (away blank risk)
        opp_fts = opp_fts.mask(hf, pa_fts)
        # AWAY_TG -> opponent is home -> use p_home_fts
        opp_fts = opp_fts.mask(af, ph_fts)
        df_tg = df_tg[(opp_fts <= 0.30) | opp_fts.isna()].copy()

        # CS “1-0 magnet” veto (optional but strong)
        cs1 = df_tg.get("cs1", pd.Series("", index=df_tg.index)).astype("string").fillna("").str.strip()
        cs1p = pd.to_numeric(df_tg.get("cs1_p", np.nan), errors="coerce")
        veto_cs = ((cs1.isin(["1-0","0-1"])) & (cs1p >= 0.10)).fillna(False)
        df_tg = df_tg[~veto_cs].copy()

        pick, home_flag, away_flag = _tg_flags(df_tg)

        # Power mismatch (optional): HOME_* requires +power_diff, AWAY_* requires -power_diff
        home_pd_thr_local = params.get(f"{label.lower()}_home_pd_min", None)
        away_pd_thr_local = params.get(f"{label.lower()}_away_pd_max", None)
        if home_pd_thr_local is None:
            home_pd_thr_local = pd_thr
        if away_pd_thr_local is None:
            away_pd_thr_local = (-float(pd_thr) if pd_thr is not None else None)

        if ((home_pd_thr_local is not None) or (away_pd_thr_local is not None)) and ("power_diff" in df_tg.columns):
            pdiff = pd.to_numeric(df_tg["power_diff"], errors="coerce")

            m_home = pd.Series(True, index=df_tg.index)
            m_away = pd.Series(True, index=df_tg.index)

            if home_pd_thr_local is not None:
                m_home = pd.Series(pdiff >= float(home_pd_thr_local), index=df_tg.index)
            if away_pd_thr_local is not None:
                m_away = pd.Series(pdiff <= float(away_pd_thr_local), index=df_tg.index)

            mask = (home_flag & m_home.fillna(False)) | (away_flag & m_away.fillna(False))
            df_tg = df_tg[mask.fillna(False)].copy()
            pick, home_flag, away_flag = _tg_flags(df_tg)
            if debug:
                print(
                    f"[deploy_rulebook] {label} after power_diff n={len(df_tg)} "
                    f"(home_pd_min={home_pd_thr_local}, away_pd_max={away_pd_thr_local})"
                )

        # PPG dominance (optional): HOME picks require +diff, AWAY picks require -diff
        if tg_ppg_diff_min is not None and ("ppg_diff_pre" in df_tg.columns):
            ppgd = pd.to_numeric(df_tg["ppg_diff_pre"], errors="coerce")
            thr = float(tg_ppg_diff_min)
            m_home = (ppgd >= thr)
            m_away = (ppgd <= -thr)

            # Build an index-aligned mask (avoid numpy broadcasting / reindex warnings)
            m_home = pd.Series(m_home, index=df_tg.index).reindex(df_tg.index)
            m_away = pd.Series(m_away, index=df_tg.index).reindex(df_tg.index)
            mask = (home_flag & m_home.fillna(False)) | (away_flag & m_away.fillna(False))

            df_tg = df_tg[mask.fillna(False)].copy()
            pick, home_flag, away_flag = _tg_flags(df_tg)
            if debug:
                print(f"[deploy_rulebook] {label} after ppg n={len(df_tg)}")
                
        # Directional TG sanity gate (PPG + power_diff + optional opponent cap)
        # HOME_TG => ppg_diff_pre >= tg_ppg_home_min and (power_diff >= tg_pd_home_min when available)
        # AWAY_TG => ppg_diff_pre <= tg_ppg_away_max and (power_diff <= tg_pd_away_max when available)
        # Optional: opponent PPG <= tg_opp_ppg_max when available
        if bool(params.get("tg_use_dir_gate", False)):
            ppgd = pd.to_numeric(df_tg.get("ppg_diff_pre"), errors="coerce")
            pdiff = pd.to_numeric(df_tg.get("power_diff"), errors="coerce")
            p_home = pd.to_numeric(df_tg.get("ppg_home_pre"), errors="coerce")
            p_away = pd.to_numeric(df_tg.get("ppg_away_pre"), errors="coerce")

            tg_ppg_home_min = float(params.get("tg_ppg_home_min", 0.35))
            tg_ppg_away_max = float(params.get("tg_ppg_away_max", -0.35))
            tg_pd_home_min = float(params.get("tg_pd_home_min", 5.0))
            tg_pd_away_max = float(params.get("tg_pd_away_max", -5.0))
            tg_opp_ppg_max = float(params.get("tg_opp_ppg_max", 1.20))
            tg_ambig_delta = float(params.get("tg_ambig_delta", 0.05))

            # opponent PPG depends on TG side
            opp_ppg = pd.Series(np.nan, index=df_tg.index)
            opp_ppg.loc[home_flag] = p_away.loc[home_flag]
            opp_ppg.loc[away_flag] = p_home.loc[away_flag]

            # require ppg_diff to be present; power_diff is optional (only enforce when finite)
            m_home = home_flag & ppgd.notna() & (ppgd >= tg_ppg_home_min)
            m_away = away_flag & ppgd.notna() & (ppgd <= tg_ppg_away_max)

            if "power_diff" in df_tg.columns:
                m_home = m_home & (pdiff.isna() | (pdiff >= tg_pd_home_min))
                m_away = m_away & (pdiff.isna() | (pdiff <= tg_pd_away_max))

            # opponent cap when available
            m_home = m_home & (opp_ppg.isna() | (opp_ppg <= tg_opp_ppg_max))
            m_away = m_away & (opp_ppg.isna() | (opp_ppg <= tg_opp_ppg_max))

            df_tg = df_tg[(m_home | m_away).fillna(False)].copy()
            pick, home_flag, away_flag = _tg_flags(df_tg)

            if debug:
                print(f"[deploy_rulebook] {label} after DIR gate n={len(df_tg)}")

            # Keep only one TG side per fixture. If both sides exist and are near-tied, drop as ambiguous.
            if ("fixture_key" in df_tg.columns) and (not df_tg.empty):

                def _choose_group(g: pd.DataFrame) -> pd.DataFrame:
                    if g is None or g.empty:
                        return g
                    pp = pd.to_numeric(g.get("model_p_for_bookie"), errors="coerce")
                    g = g.assign(__p=pp)

                    gh = g[g["bookie_pick"].astype("string").str.upper().str.startswith("HOME_")]
                    ga = g[g["bookie_pick"].astype("string").str.upper().str.startswith("AWAY_")]

                    if (not gh.empty) and (not ga.empty):
                        ph = float(pd.to_numeric(gh["__p"], errors="coerce").max())
                        pa = float(pd.to_numeric(ga["__p"], errors="coerce").max())
                        if np.isfinite(ph) and np.isfinite(pa) and abs(ph - pa) < float(tg_ambig_delta):
                            return g.iloc[0:0].copy()  # ambiguous => drop all
                        if (not np.isfinite(pa)) or (np.isfinite(ph) and ph >= pa):
                            return gh.sort_values("__p", ascending=False).head(1).drop(columns=["__p"], errors="ignore")
                        return ga.sort_values("__p", ascending=False).head(1).drop(columns=["__p"], errors="ignore")

                    return g.sort_values("__p", ascending=False).head(1).drop(columns=["__p"], errors="ignore")

                df_tg = (
                    df_tg.groupby(["fixture_key"], as_index=False, group_keys=False)
                    .apply(_choose_group)
                    .reset_index(drop=True)
                )
        # Rolling xG for the picked team (optional)
        home_xgfor_thr_local = params.get(f"{label.lower()}_home_xgfor_min", xgfor_thr)
        away_xgfor_thr_local = params.get(f"{label.lower()}_away_xgfor_min", xgfor_thr)
        if (home_xgfor_thr_local is not None) or (away_xgfor_thr_local is not None):
            if ("xg_for_avg_5_home" in df_tg.columns) or ("xg_for_avg_5_away" in df_tg.columns):
                xh = pd.to_numeric(df_tg.get("xg_for_avg_5_home"), errors="coerce")
                xa = pd.to_numeric(df_tg.get("xg_for_avg_5_away"), errors="coerce")

                m_home = pd.Series(True, index=df_tg.index)
                m_away = pd.Series(True, index=df_tg.index)

                if home_xgfor_thr_local is not None:
                    m_home = pd.Series(xh >= float(home_xgfor_thr_local), index=df_tg.index).reindex(df_tg.index)
                if away_xgfor_thr_local is not None:
                    m_away = pd.Series(xa >= float(away_xgfor_thr_local), index=df_tg.index).reindex(df_tg.index)

                mask = (home_flag & m_home.fillna(False)) | (away_flag & m_away.fillna(False))

                df_tg = df_tg[mask.fillna(False)].copy()
                pick, home_flag, away_flag = _tg_flags(df_tg)
                if debug:
                    print(
                        f"[deploy_rulebook] {label} after xg_for n={len(df_tg)} "
                        f"(home_xgfor_min={home_xgfor_thr_local}, away_xgfor_min={away_xgfor_thr_local})"
                    )

        # Opponent xG-against (optional): require opponent concedes chances
        if tg_opp_xga_min is not None:
            thr = float(tg_opp_xga_min)
            if ("xg_against_avg_5_home" in df_tg.columns) or ("xg_against_avg_5_away" in df_tg.columns):
                # If pick is HOME_*, opponent is away -> use xg_against_avg_5_away
                opp_away_xga = pd.to_numeric(df_tg.get("xg_against_avg_5_away"), errors="coerce")
                # If pick is AWAY_*, opponent is home -> use xg_against_avg_5_home
                opp_home_xga = pd.to_numeric(df_tg.get("xg_against_avg_5_home"), errors="coerce")
                m_home = (opp_away_xga >= thr)
                m_away = (opp_home_xga >= thr)

                m_home = pd.Series(m_home, index=df_tg.index).reindex(df_tg.index)
                m_away = pd.Series(m_away, index=df_tg.index).reindex(df_tg.index)
                mask = (home_flag & m_home.fillna(False)) | (away_flag & m_away.fillna(False))

                df_tg = df_tg[mask.fillna(False)].copy()
                pick, home_flag, away_flag = _tg_flags(df_tg)
                if debug:
                    print(f"[deploy_rulebook] {label} after opp_xga n={len(df_tg)}")

        # Opponent blank-risk support (optional): strong mismatch proxy
        if tg_opp_blank_min is not None:
            thr = float(tg_opp_blank_min)
            if ("p_home_fts" in df_tg.columns) and ("p_away_fts" in df_tg.columns):
                ph = pd.to_numeric(df_tg["p_home_fts"], errors="coerce")
                pa = pd.to_numeric(df_tg["p_away_fts"], errors="coerce")
                # For HOME_* picks, opponent is away -> use p_away_fts
                m_home = (pa >= thr)
                # For AWAY_* picks, opponent is home -> use p_home_fts
                m_away = (ph >= thr)

                m_home = pd.Series(m_home, index=df_tg.index).reindex(df_tg.index)
                m_away = pd.Series(m_away, index=df_tg.index).reindex(df_tg.index)
                mask = (home_flag & m_home.fillna(False)) | (away_flag & m_away.fillna(False))

                df_tg = df_tg[mask.fillna(False)].copy()
                pick, home_flag, away_flag = _tg_flags(df_tg)
                if debug:
                    print(f"[deploy_rulebook] {label} after opp_blank n={len(df_tg)}")

        return df_tg

    if not tg_enable_15:
        tg15 = tg15.iloc[0:0].copy()
    if not tg_enable_25:
        tg25 = tg25.iloc[0:0].copy()

    tg15 = _apply_tg_rules(tg15, tg15_pmin, "TG15", tg15_xgfor_thr, tg15_pd_thr)
    tg25 = _apply_tg_rules(tg25, tg25_pmin, "TG25", tg25_xgfor_thr, tg25_pd_thr)

    # --- WTN market (derived) ---
    wtn = out.iloc[0:0].copy()
    if bool(params.get("enable_wtn", False)):
        wmin = float(params.get("wtn_score_min", 0.20))
        wtn_opp_ge2_max = float(params.get("wtn_opp_ge2_max", 0.35))

        # Build HOME_WTN and AWAY_WTN candidates from already-filtered FTR rows
        ftr_src = ftr.copy() if (isinstance(ftr, pd.DataFrame) and (not ftr.empty)) else out.iloc[0:0].copy()
        if not ftr_src.empty and ("home_wtn_score" in ftr_src.columns):
            hh = ftr_src.copy()
            hh["market"] = "wtn"
            hh["bookie_pick"] = "HOME_WTN"
            hh["model_p_for_bookie"] = pd.to_numeric(hh["home_wtn_score"], errors="coerce")
            hh["score"] = pd.to_numeric(hh["home_wtn_score"], errors="coerce")

            # WTN odds are not present in ALLMARKETS; do NOT reuse FTR odds/implied for ROI.
            for _c in ("bookie_od", "bookie_implied", "bookie_implied_used", "bookie_implied_novig", "bookie_overround", "bookie_spread"):
                if _c in hh.columns:
                    hh[_c] = np.nan

            # Opponent scoring veto: for HOME_WTN, away side GE2 support must be low
            if "away_ge2_confidence" in hh.columns:
                opp = pd.to_numeric(hh["away_ge2_confidence"], errors="coerce")
                hh = hh[opp.fillna(1e9) <= float(wtn_opp_ge2_max)].copy()
                if debug:
                    print(f"[deploy_rulebook] WTN(HOME) after opp_ge2 veto n={len(hh)}")

            hh = hh[hh["model_p_for_bookie"].fillna(-1.0) >= wmin].copy()

            aa = ftr_src.copy()
            aa["market"] = "wtn"
            aa["bookie_pick"] = "AWAY_WTN"
            aa["model_p_for_bookie"] = pd.to_numeric(aa["away_wtn_score"], errors="coerce")
            aa["score"] = pd.to_numeric(aa["away_wtn_score"], errors="coerce")

            # WTN odds are not present in ALLMARKETS; do NOT reuse FTR odds/implied for ROI.
            for _c in ("bookie_od", "bookie_implied", "bookie_implied_used", "bookie_implied_novig", "bookie_overround", "bookie_spread"):
                if _c in aa.columns:
                    aa[_c] = np.nan

            # Opponent scoring veto: for AWAY_WTN, home side GE2 support must be low
            if "home_ge2_confidence" in aa.columns:
                opp = pd.to_numeric(aa["home_ge2_confidence"], errors="coerce")
                aa = aa[opp.fillna(1e9) <= float(wtn_opp_ge2_max)].copy()
                if debug:
                    print(f"[deploy_rulebook] WTN(AWAY) after opp_ge2 veto n={len(aa)}")

            aa = aa[aa["model_p_for_bookie"].fillna(-1.0) >= wmin].copy()

            wtn = pd.concat([hh, aa], ignore_index=True)

        if debug:
            print(f"[deploy_rulebook] WTN enabled score_min={wmin:.3f} n={len(wtn)}")

    # Combine
    frames = [ftr, ou, btts, tg15, tg25, wtn]
    frames = [x for x in frames if isinstance(x, pd.DataFrame) and (not x.empty)]
    keep = pd.concat(frames, axis=0, ignore_index=True) if frames else out.iloc[0:0].copy()
    # Stamp canonical product identity early (before tiering / policy enforcement)
    # so downstream splits/merges preserve product_profile/product_lane.
    keep = _stamp_product_identity(keep, params=params)
    keep = _stamp_btts_priority(keep)
    keep = _stamp_phase7c_cross_market_candidates(keep)
    keep = _stamp_ftr_priority(keep)
    keep = _stamp_meta_priority(
        keep,
        meta_threshold=float(params.get("meta_threshold", 0.60)),
    )

    if keep.empty:
        return keep

    # Per-market cap (deterministic) — supports per-market overrides
    if bool(params.get("meta_priority_ordering", False)) and ("meta_priority_rank" in keep.columns):
        keep = keep.sort_values(
            ["market", "meta_priority_rank", "ftr_priority_rank", "btts_priority_rank", "score", "bookie_implied_used"],
            ascending=[True, False, False, False, False, False],
        )
    elif bool(params.get("ftr_priority_ordering", False)) and ("ftr_priority_rank" in keep.columns):
        keep = keep.sort_values(
            ["market", "ftr_priority_rank", "btts_priority_rank", "score", "bookie_implied_used"],
            ascending=[True, False, False, False, False],
        )
    else:
        keep = keep.sort_values(
            ["market", "btts_priority_rank", "score", "bookie_implied_used"],
            ascending=[True, False, False, False],
        )

    parts = []
    for mk, g in keep.groupby("market", sort=False):
        cap = int(cap_map.get(str(mk), int(max_per_market)))
        cap = max(0, cap)
        if cap == 0:
            continue
        parts.append(g.head(cap))

    keep = pd.concat(parts, axis=0, ignore_index=True) if parts else keep.iloc[0:0].copy()

    # Final stable ordering for readability
    keep = keep.sort_values(
        ["acca_builder_priority", "combo_overlay_priority", "market", "score", "bookie_implied_used"],
        ascending=[True, False, True, False, False],
    ).reset_index(drop=True)

    return keep


# -----------------------------
# Reporting
# -----------------------------


def _novig_coverage_table(df: pd.DataFrame) -> pd.DataFrame:
    if df is None or df.empty:
        return pd.DataFrame(columns=["market", "n", "novig_n", "novig_rate", "overround_n", "overround_rate"])

    mkt = _market_norm(_col(df, "market"))
    novig = _to_num(_col(df, "bookie_implied_novig")).notna()
    overround = _to_num(_col(df, "bookie_overround")).notna()

    rows = []
    for mk in sorted(mkt.dropna().unique().tolist()):
        idx = mkt.eq(mk)
        n = int(idx.sum())
        if n <= 0:
            continue
        nov_n = int(novig[idx].sum())
        ov_n = int(overround[idx].sum())
        rows.append({
            "market": mk,
            "n": n,
            "novig_n": nov_n,
            "novig_rate": nov_n / max(n, 1),
            "overround_n": ov_n,
            "overround_rate": ov_n / max(n, 1),
        })

    return pd.DataFrame(rows)


def _md_table(df: pd.DataFrame, cols: List[str], max_rows: int = 25) -> str:
    if df is None or df.empty:
        return "(no rows)\n"

    show = df.copy()
    cols2 = [c for c in cols if c in show.columns]
    show = show[cols2].head(max_rows).copy()

    # Basic formatting for markdown
    for c in [
        "bookie_od",
        "bookie_implied",
        "bookie_implied_novig",
        "bookie_implied_used",
        "bookie_overround",
        "bookie_spread",
        "model_p_for_bookie",
        "gap",
        "gap_novig",
        "gap_used",
        "ftr_margin",
        "power_diff",
        "home_power_rating",
        "away_power_rating",
        "model_strength",
        "score",
        "scored_rate_5_home",
        "scored_rate_5_away",
        "clean_sheet_rate_5_home",
        "clean_sheet_rate_5_away",
        "home_goals_pred",
        "away_goals_pred",
        "lambda_home",
        "lambda_away",
        "exp_goals_sum",
        "p00_est",
        "cs_home",
        "cs_away",
        "p_home_ge1",
        "p_away_ge1",
        "p_home_ge2",
        "p_away_ge2",
        "p_home_ge3",
        "p_away_ge3",
        "p_home_ge4",
        "p_away_ge4",
        "pois_home_ge2",
        "pois_away_ge2",
        "pois_home_ge3",
        "pois_away_ge3",
        "cs1_p",
        "cs2_p",
        "cs3_p",
        "p_home_pois",
        "p_draw_pois",
        "p_away_pois",
        "cs_trunc_mass_0_6",
    ]:
        if c in show.columns:
            show[c] = show[c].apply(lambda x: _fmt_float(x, 3))

    # Compose markdown
    header = "| " + " | ".join(cols2) + " |\n"
    sep = "| " + " | ".join(["---"] * len(cols2)) + " |\n"

    lines = [header, sep]
    for _, r in show.iterrows():
        row = []
        for c in cols2:
            v = r.get(c, "")
            if v is None:
                v = ""
            row.append(str(v))
        lines.append("| " + " | ".join(row) + " |\n")

    return "".join(lines)


def write_report_md(
    *,
    src_path: Path,
    out_csv_path: Path,
    df_in: pd.DataFrame,
    df_deploy: pd.DataFrame,
    params: Dict[str, Any],
) -> str:
    cov_in = _novig_coverage_table(df_in)
    cov_out = _novig_coverage_table(df_deploy)

    # Summary counts
    def _counts(d: pd.DataFrame) -> Dict[str, int]:
        if d is None or d.empty or "market" not in d.columns:
            return {}
        return d["market"].astype(str).str.lower().value_counts().to_dict()

    counts_in = _counts(df_in)
    counts_out = _counts(df_deploy)

    lines: List[str] = []
    preset_name = str(params.get("preset_name", "V1")).strip() or "V1"
    lines.append(f"# Deploy Preset {preset_name}\n\n")
    lines.append(f"**Source:** `{src_path}`\n\n")
    lines.append(f"**Output CSV:** `{out_csv_path}`\n\n")

    # Audit note: legacy OU25 signal fallback (historical mixed-schema exports)
    try:
        _df_note = None
        # Prefer deploy-input/candidate frame if available in this scope; otherwise use the report frame.
        # Keep this defensive because different report paths may name the input frame differently.
        for _cand in (locals().get("df_in"), locals().get("df_raw"), locals().get("df_g"), locals().get("df"), locals().get("deploy")):
            if isinstance(_cand, pd.DataFrame):
                _df_note = _cand
                break

        if _has_legacy_ou25_signal_fallback(_df_note):
            lines.append("> Note: legacy OU25 signal column `signal_ou25` detected; rulebook fallback applied.\n\n")
    except Exception:
        pass

    lines.append("## Params\n\n")
    for k in sorted(params.keys()):
        lines.append(f"- `{k}` = `{params[k]}`\n")
    lines.append("\n")

    lines.append("## No-vig coverage\n\n")
    lines.append("### Input file\n\n")
    if cov_in.empty:
        lines.append("(no coverage info)\n\n")
    else:
        lines.append(_md_table(cov_in, ["market", "n", "novig_n", "novig_rate", "overround_n", "overround_rate"], max_rows=50))
        lines.append("\n")

    lines.append("### Deploy output\n\n")
    if cov_out.empty:
        lines.append("(no coverage info)\n\n")
    else:
        lines.append(_md_table(cov_out, ["market", "n", "novig_n", "novig_rate", "overround_n", "overround_rate"], max_rows=50))
        lines.append("\n")

    # If missing novig, show league breakdown
    if "bookie_implied_novig" in df_in.columns and (df_in["bookie_implied_novig"].notna().mean() < 0.90):
        lines.append("## Missing no-vig by league\n\n")
        tmp = df_in.copy()
        tmp["market"] = tmp["market"].astype(str).str.lower()
        tmp["_novig_ok"] = pd.to_numeric(tmp["bookie_implied_novig"], errors="coerce").notna()
        grp = (
            tmp.groupby(["market", "league"], dropna=False)["_novig_ok"]
            .agg(["count", "mean"])
            .reset_index()
            .rename(columns={"count": "n", "mean": "novig_rate"})
            .sort_values(["market", "novig_rate", "n"], ascending=[True, True, False])
        )
        lines.append(_md_table(grp, ["market", "league", "n", "novig_rate"], max_rows=80))
        lines.append("\n")

    lines.append("## Counts\n\n")
    lines.append(f"- Input rows: **{len(df_in)}** | markets: `{counts_in}`\n")
    lines.append(f"- Deploy rows: **{len(df_deploy)}** | markets: `{counts_out}`\n")
    lines.append(f"- BTTS deployment policy: {BTTS_POLICY_NOTE}\n")
    

    lines.append("## Profit-first live book tags\n\n")
    review_btts = params.get("profit_first_btts_review_leagues", ["Brazil Serie A", "Europa League", "Belgium Pro"])
    keep_btts = params.get("profit_first_btts_keep_priority_leagues", ["Japan J1", "Netherlands Eredivisie", "Europa Conference"])
    keep_ftr = params.get("profit_first_ftr_keep_priority_leagues", ["Portugal Liga", "Italy Serie A", "England Championship", "USA MLS"])
    lines.append(f"- BTTS review leagues: `{review_btts}`\n")
    lines.append(f"- BTTS priority keep leagues: `{keep_btts}`\n")
    lines.append(f"- FTR priority keep leagues: `{keep_ftr}`\n\n")

    lines.append("## STANDARD Reporting Buckets\n\n")
    if isinstance(df_deploy, pd.DataFrame) and (not df_deploy.empty):
        if "standard_reporting_bucket" in df_deploy.columns:
            bucket_counts = (
                df_deploy.loc[
                    df_deploy.get("deploy_tier", pd.Series("", index=df_deploy.index))
                    .astype("string")
                    .fillna("")
                    .str.upper()
                    .eq("STANDARD"),
                    "standard_reporting_bucket",
                ]
                .astype("string")
                .fillna("STANDARD_OTHER")
                .value_counts(dropna=False)
            )
            if len(bucket_counts) == 0:
                lines.append("(no STANDARD rows)\n\n")
            else:
                for _bucket, _count in bucket_counts.items():
                    lines.append(f"- {_bucket}: {int(_count)}\n")
                lines.append("\n")
        else:
            lines.append("(standard_reporting_bucket not present)\n\n")
    else:
        lines.append("(no deploy rows)\n\n")

    lines.append("## Profit-first bucket counts\n\n")
    if isinstance(df_deploy, pd.DataFrame) and (not df_deploy.empty):
        if "profit_first_bucket" in df_deploy.columns:
            pf_counts = (
                df_deploy["profit_first_bucket"]
                .astype("string")
                .fillna("NON_PROFIT_FIRST")
                .value_counts(dropna=False)
            )
            lines.append("")
            for _bucket, _count in pf_counts.items():
                lines.append(f"- {_bucket}: {int(_count)}")
                lines.append("\n")
            lines.append("\n")


    # Per-market sections
    cols_common = [
        "league",
        "match_date",
        "home_team_name",
        "away_team_name",
        "fixture_key",
        "market",
        "bookie_pick",
        "bookie_od",
        "bookie_implied",
        "bookie_implied_novig",
        "bookie_implied_used",
        "bookie_overround",
        "bookie_spread",
        "model_top_pick",
        "model_p_for_bookie",
        "gap",
        "gap_novig",
        "gap_used",
        "ftr_margin",
        "home_power_rating",
        "away_power_rating",
        "power_diff",
        "model_strength",
        "score",
        "average_goals_per_match_pre_match",
        "xg_sum_pre_match",
        "over_25_percentage_pre_match",
        "bookie_lambda_total_fit",
        # Optional diagnostics
        "scored_rate_5_home",
        "scored_rate_5_away",
        "clean_sheet_rate_5_home",
        "clean_sheet_rate_5_away",
        "home_goals_pred",
        "away_goals_pred",
        "lambda_home",
        "lambda_away",
        "exp_goals_sum",
        "p00_est",
        "cs_home",
        "cs_away",
        "p_home_ge1",
        "p_away_ge1",
        "p_home_ge2",
        "p_away_ge2",
        "p_home_ge3",
        "p_away_ge3",
        "p_home_ge4",
        "p_away_ge4",
        "pois_home_ge2",
        "pois_away_ge2",
        "pois_home_ge3",
        "pois_away_ge3",
        "cs1",
        "cs1_p",
        "cs2",
        "cs2_p",
        "cs3",
        "cs3_p",
        "p_home_pois",
        "p_draw_pois",
        "p_away_pois",
        "cs_trunc_mass_0_6",
        "deploy_tier",
        "tier",
        "context_reason_codes",
        "standard_reporting_bucket",
        "profit_first_bucket",
        "profit_first_keep",
        "profit_first_review_reason",
    ]

    for mk in ["ftr", "ou25", "btts", "tg15", "tg25", "wtn"]:
        # Defensive: some fallback outputs may not contain derived sort columns
        if (df_deploy is None) or df_deploy.empty:
            sub = pd.DataFrame()
        else:
            if "market" in df_deploy.columns:
                sub = df_deploy[df_deploy["market"].astype(str).str.lower().eq(mk)].copy()
            else:
                sub = pd.DataFrame()

        lines.append(f"## {mk.upper()}\n\n")
        if sub.empty:
            lines.append("(no rows)\n\n")
            continue

        # Ensure `bookie_implied_used` exists for consistent sorting
        if "bookie_implied_used" not in sub.columns:
            imp_nv = pd.to_numeric(sub.get("bookie_implied_novig", np.nan), errors="coerce")
            imp_raw = pd.to_numeric(sub.get("bookie_implied", np.nan), errors="coerce")
            sub["bookie_implied_used"] = imp_nv.where(imp_nv.notna(), imp_raw)

        # Ensure `score` exists for consistent sorting
        if "score" not in sub.columns:
            gu = pd.to_numeric(sub.get("gap_used", np.nan), errors="coerce")
            if gu.notna().any():
                sub["score"] = gu
            else:
                sub["score"] = pd.to_numeric(sub.get("model_p_for_bookie", np.nan), errors="coerce")

        # Robust sorting: some fallback outputs may miss score/bookie_implied_used.
        # Derive them defensively so markdown generation never crashes.
        if "bookie_implied_used" not in sub.columns:
            nv = pd.to_numeric(sub.get("bookie_implied_novig", np.nan), errors="coerce")
            raw = pd.to_numeric(sub.get("bookie_implied", np.nan), errors="coerce")

            # If get() returned scalars, broadcast them to the index
            if not isinstance(nv, pd.Series):
                nv = pd.Series(nv, index=sub.index)
            if not isinstance(raw, pd.Series):
                raw = pd.Series(raw, index=sub.index)

            sub["bookie_implied_used"] = nv.where(nv.notna(), raw)

        if "score" not in sub.columns:
            if "gap_used" in sub.columns:
                sub["score"] = pd.to_numeric(sub["gap_used"], errors="coerce")
            elif "model_p_for_bookie" in sub.columns:
                sub["score"] = pd.to_numeric(sub["model_p_for_bookie"], errors="coerce")
            else:
                sub["score"] = np.nan

        sort_cols = [c for c in ("score", "bookie_implied_used") if c in sub.columns]
        if sort_cols:
            sub = sub.sort_values(sort_cols, ascending=[False] * len(sort_cols))

        lines.append(_md_table(sub, cols_common, max_rows=25))
        lines.append("\n")

    return "".join(lines)

def _alias_specialist_head_probs(df: pd.DataFrame, *, debug: bool = False) -> pd.DataFrame:
    """Add canonical alias columns for specialist head probabilities.

    Canonical:
      - p_home_ge2, p_away_ge2
      - p_home_ge3, p_away_ge3
      - p_btts_fh

    Source (from bookie_allmarkets today):
      - home_ge2_confidence, away_ge2_confidence
      - home_ge3_confidence, away_ge3_confidence
      - btts_fh_confidence
    """
    if df is None or df.empty:
        return df

    out = df.copy()

    mapping = {
        "p_home_ge2": "home_ge2_confidence",
        "p_away_ge2": "away_ge2_confidence",
        "p_home_ge3": "home_ge3_confidence",
        "p_away_ge3": "away_ge3_confidence",
        "p_btts_fh":  "btts_fh_confidence",
    }

    made = []
    for dst, src in mapping.items():
        if dst in out.columns:
            continue
        if src in out.columns:
            out[dst] = pd.to_numeric(out[src], errors="coerce").clip(0.0, 1.0)
            made.append(dst)

    if debug and made:
        print(f"[deploy_rulebook] specialist head aliases added: {made}")

    return out
