    ap.add_argument("--ftr-h2h-draw-veto-min", type=float, default=None,
                    help="Optional: veto non-DRAW picks when H2H looks draw-ish (proxy) and h2h_n>=min.")
    
    # FTR PPG dominance confirms (pre-match)
    ap.add_argument("--ftr-ppg-diff-home-min", type=float, default=0.45,
                    help="If pick==HOME require ppg_diff_pre >= this (default: 0.45).")
